/// Per-tick context passed to Lua callbacks via `Lua::set_app_data`.
pub struct ScriptTickData {
    pub runner: *mut ScriptRunner,
    pub state: *mut AppState,
    pub synthetic: *mut SyntheticInput,
    pub viewport: Option<egui::Rect>,
    pub ctx: *mut egui::Context,
}

unsafe impl Send for ScriptTickData {}
unsafe impl Sync for ScriptTickData {}

impl ScriptTickData {
    pub(crate) unsafe fn runner(&self) -> &mut ScriptRunner {
        &mut *self.runner
    }

    pub(crate) unsafe fn state(&self) -> &mut AppState {
        &mut *self.state
    }

    pub(crate) unsafe fn synthetic(&self) -> &mut SyntheticInput {
        &mut *self.synthetic
    }

    pub(crate) unsafe fn egui_ctx(&self) -> &egui::Context {
        &*self.ctx
    }

    pub(crate) unsafe fn exec(&self, instr: Instruction) -> mlua::Result<Created> {
        let runner = self.runner();
        runner.last_action_error = None;
        let before = created_snapshot(&self.state().doc);
        let result = runner.execute_instruction(
            instr,
            self.state(),
            self.synthetic(),
            self.viewport,
            self.egui_ctx(),
        );
        // "Not yet — try next frame", which is what the runner means by `Wait`. Dropping it
        // here silently skipped the instruction (#1814); the Lua wrappers yield and call
        // again while this is set.
        runner.last_deferred = matches!(result, StepResult::Wait);
        // Declarative modeling instructions record their action's rejection in
        // `last_action_error` (#104/#109/#110/#112): raise it so invalid input fails the
        // script (catchable with `pcall`) instead of silently succeeding with nothing
        // created. The GUI sees the same message through the status bar.
        match runner.last_action_error.take() {
            Some(e) => Err(mlua::Error::external(e)),
            None => {
                let created = created_since(&before, &self.state().doc);
                runner.last_created = created.clone();
                Ok(Created(created))
            }
        }
    }
}

/// The kinds a call hands back what it made, most useful first (#1801). A solid operation
/// records an operation *and* produces a body, and the body is what a script goes on to build
/// with, so bodies win. Sketch geometry comes next — a `rect` is its four lines. The
/// containers a call can open on your behalf come last: the sketch `circle` auto-opened is not
/// what `circle` created.
const CREATED_TIERS: &[&[&str]] = &[
    &["body"],
    &["shape"],
    &["edge_treatment_op", "sketch_vertex_treatment_op"],
    &["line", "circle", "sketch_text"],
    &["plane"],
    &["sketch"],
    &["drawing", "cross_section", "component", "joint", "image"],
    &["constraint", "parameter"],
];

/// What a script gets back from a call: the elements it created, or nothing.
pub struct Created(Vec<SceneElement>);

impl mlua::IntoLua for Created {
    fn into_lua(self, lua: &Lua) -> mlua::Result<Value> {
        let mut made = self.0.into_iter();
        let Some(first) = made.next() else {
            return Ok(Value::Nil);
        };
        let Some(second) = made.next() else {
            // One element is handed back on its own, so `local box = bearcad.extrude{…}` reads
            // the way it should; several come back as a list.
            return make_element(lua, first);
        };
        let out = lua.create_table()?;
        for (i, element) in [first, second].into_iter().chain(made).enumerate() {
            out.set(i + 1, make_element(lua, element)?)?;
        }
        Ok(Value::Table(out))
    }
}

/// The elements of every [`CREATED_TIERS`] kind, tier by tier — what a call is measured
/// against to see what it made.
fn created_snapshot(doc: &crate::model::Document) -> Vec<std::collections::HashSet<SceneElement>> {
    CREATED_TIERS
        .iter()
        .map(|tier| tier.iter().flat_map(|kind| elements_of_kind(doc, kind)).collect())
        .collect()
}

/// The elements that appeared since `before`, from the highest tier that gained any — in
/// creation order, which is the order their arena hands them back.
fn created_since(
    before: &[std::collections::HashSet<SceneElement>],
    doc: &crate::model::Document,
) -> Vec<SceneElement> {
    for (tier, was) in CREATED_TIERS.iter().zip(before) {
        let new: Vec<SceneElement> = tier
            .iter()
            .flat_map(|kind| elements_of_kind(doc, kind))
            .filter(|element| !was.contains(element))
            .collect();
        if !new.is_empty() {
            return new;
        }
    }
    Vec::new()
}

/// A reference to a scene element used by Lua scripts — the stable handle a creation call
/// hands back (#1801). It holds the element's arena key, so it names the same element for as
/// long as that element exists, however its ordinal moves.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct LuaElement {
    pub element: SceneElement,
    /// The ordinal the handle was made at. Only a fallback: `index()` re-reads the live
    /// document, because that is the whole point of holding a handle (#1801).
    pub index: usize,
}

impl LuaElement {
    /// The element's ordinal among the live ones of its kind, read from the document now —
    /// `None` once the element is gone.
    fn live_index(&self, lua: &Lua) -> Option<usize> {
        let tick = lua.app_data_ref::<ScriptTickData>()?;
        crate::hierarchy::element_live_index(unsafe { &tick.state().doc }, &self.element)
    }
}

impl UserData for LuaElement {
    fn add_methods<M: UserDataMethods<Self>>(methods: &mut M) {
        methods.add_method("kind", |_, this, ()| Ok(element_kind_name(this.element.clone())));
        methods.add_method("index", |lua, this, ()| {
            this.live_index(lua).ok_or_else(|| {
                mlua::Error::external(format!(
                    "{} no longer exists",
                    crate::hierarchy::element_id(&this.element)
                        .unwrap_or_else(|| element_kind_name(this.element.clone()).to_string())
                ))
            })
        });
        // The document-unique, never-reused id (#1801) — the string form of the handle, safe
        // to print, store, and hand back to `bearcad.element`.
        methods.add_method("id", |_, this, ()| {
            crate::hierarchy::element_id(&this.element).ok_or_else(|| {
                mlua::Error::external(format!(
                    "a {} reference has no id of its own",
                    element_kind_name(this.element.clone())
                ))
            })
        });
        methods.add_method("exists", |lua, this, ()| Ok(this.live_index(lua).is_some()));
        // #1878: delete this element without requiring or replacing the scene selection.
        methods.add_method("delete", |lua, this, ()| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe {
                tick.exec(Instruction::DeleteElements {
                    elements: vec![this.element.clone()],
                })
            }
        });
        // #1866: a line handle names its endpoints without the reserved-word `end` key.
        methods.add_method("start", |lua, this, ()| line_endpoint_handle(lua, this, LineEnd::Start));
        methods.add_method("endpoint", |lua, this, which: String| {
            line_endpoint_handle(lua, this, parse_line_end_name(&which)?)
        });
        methods.add_method("name", |lua, this, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            Ok(crate::names::element_name(unsafe { &tick.state().doc }, this.element.clone())
                .map(str::to_string))
        });
        // #1882: inspect without spelling kind/index; `get` is the inverse of create.
        methods.add_method("get", |lua, this, ()| lua_handle_get(lua, this));
        methods.add_method("stats", |lua, this, ()| {
            if !matches!(this.element, SceneElement::Body(_)) {
                return Err(mlua::Error::external("stats() is for bodies"));
            }
            if this.live_index(lua).is_none() {
                return Ok(Value::Nil);
            }
            let bearcad: Table = lua.globals().get("bearcad")?;
            let stats: mlua::Function = bearcad.get("body_stats")?;
            stats.call::<Value>(lua.create_userdata(this.clone())?)
        });
        methods.add_method("select", |lua, this, additive: Option<bool>| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe {
                tick.exec(Instruction::SelectSceneElement {
                    element: this.element.clone(),
                    additive: additive.unwrap_or(false),
                })
            }
        });
        // #1871: `box:face("top")` is the same object `body_faces` lists — begin_sketch,
        // extrude_face, and fillet/chamfer all accept it.
        methods.add_method("face", |lua, this, name: String| {
            let key = match this.element {
                SceneElement::Body(key) => key,
                SceneElement::Shape(pi) => {
                    let tick = lua
                        .app_data_ref::<ScriptTickData>()
                        .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
                    crate::model::body_index_for_primitive(unsafe { &tick.state().doc }, pi)
                        .ok_or_else(|| mlua::Error::external("shape has no body"))?
                }
                _ => return Err(mlua::Error::external("face() is for bodies")),
            };
            named_body_face_table(lua, key, &name)
        });
        methods.add_meta_method(mlua::MetaMethod::ToString, |_, this, ()| {
            Ok(crate::hierarchy::element_id(&this.element)
                .unwrap_or_else(|| element_kind_name(this.element.clone()).to_string()))
        });
        methods.add_meta_method(mlua::MetaMethod::Eq, |_, this, other: mlua::AnyUserData| {
            Ok(other
                .borrow::<LuaElement>()
                .is_ok_and(|other| other.element == this.element))
        });
    }
}

/// One element operand (#1801): the plain ordinal scripts have always written, or a stable
/// handle (what a creation call returns), or that handle's id string, or an element's name.
/// A handle resolves against the live document at the moment of the call — which is the point,
/// since ordinals shift when elements are deleted or consumed by an operation.
pub struct Ordinal(pub usize);

/// The ground-plane display an option key names (#1936): one of the documented strings, or
/// a boolean — `false` is what a script reaches for first when it wants a clean render, and
/// `true` puts the grid back. A bad value names every accepted one instead of leaking Rust's
/// "error converting Lua boolean to String".
fn parse_ground_display(value: Value, call: &str) -> mlua::Result<GroundDisplay> {
    match value {
        Value::Boolean(true) => Ok(GroundDisplay::Grid),
        Value::Boolean(false) => Ok(GroundDisplay::None),
        Value::String(ref s) => {
            let name = s.to_str()?.to_string();
            GroundDisplay::from_name(&name).ok_or_else(|| {
                mlua::Error::external(format!(
                    "{call}: unknown ground display '{name}' \
                     (grid, solid, none/off, or a boolean)"
                ))
            })
        }
        ref other => Err(mlua::Error::external(format!(
            "{call}: ground must be grid, solid, none/off, or a boolean, got {}",
            describe_lua_value(other)
        ))),
    }
}

/// One material as a script reads it (#1943): its name, its color as the `#rrggbb` the
/// `material` verb takes, and whether it is one of the stock palette a fresh document
/// starts with — the names `material{ name, color }` refuses to reuse.
fn material_table(
    lua: &Lua,
    index: usize,
    material: &crate::model::Material,
) -> mlua::Result<Table> {
    let t = lua.create_table()?;
    t.set("index", index)?;
    t.set("name", material.name.as_str())?;
    let [r, g, b] = material.color;
    t.set("color", format!("#{r:02x}{g:02x}{b:02x}"))?;
    t.set(
        "stock",
        crate::model::Material::DEFAULTS
            .iter()
            .any(|(name, color)| *name == material.name && *color == material.color),
    )?;
    Ok(t)
}

/// How a rejected argument reads back in an error (#1933): Lua's own type name, and the
/// handle's id when the value *is* a BearCAD handle — never the raw `AnyUserData(Ref(0x…))`
/// debug form, which tells a script author nothing.
fn describe_lua_value(value: &Value) -> String {
    if let Value::UserData(ud) = value {
        if let Ok(el) = ud.borrow::<LuaElement>() {
            return crate::hierarchy::element_id(&el.element)
                .unwrap_or_else(|| element_kind_name(el.element.clone()).to_string());
        }
    }
    match value {
        Value::String(s) => format!("string '{}'", s.to_string_lossy()),
        Value::Table(_) => "a table".to_string(),
        Value::Nil => "nil".to_string(),
        other => format!("a {}", other.type_name()),
    }
}

impl mlua::FromLua for Ordinal {
    fn from_lua(value: Value, lua: &Lua) -> mlua::Result<Self> {
        match value {
            Value::Integer(i) if i >= 0 => Ok(Ordinal(i as usize)),
            Value::Number(n) if n >= 0.0 && n.fract() == 0.0 => Ok(Ordinal(n as usize)),
            Value::UserData(ref ud) => {
                let element = ud
                    .borrow::<LuaElement>()
                    .map_err(|_| mlua::Error::external("expected an element, index, or name"))?
                    .clone();
                ordinal_of_element(lua, &element.element)
            }
            Value::String(ref s) => {
                let text = s.to_str()?.to_string();
                let element = resolve_element(lua, value.clone())
                    .map_err(|_| mlua::Error::external(format!("no element '{text}'")))?;
                ordinal_of_element(lua, &element)
            }
            ref other => Err(mlua::Error::external(format!(
                "expected an index, an element handle, or a name, got {}",
                describe_lua_value(other)
            ))),
        }
    }
}

/// The live ordinal of an element a handle names, or a clear error once it is gone.
fn ordinal_of_element(lua: &Lua, element: &SceneElement) -> mlua::Result<Ordinal> {
    let tick = lua
        .app_data_ref::<ScriptTickData>()
        .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
    crate::hierarchy::element_live_index(unsafe { &tick.state().doc }, element)
        .map(Ordinal)
        .ok_or_else(|| {
            mlua::Error::external(format!(
                "{} no longer exists",
                crate::hierarchy::element_id(element)
                    .unwrap_or_else(|| element_kind_name(element.clone()).to_string())
            ))
        })
}

/// Reading element operands out of an options table (#1801). Each takes an ordinal, a handle,
/// an id, or a name — whichever the script wrote — and yields the ordinal the instruction
/// layer wants, resolved against the document as it stands right now.
trait Operands {
    /// One operand; `None` when the key is absent.
    fn ordinal_opt(&self, key: &str) -> mlua::Result<Option<usize>>;
    /// A list of operands; empty when the key is absent.
    fn ordinal_list(&self, key: &str) -> mlua::Result<Vec<usize>>;
    /// The same, but telling an absent key from an empty list — some verbs branch on that.
    fn ordinal_list_opt(&self, key: &str) -> mlua::Result<Option<Vec<usize>>>;
    /// One operand the verb cannot do without.
    fn ordinal_req(&self, key: &str) -> mlua::Result<usize>;
}

impl Operands for Table {
    fn ordinal_opt(&self, key: &str) -> mlua::Result<Option<usize>> {
        Ok(self.get::<Option<Ordinal>>(key)?.map(|o| o.0))
    }

    fn ordinal_list(&self, key: &str) -> mlua::Result<Vec<usize>> {
        Ok(self.ordinal_list_opt(key)?.unwrap_or_default())
    }

    fn ordinal_list_opt(&self, key: &str) -> mlua::Result<Option<Vec<usize>>> {
        Ok(self
            .get::<Option<Vec<Ordinal>>>(key)?
            .map(|list| list.into_iter().map(|o| o.0).collect()))
    }

    fn ordinal_req(&self, key: &str) -> mlua::Result<usize> {
        Ok(self.get::<Ordinal>(key)?.0)
    }
}

/// A name for a **face** element, which nothing else distinguishes (#987/#988): every face
/// reports kind `face` and index `0`, so a hover flickering between a body's near face and the
/// one hidden behind it — or a fan offering both — read as identical from a script. That is how
/// both bugs went unnoticed. `None` for anything that isn't a face.
fn face_element_label(doc: &crate::model::Document, element: &SceneElement) -> Option<String> {
    match element {
        SceneElement::SketchFace(face) => Some(crate::face::face_label(doc, face.clone())),
        SceneElement::BodyFace { body, centroid, .. } => Some(format!(
            "Body {} face at ({:.3}, {:.3}, {:.3})",
            body.index(),
            centroid[0] as f32 / 1000.0,
            centroid[1] as f32 / 1000.0,
            centroid[2] as f32 / 1000.0
        )),
        _ => None,
    }
}

/// The script-facing kind name of an Elements-pane row (#1670). Most rows are a scene
/// element; the few display-only ones (the document root, the Drawings section, a unit's
/// read-only contents) name themselves.
fn hierarchy_node_kind_name(node: crate::hierarchy::HierarchyNode) -> &'static str {
    use crate::hierarchy::HierarchyNode as N;
    if let Some(element) = crate::hierarchy::scene_element_for_node(node) {
        return element_kind_name(element);
    }
    match node {
        N::Document => "document",
        N::Drawings => "drawings",
        N::Drawing(_) => "drawing",
        N::DrawingProjection { .. } => "projection",
        N::DrawingAnnotation { .. } => "annotation",
        N::DrawingDimension { .. } | N::DrawingPointDim { .. } => "drawing_dimension",
        N::DrawingLoupe { .. } => "drawing_loupe",
        N::EdgeTreatment { .. } => "edge_treatment",
        N::UnitChild { .. } => "unit_child",
        N::Views => "views",
        _ => "element",
    }
}

fn element_kind_name(element: SceneElement) -> &'static str {
    match element {
        SceneElement::ConstructionPlane(_) => "plane",
        SceneElement::CrossSection(_) => "cross_section",
        SceneElement::SectionPlane { .. } => "section_plane",
        SceneElement::Sketch(_) => "sketch",
        SceneElement::Line(_) => "line",
        SceneElement::Circle(_) => "circle",
        SceneElement::Constraint(_) => "constraint",
        SceneElement::Parameter(_) => "parameter",
        SceneElement::Point(_) => "point",
        SceneElement::Extrusion(_) => "extrusion",
        SceneElement::Body(_) => "body",
        SceneElement::FaceEdge(_) => "face_edge",
        SceneElement::Origin => "origin",
        SceneElement::GlobalAxis(_) => "axis",
        SceneElement::BodyEdge { .. } => "body_edge",
        SceneElement::BodyVertex { .. } => "body_vertex",
        SceneElement::ProjectedEdge { .. } => "projected_edge",
        SceneElement::ProjectedCorner { .. } => "projected_corner",
        SceneElement::BodyFace { .. } | SceneElement::SketchFace(_) => "face",
        SceneElement::BodyCylinder { .. } => "cylinder",
        SceneElement::BodyAxis { .. } => "body_axis",
        SceneElement::CircleNormal(_) => "circle_normal",
        SceneElement::MovePoint(_) => "move_point",
        SceneElement::ExtrusionEdge { .. } => "extrusion_edge",
        SceneElement::PrimitiveEdge { .. } => "primitive_edge",
        SceneElement::RepeatedFace { .. } => "repeated_face",
        SceneElement::Image(_) => "image",
        SceneElement::BooleanOp(_) => "boolean_op",
        SceneElement::MoveOp(_) => "move_op",
        SceneElement::MirrorOp(_) => "mirror_op",
        SceneElement::RepeatOp(_) => "repeat_op",
        SceneElement::SketchRepeatOp(_) => "sketch_repeat_op",
        SceneElement::SketchOffsetOp(_) => "sketch_offset_op",
        SceneElement::SketchMirrorOp(_) => "sketch_mirror_op",
        SceneElement::SketchVertexTreatmentOp(_) => "sketch_vertex_treatment_op",
        SceneElement::SketchSliceOp(_) => "sketch_slice_op",
        SceneElement::SketchText(_) => "sketch_text",
        SceneElement::SliceOp(_) => "slice_op",
        SceneElement::ShellOp(_) => "shell_op",
        SceneElement::EdgeTreatmentOp(_) => "edge_treatment_op",
        SceneElement::Revolution(_) => "revolution",
        SceneElement::Shape(_) => "shape",
        SceneElement::SweepOp(_) => "sweep",
        SceneElement::Loft(_) => "loft",
        SceneElement::Drawing(_) => "drawing",
        SceneElement::Component(_) => "component",
        SceneElement::UnitInstance(_) => "unit_instance",
        SceneElement::Joint(_) => "joint",
        // A drawing's three item types keep their own script names (#363/#967).
        SceneElement::DrawingElement { element, .. } => {
            use crate::context::DrawingElementRef as D;
            match element {
                D::Projection(_) => "projection",
                D::Text(_) => "annotation",
                D::Dimension { .. } | D::PointDim { .. } => "drawing_dimension",
                D::Loupe { .. } => "drawing_loupe",
            }
        }
    }
}

/// The integer a script sees for an element (#1055). For a `Vec`-backed collection that is
/// still the stored index; for an arena-backed one it is the element's **ordinal** among the
/// live elements of its kind, in document order — a key is not something a hand-written
/// script can spell, and every example and doc page uses the ordinal.
fn element_index(doc: &crate::model::Document, element: SceneElement) -> usize {
    match element {
        SceneElement::Image(key) => {
            doc.tracing_images.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Revolution(key) => {
            doc.revolutions.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SweepOp(key) => doc.sweeps.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::Loft(key) => doc.lofts.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::Drawing(key) => doc.drawings.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::CrossSection(key) => {
            doc.cross_sections.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SectionPlane { view, cut } => {
            crate::model::section_plane_ordinal(doc, view, cut).unwrap_or(0)
        }
        SceneElement::Shape(key) => doc.primitives.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::Body(key) => doc.bodies.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::BooleanOp(key) => {
            doc.boolean_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::MoveOp(key) => doc.move_ops.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::MirrorOp(key) => {
            doc.mirror_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::RepeatOp(key) => {
            doc.repeat_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SliceOp(key) => doc.slice_ops.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::ShellOp(key) => doc.shell_ops.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::SketchRepeatOp(key) => {
            doc.sketch_repeat_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SketchOffsetOp(key) => {
            doc.sketch_offset_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SketchMirrorOp(key) => {
            doc.sketch_mirror_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SketchVertexTreatmentOp(key) => doc
            .sketch_vertex_treatment_ops
            .keys()
            .position(|k| k == key)
            .unwrap_or(0),
        SceneElement::SketchSliceOp(key) => {
            doc.sketch_slice_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Joint(key) => doc.joints.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::EdgeTreatmentOp(key) => {
            doc.edge_treatment_ops.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Line(key) => doc.lines.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::ConstructionPlane(key) => {
            doc.construction_planes.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Circle(key) | SceneElement::CircleNormal(key) => {
            doc.circles.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Sketch(key) => doc.sketches.keys().position(|k| k == key).unwrap_or(0),
        SceneElement::Constraint(key) => {
            doc.constraints.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Parameter(key) => {
            doc.parameters.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::SketchText(key) => {
            doc.sketch_texts.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Extrusion(key) => {
            doc.extrusions.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::Component(key) => {
            doc.components.keys().position(|k| k == key).unwrap_or(0)
        }
        SceneElement::UnitInstance(key) => {
            doc.unit_instances.keys().position(|k| k == key).unwrap_or(0)
        }
        // X/Y/Z index as 0/1/2 so a script can name one (#952).
        SceneElement::GlobalAxis(axis) => match axis {
            crate::construction::GlobalAxis::X => 0,
            crate::construction::GlobalAxis::Y => 1,
            crate::construction::GlobalAxis::Z => 2,
        },
        SceneElement::Point(_)
        | SceneElement::FaceEdge(_)
        | SceneElement::Origin
        | SceneElement::BodyEdge { .. }
        | SceneElement::BodyVertex { .. }
        | SceneElement::ProjectedEdge { .. }
        | SceneElement::ProjectedCorner { .. }
        | SceneElement::BodyFace { .. }
        | SceneElement::BodyCylinder { .. }
        | SceneElement::BodyAxis { .. }
        | SceneElement::SketchFace(_)
        | SceneElement::MovePoint(_) => 0,
        SceneElement::ExtrusionEdge { extrusion, .. } => {
            doc.extrusions.keys().position(|k| k == extrusion).unwrap_or(0)
        }
        SceneElement::PrimitiveEdge { primitive, .. } => {
            doc.primitives.keys().position(|k| k == primitive).unwrap_or(0)
        }
        SceneElement::RepeatedFace { instance, .. } => instance,
        // A drawing item indexes by its place on the page; a dimension has no index of its
        // own, so it reports the view it's on.
        SceneElement::DrawingElement { drawing, element } => {
            use crate::context::DrawingElementRef as D;
            match element {
                D::Projection(i) => i,
                D::Text(key) => doc
                    .drawings
                    .get(drawing)
                    .and_then(|d| d.annotations.keys().position(|k| k == key))
                    .unwrap_or(0),
                D::Dimension { view, .. } | D::PointDim { view, .. } => view,
                D::Loupe { index, .. } => index,
            }
        }
    }
}

/// The element a script's `(kind, index)` names (#1055) — the inverse of [`element_index`],
/// so an arena-backed kind resolves its ordinal to the key that element actually holds.
pub fn scene_element_from_kind(
    doc: &crate::model::Document,
    kind: &str,
    index: usize,
) -> Option<SceneElement> {
    match kind.to_ascii_lowercase().as_str() {
        "plane" | "construction_plane" | "constructionplane" => Some(
            SceneElement::ConstructionPlane(doc.construction_planes.keys().nth(index)?),
        ),
        "sketch" => Some(SceneElement::Sketch(doc.sketches.keys().nth(index)?)),
        "line" => Some(SceneElement::Line(doc.lines.keys().nth(index)?)),
        "circle" => Some(SceneElement::Circle(doc.circles.keys().nth(index)?)),
        "constraint" => Some(SceneElement::Constraint(doc.constraints.keys().nth(index)?)),
        "parameter" => Some(SceneElement::Parameter(doc.parameters.keys().nth(index)?)),
        "extrusion" => Some(SceneElement::Extrusion(doc.extrusions.keys().nth(index)?)),
        "body" => Some(SceneElement::Body(doc.bodies.keys().nth(index)?)),
        // #1934: the shadow-free view of the same arena.
        "live_body" => Some(SceneElement::Body(
            doc.bodies
                .iter()
                .filter(|(_, b)| !b.shadow)
                .map(|(k, _)| k)
                .nth(index)?,
        )),
        "boolean_op" | "boolean" => {
            Some(SceneElement::BooleanOp(doc.boolean_ops.keys().nth(index)?))
        }
        "move_op" | "move" => Some(SceneElement::MoveOp(doc.move_ops.keys().nth(index)?)),
        "sketch_text" | "text" => {
            Some(SceneElement::SketchText(doc.sketch_texts.keys().nth(index)?))
        }
        "component" => Some(SceneElement::Component(doc.components.keys().nth(index)?)),
        "sketch_offset_op" | "offset" => {
            Some(SceneElement::SketchOffsetOp(doc.sketch_offset_ops.keys().nth(index)?))
        }
        "sketch_mirror_op" => {
            Some(SceneElement::SketchMirrorOp(doc.sketch_mirror_ops.keys().nth(index)?))
        }
        "sketch_vertex_treatment_op" | "chamfer_op" | "fillet_op" => Some(
            SceneElement::SketchVertexTreatmentOp(doc.sketch_vertex_treatment_ops.keys().nth(index)?),
        ),
        "mirror_op" | "mirror" => Some(SceneElement::MirrorOp(doc.mirror_ops.keys().nth(index)?)),
        "unit_instance" | "unit" => {
            Some(SceneElement::UnitInstance(doc.unit_instances.keys().nth(index)?))
        }
        "image" | "tracing_image" => {
            Some(SceneElement::Image(doc.tracing_images.keys().nth(index)?))
        }
        "revolution" | "revolve" => {
            Some(SceneElement::Revolution(doc.revolutions.keys().nth(index)?))
        }
        "sweep" | "sweep_op" => Some(SceneElement::SweepOp(doc.sweeps.keys().nth(index)?)),
        "loft" => Some(SceneElement::Loft(doc.lofts.keys().nth(index)?)),
        "drawing" => Some(SceneElement::Drawing(doc.drawings.keys().nth(index)?)),
        "cross_section" | "section" => {
            Some(SceneElement::CrossSection(doc.cross_sections.keys().nth(index)?))
        }
        "section_plane" | "cutting_plane" => {
            let (view, cut) = crate::model::nth_section_plane(doc, index)?;
            Some(SceneElement::SectionPlane { view, cut })
        }
        "joint" => Some(SceneElement::Joint(doc.joints.keys().nth(index)?)),
        "shape" | "primitive" => Some(SceneElement::Shape(doc.primitives.keys().nth(index)?)),
        // #1517: the remaining top-level kinds a component can hold, so
        // `bearcad.move_to_component` can name every member the document has.
        "repeat_op" | "repeat" => Some(SceneElement::RepeatOp(doc.repeat_ops.keys().nth(index)?)),
        "slice_op" | "slice" => Some(SceneElement::SliceOp(doc.slice_ops.keys().nth(index)?)),
        "shell_op" | "shell" => Some(SceneElement::ShellOp(doc.shell_ops.keys().nth(index)?)),
        "edge_treatment_op" | "fillet_edge_op" | "chamfer_edge_op" => Some(
            SceneElement::EdgeTreatmentOp(doc.edge_treatment_ops.keys().nth(index)?),
        ),
        "sketch_repeat_op" => Some(SceneElement::SketchRepeatOp(
            doc.sketch_repeat_ops.keys().nth(index)?,
        )),
        "sketch_slice_op" => Some(SceneElement::SketchSliceOp(
            doc.sketch_slice_ops.keys().nth(index)?,
        )),
        // A circle's own normal (#1859), by the circle's ordinal.
        "circle_normal" => Some(SceneElement::CircleNormal(doc.circles.keys().nth(index)?)),
        // The world axes (#952) index as 0/1/2 for X/Y/Z, matching `element_index`.
        "axis" | "global_axis" => Some(SceneElement::GlobalAxis(match index {
            0 => crate::construction::GlobalAxis::X,
            1 => crate::construction::GlobalAxis::Y,
            2 => crate::construction::GlobalAxis::Z,
            _ => return None,
        })),
        _ => None,
    }
}

/// Every element of a script kind name, in ordinal order (#1800) — what a `{ kind = … }`
/// selector with no index stands for, and what a creation call is measured against to see
/// what it made (#1801). Empty for an unknown kind, too: the caller reports both the same way.
fn elements_of_kind(doc: &crate::model::Document, kind: &str) -> Vec<SceneElement> {
    // The kinds this runs over on every instruction walk their arena once. Resolving ordinal
    // by ordinal through `scene_element_from_kind` would be quadratic in the element count,
    // which a script with a few thousand lines in it would feel.
    macro_rules! all {
        ($arena:expr, $variant:expr) => {
            return $arena.keys().map($variant).collect()
        };
    }
    match kind.to_ascii_lowercase().as_str() {
        "body" => all!(doc.bodies, SceneElement::Body),
        // #1934: only the bodies that are really there — consumed operation inputs linger
        // as shadow bodies, so `count("body")` (which has to match the ordinal space) is
        // not the count a script means by "how many parts did I build".
        "live_body" => {
            return doc
                .bodies
                .iter()
                .filter(|(_, b)| !b.shadow)
                .map(|(k, _)| SceneElement::Body(k))
                .collect()
        }
        "shape" | "primitive" => all!(doc.primitives, SceneElement::Shape),
        "line" => all!(doc.lines, SceneElement::Line),
        "circle" => all!(doc.circles, SceneElement::Circle),
        "sketch_text" | "text" => all!(doc.sketch_texts, SceneElement::SketchText),
        "plane" | "construction_plane" | "constructionplane" => {
            all!(doc.construction_planes, SceneElement::ConstructionPlane)
        }
        "sketch" => all!(doc.sketches, SceneElement::Sketch),
        "constraint" => all!(doc.constraints, SceneElement::Constraint),
        "parameter" => all!(doc.parameters, SceneElement::Parameter),
        "drawing" => all!(doc.drawings, SceneElement::Drawing),
        "cross_section" | "section" => all!(doc.cross_sections, SceneElement::CrossSection),
        "component" => all!(doc.components, SceneElement::Component),
        "joint" => all!(doc.joints, SceneElement::Joint),
        "image" | "tracing_image" => all!(doc.tracing_images, SceneElement::Image),
        _ => {}
    }
    // Everything else is rare enough to resolve the plain way.
    let mut out = Vec::new();
    while let Some(element) = scene_element_from_kind(doc, kind, out.len()) {
        out.push(element);
    }
    out
}

/// The kind a bare `{ kind = … }` selector sweeps (#1800), or `None` when the table names one
/// specific element. `{ kind = "plane" }` is every datum plane — the way a script clears them
/// out of a screenshot; anything else in the table (an `index`, a `name`, a face/axis/point
/// selector) picks a single element, as before.
fn kind_only_selector(table: &Table) -> mlua::Result<Option<String>> {
    let Some(kind) = table.get::<Option<String>>("kind")?.or(table.get::<Option<String>>("type")?)
    else {
        return Ok(None);
    };
    for key in [
        "index", "name", "endpoint", "end", "corner", "anchor", "point", "edge", "face", "axis",
        "drawing", "view",
    ] {
        if table.contains_key(key)? {
            return Ok(None);
        }
    }
    // `{ kind = "origin" }` is the origin itself, not a sweep over a kind called "origin".
    if kind.eq_ignore_ascii_case("origin") {
        return Ok(None);
    }
    Ok(Some(kind))
}

fn parse_visibility(value: Value) -> mlua::Result<Option<bool>> {
    match value {
        Value::Nil => Ok(None),
        Value::Boolean(b) => Ok(Some(b)),
        Value::String(s) => match s.to_str()?.to_ascii_lowercase().as_str() {
            "show" | "on" | "true" | "yes" | "1" => Ok(Some(true)),
            "hide" | "off" | "false" | "no" | "0" => Ok(Some(false)),
            "toggle" => Ok(None),
            other => Err(mlua::Error::external(format!(
                "unknown visibility value '{other}'"
            ))),
        },
        other => Err(mlua::Error::external(format!(
            "expected boolean or string for visibility, got {other:?}"
        ))),
    }
}

fn parse_bool(value: Value, label: &str) -> mlua::Result<bool> {
    match value {
        Value::Boolean(b) => Ok(b),
        Value::String(s) => match s.to_str()?.to_ascii_lowercase().as_str() {
            "true" | "on" | "yes" | "1" => Ok(true),
            "false" | "off" | "no" | "0" => Ok(false),
            other => Err(mlua::Error::external(format!(
                "unknown {label} value '{other}'"
            ))),
        },
        other => Err(mlua::Error::external(format!(
            "expected boolean for {label}, got {other:?}"
        ))),
    }
}

fn make_element(lua: &Lua, element: SceneElement) -> mlua::Result<Value> {
    let tick = lua
        .app_data_ref::<ScriptTickData>()
        .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
    let index = element_index(unsafe { &tick.state().doc }, element.clone());
    drop(tick);
    Ok(Value::UserData(lua.create_userdata(LuaElement { element, index })?))
}

/// The body a script's ordinal names (#1055) — a script counts live bodies, it cannot spell
/// a key.
fn body_key_from_ordinal(lua: &Lua, ordinal: usize) -> mlua::Result<crate::model::BodyKey> {
    let tick = lua
        .app_data_ref::<ScriptTickData>()
        .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
    let key = unsafe { tick.state().doc.body_at(ordinal) };
    key.ok_or_else(|| mlua::Error::external(format!("no body {ordinal}")))
}

