    api.set(
        "sketch_faces",
        lua.create_function(|lua, sketch: Option<Ordinal>| {
            let sketch = sketch.map(|o| o.0);
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let sketches: Vec<crate::model::SketchId> = match sketch {
                Some(ordinal) => vec![state
                    .doc
                    .sketches
                    .keys()
                    .nth(ordinal)
                    .ok_or_else(|| mlua::Error::external(format!("no sketch {ordinal}")))?],
                None => {
                    if let Some(session) = state.sketch_session {
                        vec![session.sketch]
                    } else {
                        state.doc.sketches.keys().collect()
                    }
                }
            };
            let out = lua.create_table()?;
            let mut n = 0;
            for sketch in sketches {
                for face in crate::polygon::sketch_profiles(&state.doc, sketch) {
                    n += 1;
                    out.set(n, extrude_face_to_lua(lua, &face)?)?;
                }
            }
            Ok(out)
        })?,
    )?;

    api.set(
        "sketch_conflicts",
        lua.create_function(|lua, sketch: Option<Ordinal>| {
            let sketch = sketch.map(|o| o.0);
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let sketch = match sketch {
                Some(ordinal) => state
                    .doc
                    .sketches
                    .keys()
                    .nth(ordinal)
                    .ok_or_else(|| mlua::Error::external(format!("no sketch {ordinal}")))?,
                None => state
                    .sketch_session
                    .map(|session| session.sketch)
                    .ok_or_else(|| mlua::Error::external("no active sketch"))?,
            };
            let conflicts =
                crate::constraints::sketch_conflicting_constraints(&state.doc, sketch)
                    .map_err(mlua::Error::external)?;
            let table = lua.create_table()?;
            // A script sees a constraint's ordinal among the live ones (#1055).
            for (i, index) in conflicts.iter().enumerate() {
                let ordinal = state.doc.constraints.keys().position(|k| k == *index);
                table.set(i + 1, ordinal)?;
            }
            Ok(table)
        })?,
    )?;

    api.set(
        "sketch_dof",
        lua.create_function(|lua, sketch: Option<Ordinal>| {
            let sketch = sketch.map(|o| o.0);
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let sketch = match sketch {
                Some(ordinal) => state
                    .doc
                    .sketches
                    .keys()
                    .nth(ordinal)
                    .ok_or_else(|| mlua::Error::external(format!("no sketch {ordinal}")))?,
                None => state
                    .sketch_session
                    .map(|session| session.sketch)
                    .ok_or_else(|| mlua::Error::external("no active sketch"))?,
            };
            crate::constraints::sketch_degrees_of_freedom(&state.doc, sketch)
                .map_err(mlua::Error::external)
        })?,
    )?;

    // ----- Read-back / introspection getters (#107). Pure reads of the live state, like
    // `sketch_dof` above — not `Instruction`s, so they never appear in recorded scripts. -----

    // #1943: the whole material table in one call — names, colors, and which are stock.
    api.set(
        "materials",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let out = lua.create_table()?;
            for (i, key) in doc.materials.keys().enumerate() {
                out.set(i + 1, material_table(lua, i, &doc.materials[key])?)?;
            }
            Ok(out)
        })?,
    )?;

    api.set(
        "count",
        lua.create_function(|lua, kind: String| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let count = count_kind(doc, &kind).ok_or_else(|| {
                mlua::Error::external(format!(
                    "unknown count kind '{kind}' (valid kinds: {})",
                    INSPECT_KINDS.join(", ")
                ))
            })?;
            Ok(count)
        })?,
    )?;

    // #1886: live `count` vs the last Save, without exposing SQL.
    api.set(
        "count_saved",
        lua.create_function(|lua, kind: String| {
            let table = crate::script::saved_table_for_kind(&kind).ok_or_else(|| {
                mlua::Error::external(format!(
                    "unknown count kind '{kind}' (valid kinds: {})",
                    INSPECT_KINDS.join(", ")
                ))
            })?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            #[cfg(not(target_arch = "wasm32"))]
            {
                let path = state.path.as_deref().ok_or_else(|| {
                    mlua::Error::external("count_saved: document has no path")
                })?;
                let conn = rusqlite::Connection::open(path)
                    .map_err(|e| mlua::Error::external(e.to_string()))?;
                let sql = format!("SELECT COUNT(*) FROM {table}");
                let n: i64 = conn
                    .query_row(&sql, [], |row| row.get(0))
                    .map_err(|e| mlua::Error::external(e.to_string()))?;
                Ok(n)
            }
            #[cfg(target_arch = "wasm32")]
            {
                let _ = (lua, table, state);
                Err(mlua::Error::external(
                    "count_saved is not available in the browser",
                ))
            }
        })?,
    )?;

    api.set(
        "get",
        lua.create_function(|lua, args: MultiValue| {
            let (kind, index, opts) = parse_get_target(lua, args)?;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let t = lua.create_table()?;
            match kind.to_ascii_lowercase().as_str() {
                "line" => {
                    // The script's `index` is the line's ordinal (#1055).
                    let Some(line) = doc.lines.keys().nth(index).map(|k| &doc.lines[k]) else {
                        return Ok(Value::Nil);
                    };
                    t.set("x0", line.x0)?;
                    t.set("y0", line.y0)?;
                    t.set("x", line.x0)?;
                    t.set("y", line.y0)?;
                    t.set("x1", line.x1)?;
                    t.set("y1", line.y1)?;
                    t.set("construction", line.construction)?;
                    t.set("curved", line.is_curved())?;
                    if let Some([c0, c1]) = line.bezier {
                        let handles = lua.create_table()?;
                        for (i, (hx, hy)) in [c0, c1].into_iter().enumerate() {
                            let h = lua.create_table()?;
                            h.set(1, hx)?;
                            h.set(2, hy)?;
                            handles.set(i + 1, h)?;
                        }
                        t.set("bezier", handles)?;
                    }
                    t.set("length", line.length())?;
                    t.set("projected", line.projection.is_some())?;
                    if let Some(name) = &line.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set("sketch", doc.sketches.keys().position(|k| k == line.sketch))?;
                }
                "circle" => {
                    // The script's `index` is the circle's ordinal (#1055).
                    let Some(circle) = doc.circles.keys().nth(index).map(|k| &doc.circles[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("x", circle.cx)?;
                    t.set("y", circle.cy)?;
                    t.set("r", circle.r)?;
                    t.set("radius", circle.r)?;
                    t.set("diameter", circle.diameter())?;
                    t.set("construction", circle.construction)?;
                    if let Some(name) = &circle.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set("sketch", doc.sketches.keys().position(|k| k == circle.sketch))?;
                }
                "sketch" => {
                    // The script's `index` is the sketch's ordinal (#1055).
                    let Some(key) = doc.sketches.keys().nth(index) else {
                        return Ok(Value::Nil);
                    };
                    let sketch = &doc.sketches[key];
                    t.set("face", face_kind_name(&sketch.face))?;
                    if let Some(frame) = crate::face::sketch_geometry_frame(doc, key) {
                        t.set("origin", vec3_lua(lua, frame.origin)?)?;
                    }
                    if let Some(name) = &sketch.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "constraint" => {
                    // The script's `index` is the constraint's ordinal (#1055).
                    let Some(constraint) =
                        doc.constraints.keys().nth(index).map(|k| &doc.constraints[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("kind", constraint_kind_name(&constraint.kind))?;
                    t.set("expression", constraint.expression.as_str())?;
                    if let Some(name) = &constraint.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set(
                        "sketch",
                        doc.sketches.keys().position(|k| k == constraint.sketch),
                    )?;
                }
                "construction_plane" | "plane" => {
                    // The script's `index` is the plane's ordinal (#1055).
                    let Some(plane) = doc
                        .construction_planes
                        .keys()
                        .nth(index)
                        .map(|k| &doc.construction_planes[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("origin", vec3_lua(lua, plane.origin)?)?;
                    t.set("normal", vec3_lua(lua, plane.normal)?)?;
                    // The drawn rectangle's size in the plane's own u/v axes (#833).
                    let extent = lua.create_table()?;
                    extent.set("u_min", plane.extent.u_min)?;
                    extent.set("u_max", plane.extent.u_max)?;
                    extent.set("v_min", plane.extent.v_min)?;
                    extent.set("v_max", plane.extent.v_max)?;
                    t.set("extent", extent)?;
                    // #1932: how the plane was *defined*, not just where it landed — the
                    // offset/angle it was given, the expressions driving them, and which
                    // kind of anchor it hangs off.
                    let def = &plane.definition;
                    t.set("offset", def.offset_mm)?;
                    t.set("angle", def.angle_deg)?;
                    if !def.offset_expression.trim().is_empty() {
                        t.set("offset_expression", def.offset_expression.as_str())?;
                    }
                    if !def.angle_expression.trim().is_empty() {
                        t.set("angle_expression", def.angle_expression.as_str())?;
                    }
                    match &def.anchor {
                        crate::model::PlaneAnchor::Face { origin, normal, label } => {
                            t.set("anchor", "face")?;
                            t.set("anchor_origin", vec3_lua(lua, *origin)?)?;
                            t.set("anchor_normal", vec3_lua(lua, *normal)?)?;
                            t.set("anchor_label", label.as_str())?;
                        }
                        crate::model::PlaneAnchor::Axis { origin, direction, label } => {
                            t.set("anchor", "axis")?;
                            t.set("anchor_origin", vec3_lua(lua, *origin)?)?;
                            t.set("anchor_direction", vec3_lua(lua, *direction)?)?;
                            t.set("anchor_label", label.as_str())?;
                        }
                    }
                    if let Some(name) = &plane.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "extrusion" => {
                    // The script's `index` is the extrusion's ordinal among the live
                    // ones (#1055).
                    let Some(key) = doc.extrusions.keys().nth(index) else {
                        return Ok(Value::Nil);
                    };
                    let extrusion = &doc.extrusions[key];
                    t.set("distance", extrusion.distance)?;
                    t.set(
                        "sketch",
                        doc.sketches.keys().position(|k| k == extrusion.sketch),
                    )?;
                    t.set("faces", extrusion.faces.len())?;
                    t.set("body", extrusion_body_script(doc, key))?;
                    t.set("symmetric", extrusion.symmetric)?;
                    t.set("taper", extrusion.taper)?;
                    t.set("taper_mode", extrusion.taper_mode.as_str())?;
                    if !extrusion.taper_expression.is_empty() {
                        t.set("taper_expression", extrusion.taper_expression.as_str())?;
                    }
                    if !extrusion.expression.is_empty() {
                        t.set("expression", extrusion.expression.as_str())?;
                    }
                    if let Some(target) = &extrusion.target {
                        t.set("to", extrude_target_table(lua, doc, target)?)?;
                    }
                    if let Some(name) = &extrusion.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "body" | "live_body" => {
                    // The script's `index` is the body's ordinal among the live ones (#1055);
                    // `live_body` indexes the same arena with consumed shadows skipped (#1934).
                    let key = if kind == "live_body" {
                        doc.bodies
                            .iter()
                            .filter(|(_, b)| !b.shadow)
                            .map(|(k, _)| k)
                            .nth(index)
                    } else {
                        doc.bodies.keys().nth(index)
                    };
                    let Some(body) = key.map(|k| &doc.bodies[k]) else {
                        return Ok(Value::Nil);
                    };
                    if let Some(name) = &body.name {
                        t.set("name", name.as_str())?;
                    }
                    let add = lua.create_table()?;
                    for (i, ei) in body.source.extrusion_indices().iter().enumerate() {
                        add.set(i + 1, doc.extrusions.keys().position(|k| k == *ei))?;
                    }
                    t.set("add", add)?;
                    let cut = lua.create_table()?;
                    for (i, ei) in body.source.cut_extrusion_indices().iter().enumerate() {
                        cut.set(i + 1, doc.extrusions.keys().position(|k| k == *ei))?;
                    }
                    t.set("cut", cut)?;
                    t.set(
                        "material",
                        body.material
                            .and_then(|mi| doc.materials.keys().position(|k| k == mi)),
                    )?;
                    t.set("shadow", body.shadow)?;
                }
                // #1943: a body reports its material as a bare ordinal; this is what
                // resolves it, and what makes the stock palette discoverable.
                "material" => {
                    let Some(key) = doc.materials.keys().nth(index) else {
                        return Ok(Value::Nil);
                    };
                    return Ok(Value::Table(material_table(lua, index, &doc.materials[key])?));
                }
                "parameter" => {
                    // The script's `index` is the parameter's ordinal (#1055).
                    let Some(param) = doc.parameters.keys().nth(index).map(|k| &doc.parameters[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("name", param.name.as_str())?;
                    t.set("expression", param.expression.as_str())?;
                }
                "sketch_text" | "text" => {
                    let Some(text) = doc.sketch_texts.keys().nth(index).map(|k| &doc.sketch_texts[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("text", text.text.as_str())?;
                    t.set("x", text.origin.0)?;
                    t.set("y", text.origin.1)?;
                    t.set("rotation", text.rotation.to_degrees())?;
                    t.set("flip", text.flip)?;
                    t.set("size", text.size)?;
                    t.set("font", text.font_family.as_str())?;
                    t.set("bold", text.bold)?;
                    t.set("italic", text.italic)?;
                    t.set("underline", text.underline)?;
                    if let Some(w) = text.wrap_width {
                        t.set("wrap", w)?;
                    }
                    if let Some(name) = &text.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set("sketch", doc.sketches.keys().position(|k| k == text.sketch))?;
                }
                "image" | "tracing_image" => {
                    let Some(img) = doc
                        .tracing_images
                        .keys()
                        .nth(index)
                        .map(|k| &doc.tracing_images[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("origin_x", img.origin.0)?;
                    t.set("origin_y", img.origin.1)?;
                    t.set("rotation", img.rotation.to_degrees())?;
                    t.set("width", img.width_mm)?;
                    t.set("height", img.height_mm)?;
                    if let Some(name) = &img.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set("source", img.source_name.as_str())?;
                    t.set("opacity", img.opacity)?;
                    t.set(
                        "plane",
                        doc.construction_planes.keys().position(|k| k == img.plane),
                    )?;
                    if let Some(cal) = &img.calibration {
                        let from = lua.create_table()?;
                        if let Some((x, y)) = crate::model::image_calibration_point_uv(img, 0) {
                            from.set(1, x)?;
                            from.set(2, y)?;
                            t.set("from", from)?;
                        }
                        let to = lua.create_table()?;
                        if let Some((x, y)) = crate::model::image_calibration_point_uv(img, 1) {
                            to.set(1, x)?;
                            to.set(2, y)?;
                            t.set("to", to)?;
                        }
                        t.set(
                            "length",
                            crate::model::image_calibration_span_mm(img).unwrap_or(cal.length_mm),
                        )?;
                        t.set("expression", cal.expression.as_str())?;
                        let _ = cal;
                    }
                }
                "shape" | "primitive" => {
                    // A primitive's own ordinal (#1055). Dimensions come back evaluated, so
                    // a script can check what `edit_shape` actually did (#1662).
                    let Some(shape) = doc.primitives.keys().nth(index).map(|k| &doc.primitives[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    let Some(r) = crate::primitives::resolve(doc, shape) else {
                        return Ok(Value::Nil);
                    };
                    use crate::model::PrimitiveKind as K;
                    t.set(
                        "kind",
                        match shape.kind {
                            K::Cuboid => "cuboid",
                            K::Cylinder => "cylinder",
                            K::Sphere => "sphere",
                        },
                    )?;
                    match shape.kind {
                        K::Cuboid => {
                            t.set("width", r.width)?;
                            t.set("depth", r.depth)?;
                            t.set("height", r.height)?;
                        }
                        K::Cylinder => {
                            t.set("radius", r.radius)?;
                            t.set("height", r.height)?;
                        }
                        K::Sphere => t.set("radius", r.radius)?,
                    }
                    t.set("at", vec3_lua(lua, r.origin)?)?;
                    // How it was *placed*, not only where it landed (#1929): the
                    // expressions driving the components that have one.
                    if shape.origin_expression.iter().any(|e| !e.trim().is_empty()) {
                        let at = lua.create_table()?;
                        for (i, expr) in shape.origin_expression.iter().enumerate() {
                            if !expr.trim().is_empty() {
                                at.set(i + 1, expr.as_str())?;
                            }
                        }
                        t.set("at_expression", at)?;
                    }
                    t.set("normal", vec3_lua(lua, r.normal)?)?;
                    t.set("u_axis", vec3_lua(lua, r.u)?)?;
                    if let Some(name) = &shape.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "drawing" => {
                    let Some(drawing) = doc.drawings.keys().nth(index).map(|k| &doc.drawings[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("page_width", drawing.page_width_mm)?;
                    t.set("page_height", drawing.page_height_mm)?;
                    t.set("margin", drawing.margin_mm)?;
                    // Which sheet the *editor* shows it on (#1831); the exports are always
                    // black ink on white.
                    t.set("paper", if drawing.white_paper { "white" } else { "dark" })?;
                    // The style projections added to this page start in (#1834).
                    t.set("style", drawing.default_view_style.script_name())?;
                    t.set("style_label", drawing.default_view_style.label())?;
                    t.set("views", drawing.views.len())?;
                    t.set("annotations", drawing.annotations.len())?;
                    if let Some(name) = &drawing.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "cross_section" | "section" => {
                    let Some(view) =
                        doc.cross_sections.keys().nth(index).map(|k| &doc.cross_sections[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("cuts", view.cuts.len())?;
                    if let Some(name) = &view.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "edge_dimension" => {
                    // A drawing view's edge-length dimension (#1916/#1926): where its
                    // label was dragged to, the outward angle it snapped onto, and which
                    // end a too-short label hangs past. `index` is the ordinal among the
                    // view's shown edge dimensions.
                    let opts = opts.as_ref().ok_or_else(|| {
                        mlua::Error::external(
                            "get{ kind = \"edge_dimension\", index, drawing, view }",
                        )
                    })?;
                    let drawing: usize = opts.ordinal_req("drawing")?;
                    let view: usize = opts.ordinal_req("view")?;
                    let Some(v) = doc
                        .drawings
                        .values()
                        .nth(drawing)
                        .and_then(|d| d.views.get(view))
                    else {
                        return Ok(Value::Nil);
                    };
                    let Some(key) = v.dimensioned_edges.get(index).copied() else {
                        return Ok(Value::Nil);
                    };
                    let offset = v
                        .dimension_offsets
                        .iter()
                        .find(|(k, _)| *k == key)
                        .map(|(_, o)| *o)
                        .unwrap_or(0.0);
                    t.set("offset", offset)?;
                    if let Some((_, ang)) =
                        v.dimension_offset_angles.iter().find(|(k, _)| *k == key)
                    {
                        t.set("angle", *ang)?;
                    }
                    if let Some((_, s)) =
                        v.dimension_label_sides.iter().find(|(k, _)| *k == key)
                    {
                        t.set("side", *s)?;
                    }
                    let deq = |q: [i32; 3]| crate::hierarchy::dequantize_body_point(q);
                    t.set("a", vec3_lua(lua, deq(key.0))?)?;
                    t.set("b", vec3_lua(lua, deq(key.1))?)?;
                }
                "circle_dimension" => {
                    // A drawing view's circle Ø dimension (#1774): where its label was dragged
                    // to — `0.0` is the auto-placed default. `index` is the ordinal among the
                    // view's shown circle dimensions.
                    let opts = opts.as_ref().ok_or_else(|| {
                        mlua::Error::external(
                            "get{ kind = \"circle_dimension\", index, drawing, view }",
                        )
                    })?;
                    let drawing: usize = opts.ordinal_req("drawing")?;
                    let view: usize = opts.ordinal_req("view")?;
                    let offset = doc
                        .drawings
                        .values()
                        .nth(drawing)
                        .and_then(|d| d.views.get(view))
                        .and_then(|v| {
                            let center = v.dimensioned_circles.get(index)?;
                            v.circle_dim_offsets
                                .iter()
                                .find(|(k, _)| k == center)
                                .map(|(_, o)| *o)
                        })
                        .unwrap_or(0.0);
                    t.set("offset", offset)?;
                }
                "point_dimension" => {
                    // A drawing view's free point-to-point dimension (#1774): what it measures
                    // and where its label was dragged to.
                    let opts = opts.as_ref().ok_or_else(|| {
                        mlua::Error::external(
                            "get{ kind = \"point_dimension\", index, drawing, view }",
                        )
                    })?;
                    let drawing: usize = opts.ordinal_req("drawing")?;
                    let view: usize = opts.ordinal_req("view")?;
                    let Some(dim) = doc
                        .drawings
                        .values()
                        .nth(drawing)
                        .and_then(|d| d.views.get(view))
                        .and_then(|v| v.point_dims.get(index))
                    else {
                        return Ok(Value::Nil);
                    };
                    let ab = |p: (f32, f32)| -> mlua::Result<mlua::Table> {
                        let pt = lua.create_table()?;
                        pt.set(1, p.0)?;
                        pt.set(2, p.1)?;
                        Ok(pt)
                    };
                    t.set("a", ab(dim.a)?)?;
                    t.set("b", ab(dim.b)?)?;
                    t.set("axis", dim.axis.name())?;
                    t.set("offset", dim.offset)?;
                }
                "section_plane" | "cutting_plane" => {
                    let Some((view_key, cut)) = crate::model::nth_section_plane(doc, index) else {
                        return Ok(Value::Nil);
                    };
                    let Some(plane) = doc
                        .cross_sections
                        .get(view_key)
                        .and_then(|v| v.cuts.get(cut))
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set(
                        "view",
                        doc.cross_sections.keys().position(|k| k == view_key).unwrap_or(0),
                    )?;
                    t.set("cut", cut)?;
                    t.set("origin", vec3_lua(lua, plane.origin)?)?;
                    t.set("normal", vec3_lua(lua, plane.normal)?)?;
                    t.set("offset", plane.offset_mm)?;
                    t.set("roll", plane.roll.to_degrees())?;
                    t.set("flip", plane.flip)?;
                    if let Some(name) = &plane.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "joint" => {
                    let Some(joint) = doc.joints.keys().nth(index).map(|k| &doc.joints[k]) else {
                        return Ok(Value::Nil);
                    };
                    t.set("kind", joint.kind.script_name())?;
                    let members = lua.create_table()?;
                    for (i, m) in joint.members.iter().enumerate() {
                        let entry = lua.create_table()?;
                        let (kind, ordinal) = match m {
                            crate::model::JointRef::Body(k) => {
                                ("body", doc.bodies.keys().position(|x| x == *k))
                            }
                            crate::model::JointRef::Component(k) => {
                                ("component", doc.components.keys().position(|x| x == *k))
                            }
                            crate::model::JointRef::UnitInstance(k) => {
                                ("unit_instance", doc.unit_instances.keys().position(|x| x == *k))
                            }
                        };
                        entry.set("kind", kind)?;
                        entry.set("index", ordinal)?;
                        members.set(i + 1, entry)?;
                    }
                    t.set("members", members)?;
                    t.set("base", joint.base)?;
                    t.set("position", joint.position.as_str())?;
                    t.set("position2", joint.position2.as_str())?;
                    t.set("position3", joint.position3.as_str())?;
                    // The set pose to revert to, and the travel stops (#1945): a partial
                    // `edit_joint` has to be checkable, and the limits were unreadable.
                    t.set("rest", joint.rest.as_str())?;
                    t.set("rest2", joint.rest2.as_str())?;
                    t.set("rest3", joint.rest3.as_str())?;
                    t.set("slide_min", joint.limits.slide_min.as_str())?;
                    t.set("slide_max", joint.limits.slide_max.as_str())?;
                    t.set("turn_min", joint.limits.turn_min.as_str())?;
                    t.set("turn_max", joint.limits.turn_max.as_str())?;
                    if let crate::model::JointKind::Screw { lead } = &joint.kind {
                        t.set("lead", lead.as_str())?;
                    }
                    if let Some(name) = &joint.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "component" => {
                    let Some(key) = doc.components.keys().nth(index) else {
                        return Ok(Value::Nil);
                    };
                    let component = &doc.components[key];
                    if let Some(name) = &component.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set(
                        "parent",
                        component
                            .parent
                            .and_then(|p| doc.components.keys().position(|k| k == p)),
                    )?;
                }
                // Feature operations (#1690): the tools that build bodies out of other
                // bodies each read back as a small summary — enough for a script to check
                // what a click actually built.
                "revolution" | "revolve" => {
                    let Some(rev) = doc.revolutions.keys().nth(index).map(|k| &doc.revolutions[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == rev.sketch))?;
                    t.set("faces", rev.faces.len())?;
                    t.set("axis", revolve_axis_name(&rev.axis))?;
                    t.set("angle", rev.angle_deg)?;
                    t.set("pitch", rev.pitch_mm)?;
                    t.set("body", revolve_mode_name(&rev.mode))?;
                    t.set("mode", revolve_mode_name(&rev.mode))?;
                    if let Some(name) = &rev.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sweep" => {
                    let Some(sweep) = doc.sweeps.keys().nth(index).map(|k| &doc.sweeps[k]) else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == sweep.sketch))?;
                    t.set("faces", sweep.faces.len())?;
                    t.set("path", sweep.path.len())?;
                    t.set("body", sweep_mode_name(&sweep.mode))?;
                    if let Some(name) = &sweep.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "loft" => {
                    let Some(loft) = doc.lofts.keys().nth(index).map(|k| &doc.lofts[k]) else {
                        return Ok(Value::Nil);
                    };
                    t.set("sections", loft.sections.len())?;
                    t.set("body", loft_mode_name(&loft.mode))?;
                    if let Some(name) = &loft.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "combine" | "boolean" | "boolean_op" => {
                    let Some(op) = doc.boolean_ops.keys().nth(index).map(|k| &doc.boolean_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("op", op.kind.script_name())?;
                    t.set("a", body_ordinals_table(lua, doc, &op.a)?)?;
                    t.set("b", body_ordinals_table(lua, doc, &op.b)?)?;
                    t.set("keep_b", op.keep_b)?;
                    t.set("outputs", op.outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "move" | "move_op" => {
                    let Some(op) = doc.move_ops.keys().nth(index).map(|k| &doc.move_ops[k]) else {
                        return Ok(Value::Nil);
                    };
                    t.set("targets", op.targets.len())?;
                    t.set("outputs", op.outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "mirror" | "mirror_op" => {
                    let Some(op) = doc.mirror_ops.keys().nth(index).map(|k| &doc.mirror_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("targets", op.targets.len())?;
                    t.set("outputs", op.outputs.len())?;
                    t.set("output", op.mode.script_name())?;
                    t.set("plane", face_kind_name(&op.plane))?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "repeat" | "repeat_op" => {
                    let Some(op) = doc.repeat_ops.keys().nth(index).map(|k| &doc.repeat_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("targets", op.targets.len())?;
                    t.set("outputs", op.outputs.len())?;
                    t.set("axis", revolve_axis_name(&op.axis))?;
                    t.set("mode", op.mode.script_name())?;
                    t.set("count", op.count.as_str())?;
                    t.set("spacing", op.spacing.as_str())?;
                    t.set("length", op.length.as_str())?;
                    t.set("around_axis", op.around_axis)?;
                    t.set("flip", op.flip)?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "slice" | "slice_op" => {
                    let Some(op) = doc.slice_ops.keys().nth(index).map(|k| &doc.slice_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("targets", op.targets.len())?;
                    t.set("cutters", op.cutters.len())?;
                    t.set("outputs", op.outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "shell" | "shell_op" => {
                    let Some(op) = doc.shell_ops.keys().nth(index).map(|k| &doc.shell_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("targets", op.targets.len())?;
                    t.set("open_faces", op.open_faces.len())?;
                    t.set("thickness", op.thickness.as_str())?;
                    t.set("outputs", op.outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "edge_treatment" => {
                    let Some(op) = doc
                        .edge_treatment_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.edge_treatment_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set(
                        "kind",
                        match op.kind {
                            crate::model::VertexTreatmentKind::Chamfer => "chamfer",
                            crate::model::VertexTreatmentKind::Fillet => "fillet",
                        },
                    )?;
                    t.set("targets", op.targets.len())?;
                    t.set("edges", op.edges.len())?;
                    t.set("amount", op.amount)?;
                    t.set("expression", op.expression.as_str())?;
                    t.set("outputs", op.outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sketch_offset" | "offset" => {
                    let Some(op) = doc
                        .sketch_offset_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.sketch_offset_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == op.sketch))?;
                    t.set("distance", op.distance.as_str())?;
                    t.set("targets", op.line_targets.len() + op.circle_targets.len())?;
                    t.set("outputs", op.line_outputs.len() + op.circle_outputs.len())?;
                    t.set("construction", op.construction)?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sketch_mirror" => {
                    let Some(op) = doc
                        .sketch_mirror_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.sketch_mirror_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == op.sketch))?;
                    t.set("targets", op.line_targets.len() + op.circle_targets.len())?;
                    t.set("outputs", op.line_outputs.len() + op.circle_outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sketch_repeat" => {
                    let Some(op) = doc
                        .sketch_repeat_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.sketch_repeat_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == op.sketch))?;
                    t.set("mode", op.mode.script_name())?;
                    t.set("count", op.count.as_str())?;
                    t.set("spacing", op.spacing.as_str())?;
                    t.set("length", op.length.as_str())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sketch_slice" => {
                    let Some(op) = doc
                        .sketch_slice_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.sketch_slice_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == op.sketch))?;
                    t.set("targets", op.line_targets.len() + op.circle_targets.len())?;
                    t.set("cutters", op.cutter_lines.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "sketch_chamfer" | "sketch_fillet" => {
                    let Some(op) = doc
                        .sketch_vertex_treatment_ops
                        .keys()
                        .nth(index)
                        .map(|k| &doc.sketch_vertex_treatment_ops[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    t.set("sketch", doc.sketches.keys().position(|k| k == op.sketch))?;
                    t.set("corners", op.corners.len())?;
                    t.set("outputs", op.line_outputs.len() + op.bridge_outputs.len())?;
                    if let Some(name) = &op.name {
                        t.set("name", name.as_str())?;
                    }
                }
                "unit_instance" | "unit" => {
                    let Some(inst) = doc
                        .unit_instances
                        .keys()
                        .nth(index)
                        .map(|k| &doc.unit_instances[k])
                    else {
                        return Ok(Value::Nil);
                    };
                    if let Some(name) = &inst.name {
                        t.set("name", name.as_str())?;
                    }
                    t.set("unit", doc.units.keys().position(|k| k == inst.unit))?;
                }
                other => {
                    return Err(mlua::Error::external(format!(
                        "unknown get kind '{other}' (valid kinds: {})",
                        INSPECT_KINDS.join(", ")
                    )))
                }
            }
            Ok(Value::Table(t))
        })?,
    )?;

    api.set(
        "body_stats",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let Some(key) = doc.bodies.keys().nth(index) else {
                return Ok(Value::Nil);
            };
            let Some(mesh) = crate::extrude::body_solid_mesh(doc, key) else {
                return Err(mlua::Error::external(format!(
                    "body {index} has no mesh"
                )));
            };
            let Some((min, max)) = mesh.bounds() else {
                return Err(mlua::Error::external(format!(
                    "body {index} has no mesh"
                )));
            };
            let t = lua.create_table()?;
            t.set("volume", crate::extrude::mesh_signed_volume(&mesh).abs())?;
            t.set("triangles", mesh.triangles.len())?;
            let bbox = lua.create_table()?;
            bbox.set("min", vec3_lua(lua, min)?)?;
            bbox.set("max", vec3_lua(lua, max)?)?;
            t.set("bbox", bbox)?;
            Ok(Value::Table(t))
        })?,
    )?;

    // A body **as the open cross-section view shows it** (#1845): the same
    // `{ volume, triangles, bbox }` `body_stats` gives, measured on the mesh the view's
    // cutting planes leave behind. Without it a script can hang planes but never see what
    // they took. `nil` when nothing of the body survives the cut.
    api.set(
        "section_stats",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let Some(key) = state.doc.bodies.keys().nth(index) else {
                return Ok(Value::Nil);
            };
            let cuts: Vec<crate::model::CrossSectionCut> = state
                .editing_cross_section
                .and_then(|v| state.doc.cross_sections.get(v))
                .map(|v| v.cuts.clone())
                .unwrap_or_default();
            let Some(mesh) = crate::extrude::sectioned_body_mesh(&state.doc, key, &cuts) else {
                return Ok(Value::Nil);
            };
            let Some((min, max)) = mesh.bounds() else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("volume", crate::extrude::mesh_signed_volume(&mesh).abs())?;
            t.set("triangles", mesh.triangles.len())?;
            let bbox = lua.create_table()?;
            bbox.set("min", vec3_lua(lua, min)?)?;
            bbox.set("max", vec3_lua(lua, max)?)?;
            t.set("bbox", bbox)?;
            Ok(Value::Table(t))
        })?,
    )?;

    // A body's flat faces (#1020): `{ center = {x,y,z}, normal = {x,y,z} }` per face, in the
    // un-posed body's own coordinates — exactly what a mate's `face = {…}` argument takes.
    // Without this a script would have to guess a face's quantized key to name it at all.
    api.set(
        "body_faces",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let out = lua.create_table()?;
            let Some(key) = doc.bodies.keys().nth(index) else {
                return Ok(Value::Table(out));
            };
            let Some(mesh) = crate::extrude::body_solid_mesh_unposed(doc, key) else {
                return Ok(Value::Table(out));
            };
            // Flat faces only (#1013): a round wall is a cylinder, reported by
            // `body_cylinders`, and would give a mate a nonsense plane to land on. The
            // flats are split out of the smooth chains (#1951), so a filleted cap's
            // remaining top is listed as the face it is.
            let _ = &mesh;
            for (i, tris) in crate::extrude::body_flat_face_groups(doc, key).iter().enumerate() {
                out.set(i + 1, body_face_table(lua, index, tris)?)?;
            }
            Ok(Value::Table(out))
        })?,
    )?;

    // A body's cylindrical surfaces (#1013): each with its centre line, in the un-posed
    // body's own coordinates. `axis` is what a mate's `line_up` row takes to put a hole on a
    // shaft; `cylinder` names the round wall itself.
    api.set(
        "body_cylinders",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let out = lua.create_table()?;
            let Some(key) = doc.bodies.keys().nth(index) else {
                return Ok(Value::Table(out));
            };
            for (i, cyl) in crate::extrude::body_cylinders(doc, key).iter().enumerate() {
                let entry = lua.create_table()?;
                entry.set("body", index)?;
                entry.set("cylinder", vec3_lua(lua, cyl.origin)?)?;
                entry.set("direction", vec3_lua(lua, cyl.dir)?)?;
                entry.set("radius", cyl.radius)?;
                entry.set("length", cyl.half_length * 2.0)?;
                let axis = lua.create_table()?;
                axis.set("body", index)?;
                axis.set("hole_axis", vec3_lua(lua, cyl.origin)?)?;
                axis.set("direction", vec3_lua(lua, cyl.dir)?)?;
                entry.set("axis", axis)?;
                out.set(i + 1, entry)?;
            }
            Ok(Value::Table(out))
        })?,
    )?;

    // A body's feature edges (#1020): `{ edge = { {x,y,z}, {x,y,z} } }` per edge, in the
    // un-posed body's own coordinates — what a mate's `line_up` row takes.
    api.set(
        "body_edges",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let doc = unsafe { &tick.state().doc };
            let out = lua.create_table()?;
            let Some(key) = doc.bodies.keys().nth(index) else {
                return Ok(Value::Table(out));
            };
            let Some(mesh) = crate::extrude::body_solid_mesh_unposed(doc, key) else {
                return Ok(Value::Table(out));
            };
            for (i, chain) in crate::gpu_viewport::solid_mesh_edge_chains(&mesh)
                .iter()
                .enumerate()
            {
                let (a, b) = crate::gpu_viewport::chain_canonical_segment(chain);
                let edge = lua.create_table()?;
                edge.set("body", index)?;
                let ends = lua.create_table()?;
                ends.set(1, vec3_lua(lua, a)?)?;
                ends.set(2, vec3_lua(lua, b)?)?;
                edge.set("edge", ends)?;
                out.set(i + 1, edge)?;
            }
            Ok(Value::Table(out))
        })?,
    )?;

    api.set(
        "status",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            Ok(unsafe { tick.state().status.clone() })
        })?,
    )?;

    // #1546: the same identity Help → About shows (release tag, or crate version + SHA).
    api.set(
        "version",
        lua.create_function(|_, ()| Ok(crate::full_version()))?,
    )?;

    // #1654: what this run has done so far — the timestamped log of every action, refusal
    // and warning, and the same text a DEV bug report attaches.
    api.set(
        "session_log",
        lua.create_function(|_, ()| Ok(crate::diag::session_log()))?,
    )?;

    api.set(
        "selection",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let out = lua.create_table()?;
            for (i, element) in state.scene_selection.iter().enumerate() {
                let entry = lua.create_table()?;
                entry.set("kind", element_kind_name(element.clone()))?;
                // #1882: every selection entry carries identity so the table works as a
                // handle (point/face-edge used to omit `index` entirely).
                match &element {
                    SceneElement::Point(p) => fill_selection_point(lua, &state.doc, &entry, p)?,
                    SceneElement::CircleNormal(key) => {
                        entry.set(
                            "index",
                            state.doc.circles.keys().position(|k| k == *key).unwrap_or(0),
                        )?;
                    }
                    SceneElement::BodyFace {
                        body,
                        centroid,
                        normal,
                    } => {
                        let ordinal = state.doc.bodies.keys().position(|k| k == *body).unwrap_or(0);
                        entry.set("index", ordinal)?;
                        entry.set("body", ordinal)?;
                        entry.set(
                            "face",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*centroid))?,
                        )?;
                        entry.set(
                            "normal",
                            vec3_lua(
                                lua,
                                crate::hierarchy::dequantize_body_point(*normal).normalize_or_zero(),
                            )?,
                        )?;
                    }
                    SceneElement::BodyCylinder {
                        body,
                        origin,
                        dir,
                        radius,
                    } => {
                        let ordinal = state.doc.bodies.keys().position(|k| k == *body).unwrap_or(0);
                        entry.set("index", ordinal)?;
                        entry.set("body", ordinal)?;
                        entry.set(
                            "cylinder",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*origin))?,
                        )?;
                        entry.set(
                            "direction",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*dir))?,
                        )?;
                        entry.set("radius", *radius as f32 / 1000.0)?;
                    }
                    SceneElement::BodyAxis { body, origin, dir } => {
                        let ordinal = state.doc.bodies.keys().position(|k| k == *body).unwrap_or(0);
                        entry.set("index", ordinal)?;
                        entry.set("body", ordinal)?;
                        entry.set(
                            "origin",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*origin))?,
                        )?;
                        entry.set(
                            "direction",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*dir))?,
                        )?;
                    }
                    // A body's remaining flat picked as a *sketchable* face is the same
                    // thing as picking it directly (#1871/#1951): report the identity, not
                    // just a display label and a dummy index.
                    SceneElement::SketchFace(crate::model::FaceId::BodyMeshFace {
                        body,
                        centroid,
                        normal,
                    }) => {
                        let ordinal = state.doc.bodies.keys().position(|k| k == *body).unwrap_or(0);
                        entry.set("index", ordinal)?;
                        entry.set("body", ordinal)?;
                        entry.set(
                            "face",
                            vec3_lua(lua, crate::hierarchy::dequantize_body_point(*centroid))?,
                        )?;
                        entry.set(
                            "normal",
                            vec3_lua(
                                lua,
                                crate::hierarchy::dequantize_body_point(*normal).normalize_or_zero(),
                            )?,
                        )?;
                    }
                    SceneElement::FaceEdge(_) => {
                        entry.set("index", element_index(&state.doc, element.clone()))?;
                    }
                    _ => {
                        entry.set("index", element_index(&state.doc, element.clone()))?;
                    }
                }
                out.set(i + 1, entry)?;
            }
            // The drawing page keeps its own selection (#346) — projections, notes,
            // dimensions, loupes. Without these a script could not see what a click on the
            // page picked at all (#1846). Each carries the drawing it is on.
            let n = state.scene_selection.iter().count();
            for (i, (drawing, element)) in state.selected_drawing_elements.iter().enumerate() {
                let el = SceneElement::DrawingElement {
                    drawing: *drawing,
                    element: *element,
                };
                let entry = lua.create_table()?;
                entry.set("kind", element_kind_name(el.clone()))?;
                entry.set("index", element_index(&state.doc, el))?;
                entry.set(
                    "drawing",
                    state.doc.drawings.keys().position(|k| k == *drawing).unwrap_or(0),
                )?;
                if let crate::context::DrawingElementRef::Loupe { view, magnified, .. } = element {
                    entry.set("view", *view)?;
                    entry.set("magnified", *magnified)?;
                }
                out.set(n + i + 1, entry)?;
            }
            Ok(out)
        })?,
    )?;

    // The active tool's element pickers (#968): what each one is called, whether it has focus,
    // what kinds and how many it accepts, and what it currently holds. Without this a script
    // can't tell an accepted pick from a rejected one — a body-set tool consumes the click
    // either way, so `selection()` looks identical.
    // What the viewport is hover-highlighting (#968) — the pick a click would take, as
    // `{ kind, index, count, elements }`, or nil when nothing is. Lets a script assert that the
    // right thing lights up, which is otherwise unobservable from outside the renderer.
    api.set(
        "hovered",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let hovered = state.hover_elements.clone();
            let Some(element) = hovered.first().cloned() else {
                return Ok(Value::Nil);
            };
            let doc = unsafe { &tick.state().doc };
            let describe = |element: crate::hierarchy::SceneElement| -> mlua::Result<Table> {
                let entry = lua.create_table()?;
                entry.set("kind", element_kind_name(element.clone()))?;
                entry.set("index", element_index(doc, element.clone()))?;
                if let Some(label) = face_element_label(doc, &element) {
                    entry.set("label", label)?;
                }
                // A body's flat, whether it was picked as a face or as a sketchable
                // surface, reports the same identity (#1871/#1951) — body + centroid +
                // normal, not a display label and a dummy index.
                let mesh_face = match &element {
                    SceneElement::BodyFace { body, centroid, normal } => {
                        Some((*body, *centroid, *normal))
                    }
                    SceneElement::SketchFace(crate::model::FaceId::BodyMeshFace {
                        body,
                        centroid,
                        normal,
                    }) => Some((*body, *centroid, *normal)),
                    _ => None,
                };
                if let Some((body, centroid, normal)) = mesh_face {
                    let ordinal = doc.bodies.keys().position(|k| k == body).unwrap_or(0);
                    entry.set("body", ordinal)?;
                    entry.set(
                        "face",
                        vec3_lua(lua, crate::hierarchy::dequantize_body_point(centroid))?,
                    )?;
                    entry.set(
                        "normal",
                        vec3_lua(
                            lua,
                            crate::hierarchy::dequantize_body_point(normal).normalize_or_zero(),
                        )?,
                    )?;
                }
                Ok(entry)
            };
            let entry = describe(element)?;
            // A picker that expands a face to its boundary lights — and takes — every edge at
            // once (#1541). The first is the table's own kind/index, as it always was; `count`
            // and `elements` say what the rest of the highlight is.
            entry.set("count", hovered.len())?;
            let all = lua.create_table()?;
            for (i, e) in hovered.into_iter().enumerate() {
                all.set(i + 1, describe(e)?)?;
            }
            entry.set("elements", all)?;
            Ok(Value::Table(entry))
        })?,
    )?;

    // The Move tool's intended preview pose (#1458) — the hover probe when a candidate
    // is under the cursor, else the in-progress move. Translation + quaternion, and the
    // AABB of the moving bodies under that pose. `nil` when there is no ghost. Lets a
    // script assert the placement a click would commit, which is otherwise only visible
    // as a translucent mesh.
    api.set(
        "move_preview",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let Some(m) = state.move_preview_transform else {
                return Ok(Value::Nil);
            };
            let (_, rot, pos) = m.to_scale_rotation_translation();
            let entry = lua.create_table()?;
            entry.set("translation", vec3_lua(lua, pos)?)?;
            let q = lua.create_table()?;
            q.set(1, rot.x)?;
            q.set(2, rot.y)?;
            q.set(3, rot.z)?;
            q.set(4, rot.w)?;
            entry.set("rotation", q)?;
            let mut bb_min = glam::Vec3::splat(f32::INFINITY);
            let mut bb_max = glam::Vec3::splat(f32::NEG_INFINITY);
            let mut any = false;
            if let Some(cm) = state.creating_move.as_ref() {
                for &bi in &cm.targets {
                    let Some(mesh) = crate::extrude::body_solid_mesh(&state.doc, bi) else {
                        continue;
                    };
                    let Some((lo, hi)) = mesh.bounds() else {
                        continue;
                    };
                    for x in [lo.x, hi.x] {
                        for y in [lo.y, hi.y] {
                            for z in [lo.z, hi.z] {
                                let p = m.transform_point3(glam::Vec3::new(x, y, z));
                                bb_min = bb_min.min(p);
                                bb_max = bb_max.max(p);
                                any = true;
                            }
                        }
                    }
                }
            }
            if any {
                let bbox = lua.create_table()?;
                bbox.set("min", vec3_lua(lua, bb_min)?)?;
                bbox.set("max", vec3_lua(lua, bb_max)?)?;
                entry.set("bbox", bbox)?;
            }
            Ok(Value::Table(entry))
        })?,
    )?;

    // The Selection Exploder's fan (#968): one `{ kind, index }` per leaf, or an empty table
    // when it's closed. The crowd should offer exactly what the focused picker can take.
    api.set(
        "exploder",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let out = lua.create_table()?;
            for (i, element) in state.exploder_leaves.iter().enumerate() {
                let entry = lua.create_table()?;
                entry.set("kind", element_kind_name(element.clone()))?;
                entry.set("index", element_index(&state.doc, element.clone()))?;
                // Where this leaf's loupe sits, in the viewport-local pixels `bearcad.ui.click`
                // takes (#986) — absent for a leaf the current level shows inside a group.
                if let Some(Some((x, y))) = state.exploder_loupe_positions.get(i) {
                    entry.set("x", *x)?;
                    entry.set("y", *y)?;
                }
                // Which face each leaf is (#988) — a fan over a solid offers several, and
                // `kind`/`index` are identical for all of them.
                if let Some(label) = face_element_label(&state.doc, element) {
                    entry.set("label", label)?;
                }
                out.set(i + 1, entry)?;
            }
            Ok(out)
        })?,
    )?;

    // Arm a picker by name (#963/#968), the scripted equivalent of clicking it in the pane.
    api.set(
        "picker_focus",
        lua.create_function(|lua, name: String| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::FocusPicker { name }) }
        })?,
    )?;

    fn push_picker_row(
        lua: &Lua,
        view: &crate::context::ToolPickerView,
        doc: &crate::model::Document,
    ) -> mlua::Result<Table> {
        let entry = lua.create_table()?;
        entry.set("name", view.heading)?;
        entry.set("focused", view.picker.is_focused())?;
        match view.picker.limit() {
            crate::element_picker::PickLimit::Finite(n) => entry.set("limit", n)?,
            crate::element_picker::PickLimit::Infinite => {}
        }
        let kinds = lua.create_table()?;
        for (k, kind) in view.picker.filter().accepted_kinds().iter().enumerate() {
            kinds.set(k + 1, kind.label())?;
        }
        entry.set("accepts", kinds)?;
        let items = lua.create_table()?;
        for (n, element) in view.picker.picked().iter().enumerate() {
            let item = lua.create_table()?;
            item.set("kind", element_kind_name(element.clone()))?;
            item.set("index", element_index(doc, element.clone()))?;
            items.set(n + 1, item)?;
        }
        entry.set("items", items)?;
        Ok(entry)
    }

    api.set(
        "pickers",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let out = lua.create_table()?;
            for (i, view) in state.tool_pickers.iter().enumerate() {
                out.set(i + 1, push_picker_row(lua, view, &state.doc)?)?;
            }
            Ok(out)
        })?,
    )?;
    api.set(
        "picker",
        lua.create_function(|lua, name: String| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            for view in &state.tool_pickers {
                if view.heading == name {
                    return Ok(Some(push_picker_row(lua, view, &state.doc)?));
                }
            }
            Ok(None)
        })?,
    )?;

    // The per-tool behaviour table (#1508): every row the runtime reads, so a script can
    // assert the policy rather than reverse-engineer it. `bearcad.debug.tool_table()` is
    // the whole table; `bearcad.debug.tool_row()` is the active tool's row in the space
    // the app is in.
    fn push_tool_row(
        lua: &Lua,
        row: &crate::tooltable::ToolRow,
    ) -> mlua::Result<Table> {
        let entry = lua.create_table()?;
        entry.set("tool", crate::shortcuts::tool_script_name(row.tool))?;
        entry.set("space", row.space.label())?;
        entry.set("gizmo", row.gizmo.label())?;
        entry.set("esc", row.esc.label())?;
        entry.set("commit_on_enter", row.commit_on_enter)?;
        entry.set("commit_widget", row.commit_widget.label())?;
        entry.set("output_modes", row.output_modes)?;
        entry.set("stay_armed", row.stay_armed)?;
        entry.set("arm_on_set_tool", row.arm_on_set_tool)?;
        let prefs = lua.create_table()?;
        for (i, p) in row.prefs.iter().enumerate() {
            prefs.set(i + 1, p.label())?;
        }
        entry.set("prefs", prefs)?;
        entry.set("opens_sketch", row.face_click_opens_sketch)?;
        entry.set("leaves_sketch", crate::tooltable::is_3d_only(row.tool))?;
        entry.set("dual_mode", crate::tooltable::is_dual_mode(row.tool))?;
        entry.set(
            "survives_begin_sketch",
            crate::tooltable::survives_begin_sketch(row.tool),
        )?;
        entry.set("draft", format!("{:?}", row.draft))?;
        entry.set("multi_pick", row.multi_pick.label())?;
        let pickers = lua.create_table()?;
        for (i, p) in row.pickers.iter().enumerate() {
            pickers.set(i + 1, p.heading)?;
        }
        entry.set("pickers", pickers)?;
        Ok(entry)
    }

    api.set(
        "tool_table",
        lua.create_function(|lua, ()| {
            let out = lua.create_table()?;
            for (i, row) in crate::tooltable::all_rows().iter().enumerate() {
                out.set(i + 1, push_tool_row(lua, row)?)?;
            }
            Ok(out)
        })?,
    )?;

    api.set(
        "tool_row",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            push_tool_row(lua, &state.tool_row())
        })?,
    )?;

    // Materials (#834): `bearcad.material{ name = "Steel", color = "#b0b6be", bodies = {0} }`
    // adds one and hands it to the listed bodies; `bearcad.set_material{ body = 0, material =
    // 0 }` (or `material = nil`) assigns/clears one.
    api.set(
        "material",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "material", &["name", "color", "bodies"])?;
            let name: Option<String> = opts.get("name")?;
            let color = match opts.get::<Option<String>>("color")? {
                Some(text) => Some(parse_hex_color(&text)?),
                None => None,
            };
            let bodies: Vec<usize> = opts.ordinal_list("bodies")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::AddMaterial { name, color, bodies }) }
        })?,
    )?;

    api.set(
        "set_material",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "set_material", &["body", "material"])?;
            let body: usize = opts.ordinal_req("body")?;
            let material: Option<usize> = opts.get("material")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetBodyMaterial { body, material }) }
        })?,
    )?;

    // Shadow bodies (#1218): `bearcad.set_body_shadow{ body = 0, shadow = true }` hides a
    // body from the viewport (except hover/select) and from whole-document export —
    // the same flag operations set when they consume an input. `shadow = false` restores it.
    api.set(
        "set_body_shadow",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "set_body_shadow", &["body", "shadow"])?;
            let body: usize = opts.ordinal_req("body")?;
            let shadow: bool = opts.get("shadow")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetBodyShadow { body, shadow }) }
        })?,
    )?;

    // Geometric constraints: `bearcad.constrain("parallel", a, b)` with handles / point
    // tables. Modeling scripts must not mutate selection (#1868).
    api.set(
        "constrain",
        lua.create_function(|lua, (name, refs): (String, MultiValue)| {
            let kind = parse_geometric_constraint(&name).ok_or_else(|| {
                mlua::Error::external(format!("unknown geometric constraint '{name}'"))
            })?;
            if refs.is_empty() {
                return Err(mlua::Error::external(
                    "constrain requires operands (handles or point tables); \
                     use bearcad.ui.add_geometric_constraint to apply to the current selection",
                ));
            }
            let elements: Vec<SceneElement> = refs
                .into_iter()
                .map(|v| resolve_element(lua, v))
                .collect::<mlua::Result<_>>()?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::Constrain { kind, elements }) }
        })?,
    )?;

    // Distance and angle dimensions: `bearcad.dimension{ kind, …, value }`. Angle `value`
    // is a number (degrees) or an expression; `sign` picks which of the two wedges.
    api.set(
        "dimension",
        lua.create_function(|lua, opts: Table| {
            check_keys(
                &opts,
                "dimension",
                &[
                    "kind", "type", "value", "index", "a", "b", "sign", "point", "line",
                    "anchor", "mover",
                ],
            )?;
            let kind: String = opts.get("kind").or_else(|_| opts.get("type"))?;
            let expression = lua_amount_expr(&opts, "value")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            if kind.eq_ignore_ascii_case("angle") {
                let line_a = opts.ordinal_req("a")?;
                let line_b = opts.ordinal_req("b")?;
                unsafe {
                    let rotation_sign: i8 = if let Some(s) = opts.get::<Option<i8>>("sign")? {
                        s
                    } else {
                        crate::constraints::angle_constraint_natural_sign(
                            &tick.state().doc,
                            crate::model::ConstraintLine::Line(line_key_from_ordinal(lua, line_a)?),
                            crate::model::ConstraintLine::Line(line_key_from_ordinal(lua, line_b)?),
                        )
                        .unwrap_or(1)
                    };
                    tick.exec(Instruction::AddAngleConstraint {
                        line_a,
                        line_b,
                        rotation_sign,
                        expression,
                    })
                }
            } else {
                let target = parse_distance_target(lua, opts)?;
                unsafe { tick.exec(Instruction::AddDistanceConstraint { target, expression }) }
            }
        })?,
    )?;

    // Selection-based apply for UI tests: `bearcad.ui.add_geometric_constraint("parallel")`.
    api.set(
        "add_geometric_constraint",
        lua.create_function(|lua, name: String| {
            let kind = parse_geometric_constraint(&name).ok_or_else(|| {
                mlua::Error::external(format!("unknown geometric constraint '{name}'"))
            })?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::AddGeometricConstraint(kind)) }
        })?,
    )?;

    api.set(
        "constraint_shortcut",
        lua.create_function(|lua, key: mlua::String| {
            let key = key.to_str()?;
            let key = key
                .chars()
                .next()
                .ok_or_else(|| mlua::Error::external("constraint_shortcut requires a key"))?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::ApplyConstraintShortcut(key)) }
        })?,
    )?;

    // Two forms: positional `drag_vertex(point, u, v)` moves to an absolute sketch-local
    // spot, and the semantic-gizmo table form `drag_vertex{ point = ..., du = 1, dv = 0 }`
    // (#114) nudges by a delta from the vertex's current position. Both respect
    // constraints and raise (catchable via pcall) when the vertex is fully constrained.
    api.set(
        "drag_vertex",
        lua.create_function(|lua, (first, u, v): (Value, Option<f32>, Option<f32>)| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let (point, u, v) = match (u, v) {
                (Some(u), Some(v)) => (parse_constraint_point(lua, first)?, u, v),
                _ => {
                    let Value::Table(opts) = first else {
                        return Err(mlua::Error::external(
                            "drag_vertex table form requires a table",
                        ));
                    };
                    let point = parse_constraint_point(lua, opts.get("point")?)?;
                    let du: Option<f32> = opts.get("du")?;
                    let dv: Option<f32> = opts.get("dv")?;
                    if du.is_none() && dv.is_none() {
                        return Err(mlua::Error::external(
                            "drag_vertex table form requires `du` and/or `dv`",
                        ));
                    }
                    let (cur_u, cur_v) = unsafe {
                        let state = tick.state();
                        let sketch = state
                            .sketch_session
                            .map(|s| s.sketch)
                            .ok_or_else(|| mlua::Error::external("Not in sketch mode"))?;
                        crate::geometric_constraints::point_uv(&state.doc, sketch, point.clone())
                            .map_err(mlua::Error::external)?
                    };
                    (
                        point,
                        cur_u + du.unwrap_or(0.0),
                        cur_v + dv.unwrap_or(0.0),
                    )
                }
            };
            unsafe { tick.exec(Instruction::DragVertex { point, u, v }) }
        })?,
    )?;

    // Two forms: positional `drag_line(line, anchor_u, anchor_v, u, v)` replays a raw
    // grab-here-drop-there gesture, and the semantic-gizmo table form
    // `drag_line{ line = ..., du = 0, dv = 2 }` (#114) translates the line by a delta
    // (line drags are pure translations from the anchor, so the anchor is arbitrary).
    api.set(
        "drag_line",
        lua.create_function(
            |lua,
             (first, anchor_u, anchor_v, u, v): (
                Table,
                Option<f32>,
                Option<f32>,
                Option<f32>,
                Option<f32>,
            )| {
                let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
                let (target, anchor_u, anchor_v, u, v) = match (anchor_u, anchor_v, u, v) {
                    (Some(anchor_u), Some(anchor_v), Some(u), Some(v)) => {
                        (parse_constraint_line_table(lua, first)?, anchor_u, anchor_v, u, v)
                    }
                    _ => {
                        let line_table: Table = first.get("line")?;
                        let target = parse_constraint_line_table(lua, line_table)?;
                        let du: Option<f32> = first.get("du")?;
                        let dv: Option<f32> = first.get("dv")?;
                        if du.is_none() && dv.is_none() {
                            return Err(mlua::Error::external(
                                "drag_line table form requires `du` and/or `dv`",
                            ));
                        }
                        (target, 0.0, 0.0, du.unwrap_or(0.0), dv.unwrap_or(0.0))
                    }
                };
                unsafe {
                    tick.exec(Instruction::DragLineSegment {
                            target,
                            anchor_u,
                            anchor_v,
                            u,
                            v,
                        },
                    )
                }
            },
        )?,
    )?;

