    // #159: how the ground plane renders ("grid" | "solid").
    api.set(
        "ground",
        lua.create_function(|lua, value: Value| {
            let mode = parse_ground_display(value, "ground")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::GroundDisplay(mode)) }
        })?,
    )?;

    // #108: absolute camera control. `bearcad.ui.camera{}` (no args / no keys) is a pure read of
    // the live view; passing any subset of `yaw`/`pitch`/`distance`/`target = {x, y, z}` sets
    // those fields instantly (no transition animation — deterministic for screenshots).
    // `projection`/`shading`/`ground` set the three settings the read already reports (#1771) —
    // they used to be dropped on the floor, so a script asking for an orthographic camera went
    // on running perspective. Any other key is an error, for the same reason.
    const CAMERA_KEYS: &[&str] = &[
        "yaw",
        "pitch",
        "distance",
        "target",
        "projection",
        "shading",
        "ground",
    ];
    api.set(
        "camera",
        lua.create_function(|lua, opts: Option<Table>| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            // Angles are degrees here like everywhere else in the API (#1657); an
            // expression string may name its own unit ("1.2rad").
            let (yaw, pitch, distance, target, projection, shading, ground) = match &opts {
                Some(t) => {
                    check_keys(t, "camera", CAMERA_KEYS)?;
                    let doc = unsafe { &tick.state().doc };
                    (
                        angle_deg_opt(lua, doc, t, "camera", "yaw")?,
                        angle_deg_opt(lua, doc, t, "camera", "pitch")?,
                        length_mm_opt(lua, doc, t, "camera", "distance")?,
                        match t.get::<Option<Table>>("target")? {
                            Some(v) => Some(vec3_from_lua(&v)?),
                            None => None,
                        },
                        match t.get::<Option<String>>("projection")? {
                            Some(name) => Some(ProjectionMode::from_name(&name).ok_or_else(
                                || {
                                    mlua::Error::external(format!(
                                        "camera: unknown projection '{name}'                                          (try perspective, orthographic)"
                                    ))
                                },
                            )?),
                            None => None,
                        },
                        match t.get::<Option<String>>("shading")? {
                            Some(name) => Some(ShadingMode::from_name(&name).ok_or_else(|| {
                                let known: Vec<&str> = crate::camera::SHADING_MODES
                                    .iter()
                                    .map(|m| m.script_name())
                                    .collect();
                                mlua::Error::external(format!(
                                    "camera: unknown shading mode '{name}' (try {})",
                                    known.join(", ")
                                ))
                            })?),
                            None => None,
                        },
                        match t.get::<Value>("ground")? {
                            Value::Nil => None,
                            value => Some(parse_ground_display(value, "camera")?),
                        },
                    )
                }
                None => (None, None, None, None, None, None, None),
            };
            if let Some(mode) = projection {
                unsafe { tick.exec(Instruction::ProjectionMode(mode))? };
            }
            if let Some(mode) = shading {
                unsafe { tick.exec(Instruction::ShadingMode(mode))? };
            }
            if let Some(mode) = ground {
                unsafe { tick.exec(Instruction::GroundDisplay(mode))? };
            }
            if projection.is_some() || shading.is_some() || ground.is_some() {
                // A settings-only call is a write, not the read below.
                if yaw.is_none() && pitch.is_none() && distance.is_none() && target.is_none() {
                    return Ok(Value::Nil);
                }
            }
            if yaw.is_none() && pitch.is_none() && distance.is_none() && target.is_none() {
                let cam = unsafe { &tick.state().cam };
                let t = lua.create_table()?;
                t.set("yaw", cam.yaw.to_degrees())?;
                t.set("pitch", cam.pitch.to_degrees())?;
                t.set("distance", cam.distance)?;
                t.set("target", vec3_lua(lua, cam.target)?)?;
                t.set(
                    "projection",
                    match cam.projection_mode() {
                        ProjectionMode::Natural => "perspective",
                        ProjectionMode::Orthographic => "orthographic",
                    },
                )?;
                // The other two view settings the gear popup holds (#1805): a script could
                // set them but had no way to read them back and assert.
                t.set("shading", cam.shading_mode().script_name())?;
                t.set("ground", cam.ground_display().script_name())?;
                return Ok(Value::Table(t));
            }
            unsafe {
                tick.exec(Instruction::SetCamera {
                    yaw,
                    pitch,
                    distance,
                    target,
                })?;
            }
            Ok(Value::Nil)
        })?,
    )?;

    // #108/#1276/#1303: frame selection or document; half-Home glide unless animation is off.
    // Native name is `_zoom_fit`; the public `zoom_fit` yields until the transition ends.
    api.set(
        "_zoom_fit",
        lua.create_function(|lua, ()| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::ZoomFit) }
        })?,
    )?;

    // #34/#94/#108: switch the Elements pane's layout ("list" | "tree" | "graph").
    api.set(
        "elements_view",
        lua.create_function(|lua, name: String| {
            let mode = crate::hierarchy::HierarchyViewMode::from_name(&name).ok_or_else(|| {
                mlua::Error::external(format!(
                    "unknown elements view '{name}' (expected 'list', 'tree', or 'graph')"
                ))
            })?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetElementsView { mode }) }
        })?,
    )?;

    // #1670: read the Graph view's one-node-per-line layout — `{ lanes = n, rows = { { name,
    // kind, lane, x, y, w, h, active, eye? = { x, y, w, h } }, ... }, edges = { { from, to, lane,
    // kind = "parent" | "dependency" | "related" },
    // ... } }`, with `from`/`to` as 1-based row numbers and an edge kind of "parent",
    // "dependency", or "related". Rows come out in the order the pane
    // draws them, with the pane's default element filter; pass `{ shadow_bodies = true }` to
    // include shadow bodies the way the filter toggle does. `x/y/w/h` are where the row was
    // drawn last frame, in window pixels like `elements_row_rect` — pass the row to `click`
    // (#1880). `eye` is the leftmost visibility toggle (#1907); pass it to `click` to hide
    // or show that element. Absent unless the Graph view painted that row / eyeball. `active`
    // is true for the drawing currently open in the Drawing workbench (#1905), even when that
    // row is not selected.
    api.set(
        "elements_graph",
        lua.create_function(|lua, opts: Option<mlua::Table>| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let state = unsafe { tick.state() };
            let mut filter = crate::hierarchy::ElementFilter::default();
            if let Some(opts) = opts {
                if let Some(show) = opts.get::<Option<bool>>("shadow_bodies")? {
                    filter.shadow_bodies = show;
                }
            }
            let mut tree = crate::hierarchy::graph_view_tree(
                &state.doc,
                state.sketch_session,
                &filter,
            );
            if state.workbench() != crate::actions::Workbench::View {
                crate::hierarchy::prune_section_planes(&mut tree);
            }
            let layout = crate::hierarchy::graph_lane_layout(&state.doc, &tree);
            // Last-frame screen position of each row, for scripts that click the pane; absent
            // for a row that was scrolled out or while another view is showing.
            let painted = crate::hierarchy::elements_graph_row_rects(unsafe { tick.egui_ctx() });
            let eyes = crate::hierarchy::elements_graph_eye_rects(unsafe { tick.egui_ctx() });
            let out = lua.create_table()?;
            out.set("lanes", layout.lane_count)?;
            let rows = lua.create_table()?;
            for (row, entry) in layout.rows.iter().enumerate() {
                let t = lua.create_table()?;
                t.set("name", crate::hierarchy::node_label(&state.doc, entry.node))?;
                t.set("kind", hierarchy_node_kind_name(entry.node))?;
                t.set("lane", entry.lane)?;
                t.set(
                    "active",
                    crate::hierarchy::node_is_open_drawing(entry.node, state.editing_drawing),
                )?;
                if let Some((_, rect)) = painted.iter().find(|(node, _)| *node == entry.node) {
                    // Window pixels, like `elements_row_rect` / `pane_rect`. `click(row)`
                    // converts to the viewport space the pointer events use (#1880).
                    t.set("x", rect.min.x)?;
                    t.set("y", rect.min.y)?;
                    t.set("w", rect.width())?;
                    t.set("h", rect.height())?;
                }
                if let Some((_, rect)) = eyes.iter().find(|(node, _)| *node == entry.node) {
                    let eye = lua.create_table()?;
                    eye.set("x", rect.min.x)?;
                    eye.set("y", rect.min.y)?;
                    eye.set("w", rect.width())?;
                    eye.set("h", rect.height())?;
                    t.set("eye", eye)?;
                }
                rows.set(row + 1, t)?;
            }
            out.set("rows", rows)?;
            let edges = lua.create_table()?;
            let mut next = 1;
            for edge in &layout.edges {
                let (Some(from), Some(to)) =
                    (layout.row_of(edge.from), layout.row_of(edge.to))
                else {
                    continue;
                };
                let t = lua.create_table()?;
                t.set("from", from + 1)?;
                t.set("to", to + 1)?;
                t.set("lane", edge.lane)?;
                t.set(
                    "kind",
                    match edge.kind {
                        crate::hierarchy::GraphLaneEdgeKind::Parent => "parent",
                        crate::hierarchy::GraphLaneEdgeKind::Dependency => "dependency",
                        crate::hierarchy::GraphLaneEdgeKind::Related => "related",
                    },
                )?;
                edges.set(next, t)?;
                next += 1;
            }
            out.set("edges", edges)?;
            Ok(Value::Table(out))
        })?,
    )?;

    // #1686: which workbench the app is in — `bearcad.ui.workbench()` reads it back
    // ("model" | "sketch" | "drawing" | "view"); passing a name switches to it, opening the
    // most recent sketch / drawing / cross-section view the way the toolbar's picker does.
    api.set(
        "workbench",
        lua.create_function(|lua, name: Option<String>| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(name) = name else {
                let state = unsafe { tick.state() };
                return Ok(Value::String(
                    lua.create_string(state.workbench().script_name())?,
                ));
            };
            let workbench = crate::actions::Workbench::from_name(&name).ok_or_else(|| {
                mlua::Error::external(format!(
                    "unknown workbench '{name}' (expected 'model', 'sketch', 'drawing', or 'view')"
                ))
            })?;
            unsafe { tick.exec(Instruction::SetWorkbench { workbench })? };
            Ok(Value::Nil)
        })?,
    )?;

    api.set(
        "pane",
        lua.create_function(|lua, (pane, visible): (String, Value)| {
            let pane = Pane::from_name(&pane)
                .ok_or_else(|| mlua::Error::external(format!("unknown pane '{pane}'")))?;
            let visible = parse_visibility(visible)?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetPane { pane, visible }) }
        })?,
    )?;

    // Last-frame pane rect in logical points (#1575), or nil when the pane is hidden.
    api.set(
        "pane_rect",
        lua.create_function(|lua, pane: String| {
            let pane = Pane::from_name(&pane)
                .ok_or_else(|| mlua::Error::external(format!("unknown pane '{pane}'")))?;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(rect) = crate::script::pane_rect(unsafe { tick.egui_ctx() }, pane) else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1712: where the Elements pane's List view drew the row with this label last frame, in
    // window pixels (like `pane_rect`) — `{ x, y, w, h }`, or `nil` when there is no such
    // row on screen (or the pane is showing the Graph). Pass the table to `click` (#1880).
    api.set(
        "elements_row_rect",
        lua.create_function(|lua, label: String| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(rect) =
                crate::hierarchy::elements_list_row_rect(unsafe { tick.egui_ctx() }, &label)
            else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1856: the items of the context menu that is open right now. `menu_items()` lists
    // their labels in the order shown; `menu_item_rect(label)` says where one landed, in
    // window pixels. Pass that table to `click` (#1880). Both are empty/nil when no menu
    // is up — the popup is an egui window a script otherwise has no way to reach into.
    api.set(
        "menu_items",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let out = lua.create_table()?;
            for (i, label) in crate::hierarchy::menu_item_labels(unsafe { tick.egui_ctx() })
                .into_iter()
                .enumerate()
            {
                out.set(i + 1, label)?;
            }
            Ok(out)
        })?,
    )?;
    api.set(
        "menu_item_rect",
        lua.create_function(|lua, label: String| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(rect) = crate::hierarchy::menu_item_rect(unsafe { tick.egui_ctx() }, &label)
            else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1828: where the Context pane drew the row labelled `label` last frame, in window
    // coordinates (like `pane_rect`) — `{ x, y, w, h }`, or `nil` when the pane is not
    // showing such a row. Unlabelled rows answer to their salt ("align_lines").
    api.set(
        "context_row_rect",
        lua.create_function(|lua, label: String| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(rect) = crate::context::context_row_rect(unsafe { tick.egui_ctx() }, &label)
            else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1846: where the page drew one circle of a zoom loupe last frame, in window
    // coordinates like `drawing_view_rect` — `{ x, y, w, h }` of the square it is inscribed
    // in, so a script can aim at its centre to move it or its rim to resize it.
    api.set(
        "drawing_loupe_rect",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "drawing_loupe_rect", &["view", "index", "magnified"])?;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let view: usize = opts.ordinal_req("view")?;
            let index: usize = opts.ordinal_req("index")?;
            let magnified: bool = opts.get::<Option<bool>>("magnified")?.unwrap_or(true);
            let Some(rect) = crate::drawing_loupe_rect(
                unsafe { tick.egui_ctx() },
                view,
                index,
                magnified,
            ) else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            // Which part of the circle does what (#1851): `band` px of rim resize it,
            // everything inside moves it, and `handle` is the dot drawn at the centre when
            // it is selected. Painted at exactly these sizes, so a script can aim at the
            // same zone a user sees.
            let radius = rect.width() * 0.5;
            t.set("band", crate::drawing::loupe_resize_band_px(radius))?;
            t.set("handle", crate::drawing::loupe_move_handle_px(radius))?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1709: where the drawing page drew a view's card last frame, in window coordinates
    // (like `pane_rect` and `tutorial_orb`) — `{ x, y, w, h }`, or `nil` when that view isn't
    // on screen.
    api.set(
        "drawing_view_rect",
        lua.create_function(|lua, view: Ordinal| {
            let view = view.0;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(rect) = crate::drawing_view_card_rect(unsafe { tick.egui_ctx() }, view) else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("x", rect.min.x)?;
            t.set("y", rect.min.y)?;
            t.set("w", rect.width())?;
            t.set("h", rect.height())?;
            Ok(Value::Table(t))
        })?,
    )?;

    // #1619: how far a pane is scrolled, and whether it has anything to scroll. `nil` when
    // the pane is hidden or scrolls nothing of its own.
    api.set(
        "pane_scroll",
        lua.create_function(|lua, pane: String| {
            let pane = Pane::from_name(&pane)
                .ok_or_else(|| mlua::Error::external(format!("unknown pane '{pane}'")))?;
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            let Some(scroll) = crate::script::pane_scroll(unsafe { tick.egui_ctx() }, pane) else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("offset", scroll.offset)?;
            t.set("content", scroll.content)?;
            t.set("viewport", scroll.viewport)?;
            Ok(Value::Table(t))
        })?,
    )?;

    // Wheel over a pane to scroll it (#1619): positive `dy` scrolls the content down.
    api.set(
        "scroll_pane",
        lua.create_function(|lua, (pane, dy): (String, f32)| {
            let pane = Pane::from_name(&pane)
                .ok_or_else(|| mlua::Error::external(format!("unknown pane '{pane}'")))?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::ScrollPane { pane, dy }) }
        })?,
    )?;

    // Open or collapse every AI pane section at once (#1619).
    api.set(
        "ai_sections",
        lua.create_function(|lua, how: String| {
            let open = match how.to_ascii_lowercase().as_str() {
                "open" => true,
                "close" | "collapse" => false,
                other => {
                    return Err(mlua::Error::external(format!(
                        "ai_sections expects 'open' or 'close', got '{other}'"
                    )))
                }
            };
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetAiSectionsOpen { open }) }
        })?,
    )?;

// #1621: the AI config pane's section titles, in draw order — a read-only mirror of
    // the headers, so a script can prove the pane split without a screenshot.
    api.set(
        "ai_pane_sections",
        lua.create_function(|lua, ()| {
            let titles = crate::ai::panel::section_titles();
            let t = lua.create_table()?;
            for (index, title) in titles.iter().enumerate() {
                t.set(index + 1, title.to_string())?;
            }
            Ok(Value::Table(t))
        })?,
    )?;

    // Open the AI pane at its MCP Server section (#1622): mirrors the Integration ▸
    // AI MCP Server… menu item, so the deep-link stays scriptable.
    api.set(
        "ai_mcp",
        lua.create_function(|lua, how: String| {
            if how.to_ascii_lowercase().as_str() != "show" {
                return Err(mlua::Error::external(format!(
                    "ai_mcp expects 'show', got '{how}'"
                )));
            }
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::ShowMcpServerSection) }
        })?,
    )?;

    // The native menu bar's shape (#1622): the OS menus can't be driven by pointer input,
    // so scripts read the structure back top-level menu title → item labels.
    api.set(
        "menu_structure",
        lua.create_function(|lua, ()| {
            let out = lua.create_table()?;
            for (title, items) in crate::native_menu::menu_structure() {
                let arr = lua.create_table()?;
                for (i, label) in items.iter().enumerate() {
                    arr.set(i + 1, label.clone())?;
                }
                out.set(title, Value::Table(arr))?;
            }
            Ok(Value::Table(out))
        })?,
    )?;

    // Whether the last instruction asked to be retried rather than run (#1814). The Lua
    // wrappers below spin on this; scripts never call it.
    api.set(
        "_deferred",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            Ok(unsafe { tick.runner() }.last_deferred)
        })?,
    )?;

    // egui multipass id-instability count (#1614). Zero on a healthy layout.
    api.set(
        "widget_id_warnings",
        lua.create_function(|_, ()| Ok(crate::diag::widget_id_change_warnings()))?,
    )?;

    // Whether this run has no OS window at all (#1815) — `--headless`, the default for
    // `--script`. A test that can only work against real windows (⌘` cycling, a helper
    // process) checks this and skips, rather than failing everywhere but CI's Xvfb job.
    api.set(
        "headless",
        lua.create_function(|lua, ()| {
            let tick = lua
                .app_data_ref::<ScriptTickData>()
                .ok_or_else(|| mlua::Error::external("script tick context missing"))?;
            Ok(unsafe { tick.state() }.headless)
        })?,
    )?;

    // #1867: name-first parameter functions. The old `parameter("add"|"value"|…)`
    // dispatcher is gone; a script names a parameter (or holds the handle `add_parameter`
    // returns) instead of an ordinal that shifts after a delete.
    api.set(
        "add_parameter",
        lua.create_function(|lua, (name, expression): (String, Value)| {
            let expression = lua_expression_string(Some(&expression), "add_parameter")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let created = unsafe { tick.exec(Instruction::AddParameter { name, expression }) }?;
            created.into_lua(lua)
        })?,
    )?;
    api.set(
        "set_parameter",
        lua.create_function(|lua, (target, expression): (Value, Value)| {
            let index = lua_parameter_index(lua, Some(&target), "set_parameter")?;
            let expression = lua_expression_string(Some(&expression), "set_parameter")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::SetParameterExpression { index, expression }) }
        })?,
    )?;
    api.set(
        "parameter_value",
        lua.create_function(|lua, target: Value| {
            let Some(index) = lua_parameter_index_opt(lua, Some(&target), "parameter_value")? else {
                return Ok(Value::Nil);
            };
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let doc = unsafe { &tick.state().doc };
            let Some(param) = doc.parameters.values().nth(index) else {
                return Ok(Value::Nil);
            };
            lua_parameter_value(lua, &param.expression)
        })?,
    )?;
    api.set(
        "parameter_expression",
        lua.create_function(|lua, target: Value| {
            let Some(index) = lua_parameter_index_opt(lua, Some(&target), "parameter_expression")?
            else {
                return Ok(Value::Nil);
            };
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let doc = unsafe { &tick.state().doc };
            let Some(param) = doc.parameters.values().nth(index) else {
                return Ok(Value::Nil);
            };
            Ok(Value::String(lua.create_string(&param.expression)?))
        })?,
    )?;
    api.set(
        "delete_parameter",
        lua.create_function(|lua, target: Value| {
            let index = lua_parameter_index(lua, Some(&target), "delete_parameter")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::DeleteParameter { index }) }
        })?,
    )?;
    api.set(
        "edit_parameter",
        lua.create_function(|lua, opts: Table| {
            check_keys(
                &opts,
                "edit_parameter",
                &["name", "private", "min", "max", "step", "rename"],
            )?;
            let target: Value = opts.get("name").map_err(|_| {
                mlua::Error::external("edit_parameter requires a `name` (string or handle)")
            })?;
            let index = lua_parameter_index(lua, Some(&target), "edit_parameter")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            if let Some(name) = opts.get::<Option<String>>("rename")? {
                unsafe { tick.exec(Instruction::SetParameterName { index, name })? };
            }
            if opts.contains_key("private")? {
                let private: bool = opts.get("private")?;
                unsafe {
                    tick.exec(Instruction::SetParameterPrimary {
                        index,
                        primary: !private,
                    })?;
                }
            }
            for (key, which) in [
                ("min", crate::parameters::ParameterBound::Minimum),
                ("max", crate::parameters::ParameterBound::Maximum),
                ("step", crate::parameters::ParameterBound::Step),
            ] {
                if opts.contains_key(key)? {
                    let expression = lua_bound_expression(opts.get(key)?, key)?;
                    unsafe {
                        tick.exec(Instruction::SetParameterBound {
                            index,
                            which,
                            expression,
                        })?;
                    }
                }
            }
            Ok(Value::Nil)
        })?,
    )?;
    api.set(
        "parameter_from_line_length",
        lua.create_function(|lua, (line, name): (Value, Option<String>)| {
            let line_index = lua_index_arg(lua, Some(&line), "parameter_from_line_length")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let created = unsafe {
                tick.exec(Instruction::CreateParameterFromLineLength { line_index, name })?
            };
            created.into_lua(lua)
        })?,
    )?;
    api.set(
        "parameter_options",
        lua.create_function(|lua, (target, open): (Value, Option<bool>)| {
            let index = lua_parameter_index(lua, Some(&target), "parameter_options")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            let Some(key) = state.doc.parameters.keys().nth(index) else {
                return Err(mlua::Error::external(format!("Parameter {index} not found")));
            };
            match open {
                None => Ok(Value::Boolean(
                    state.parameters_pane.options_open.contains(&key),
                )),
                Some(true) => {
                    state.parameters_pane.options_open.insert(key);
                    Ok(Value::Nil)
                }
                Some(false) => {
                    state.parameters_pane.options_open.remove(&key);
                    if state
                        .parameters_pane
                        .options_editing
                        .is_some_and(|(k, _)| k == key)
                    {
                        state.parameters_pane.options_editing = None;
                        state.parameters_pane.options_draft.clear();
                    }
                    Ok(Value::Nil)
                }
            }
        })?,
    )?;
    api.set(
        "parameter_edit",
        lua.create_function(|lua, (target, field): (Value, String)| {
            let index = lua_parameter_index(lua, Some(&target), "parameter_edit")?;
            let which = crate::parameters::ParameterBound::from_name(&field).ok_or_else(|| {
                mlua::Error::external("parameter_edit field must be \"min\", \"max\", or \"step\"")
            })?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            let Some(key) = state.doc.parameters.keys().nth(index) else {
                return Err(mlua::Error::external(format!("Parameter {index} not found")));
            };
            let current = crate::parameters::bound_expression(&state.doc.parameters[key], which)
                .unwrap_or("")
                .to_string();
            state
                .parameters_pane
                .begin_options_edit(key, which, &current);
            Ok(Value::Nil)
        })?,
    )?;
    api.set(
        "parameter_editing",
        lua.create_function(|lua, ()| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            let Some((key, which)) = state.parameters_pane.options_editing else {
                return Ok(Value::Nil);
            };
            let Some(index) = state.doc.parameters.keys().position(|k| k == key) else {
                return Ok(Value::Nil);
            };
            let t = lua.create_table()?;
            t.set("index", index)?;
            t.set("name", state.doc.parameters[key].name.as_str())?;
            t.set("field", which.script_name())?;
            Ok(Value::Table(t))
        })?,
    )?;
    api.set(
        "parameter_slider",
        lua.create_function(|lua, (target, value): (Value, Option<Value>)| {
            let Some(index) = lua_parameter_index_opt(lua, Some(&target), "parameter_slider")? else {
                return Ok(Value::Nil);
            };
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let spec = {
                let doc = unsafe { &tick.state().doc };
                doc.parameters.keys().nth(index).and_then(|key| {
                    crate::parameters::parameter_slider_spec(doc, &doc.parameters[key])
                })
            };
            let Some(spec) = spec else {
                return Ok(Value::Nil);
            };
            match value {
                None | Some(Value::Nil) => {
                    let t = lua.create_table()?;
                    t.set("min", spec.min as f64)?;
                    t.set("max", spec.max as f64)?;
                    t.set("value", spec.current as f64)?;
                    if let Some(step) = spec.limits.step {
                        t.set("step", step as f64)?;
                    }
                    Ok(Value::Table(t))
                }
                Some(Value::Integer(_) | Value::Number(_)) => {
                    let v = match value {
                        Some(Value::Integer(i)) => i as f32,
                        Some(Value::Number(n)) => n as f32,
                        _ => unreachable!(),
                    };
                    let expression = {
                        let doc = unsafe { &tick.state().doc };
                        let key = doc.parameters.keys().nth(index).unwrap();
                        crate::parameters::parameter_slider_expression(
                            doc,
                            &doc.parameters[key],
                            v,
                        )
                    }
                    .ok_or_else(|| mlua::Error::external("parameter has no slider"))?;
                    unsafe {
                        tick.exec(Instruction::SetParameterExpression { index, expression })?;
                    }
                    Ok(Value::Nil)
                }
                _ => Err(mlua::Error::external(
                    "parameter_slider value must be a number (mm / degrees)",
                )),
            }
        })?,
    )?;

