    // #1288: auto-update channel — "release" (default) or "pre_release".
    // No arg / nil returns the current channel string.
    api.set(
        "update_channel",
        lua.create_function(|lua, channel: Option<String>| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            match channel {
                None => {
                    let state = unsafe { tick.state() };
                    Ok(Some(state.update_channel.as_str().to_string()))
                }
                Some(s) => {
                    let channel = crate::settings::UpdateChannel::parse(&s).ok_or_else(|| {
                        mlua::Error::external(format!(
                            "update_channel expects \"release\" or \"pre_release\", got {s:?}"
                        ))
                    })?;
                    unsafe { tick.exec(Instruction::SetUpdateChannel { channel })? };
                    Ok(None)
                }
            }
        })?,
    )?;

    // World corners of a tracing image (including an in-progress Move preview, #1611).
    api.set(
        "image_corners",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            let image = state
                .doc
                .tracing_images
                .keys()
                .nth(index)
                .ok_or_else(|| mlua::Error::external(format!("no image {index}")))?;
            let pose = crate::actions::live_image_pose(
                &state.doc,
                image,
                state.creating_move.as_ref(),
            );
            let corners = crate::construction::tracing_image_live_corners(
                &state.doc,
                image,
                pose,
            )
            .ok_or_else(|| mlua::Error::external(format!("image {index} has no corners")))?;
            let table = lua.create_table()?;
            for (i, p) in corners.iter().enumerate() {
                let row = lua.create_table()?;
                row.set(1, p.x)?;
                row.set(2, p.y)?;
                row.set(3, p.z)?;
                table.set(i + 1, row)?;
            }
            Ok(table)
        })?,
    )?;

    // Read a line's current endpoints (sketch-local mm) — the assertion hook for
    // interaction regression tests.
    // #1799: `extrude_edges(i)` lists the analytic edges of extrusion `i` in exactly the
    // shape `fillet_edge`/`chamfer_edge` accept — no guessing magic (face, edge) pairs.
    api.set(
        "extrude_edges",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let doc = unsafe { &tick.state().doc };
            let Some(ext) = doc.extrusions.keys().nth(index).map(|k| &doc.extrusions[k]) else {
                return Err(mlua::Error::external(format!("no extrusion {index}")));
            };
            let out = lua.create_table()?;
            let mut n = 0usize;
            for (fi, face) in ext.faces.iter().enumerate() {
                match face {
                    // A circle's rim is one closed edge: the top and bottom cap rims.
                    crate::model::ExtrudeFace::Circle(_) => {
                        for (kind, top) in [("bottom", false), ("top", true)] {
                            let e = lua.create_table()?;
                            e.set("kind", kind)?;
                            e.set("face", fi)?;
                            e.set("edge", 0)?;
                            e.raw_set("top", top)?;
                            n += 1;
                            out.set(n, e)?;
                        }
                    }
                    other => {
                        let count = crate::extrude::side_face_count(other);
                        for edge in 0..count {
                            let e = lua.create_table()?;
                            e.set("kind", "vertical")?;
                            e.set("face", fi)?;
                            e.set("edge", edge)?;
                            n += 1;
                            out.set(n, e)?;
                        }
                        for edge in 0..count {
                            for (kind, top) in [("bottom", false), ("top", true)] {
                                let e = lua.create_table()?;
                                e.set("kind", kind)?;
                                e.set("face", fi)?;
                                e.set("edge", edge)?;
                                e.raw_set("top", top)?;
                                n += 1;
                                out.set(n, e)?;
                            }
                        }
                    }
                }
            }
            Ok(out)
        })?,
    )?;

    api.set(
        "line_endpoints",
        lua.create_function(|lua, index: Ordinal| {
            let index = index.0;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            // The script's `index` is the line's ordinal (#1055).
            let Some(line) = state.doc.lines.keys().nth(index).map(|k| &state.doc.lines[k])
            else {
                return Ok(mlua::MultiValue::new());
            };
            (line.x0, line.y0, line.x1, line.y1).into_lua_multi(lua)
        })?,
    )?;

