    // Project outside 3D geometry into the active sketch (#1351): the declarative
    // equivalent of the Project tool + Enter. Empty / omitted sources use the current
    // selection (and un-project when that selection is only already-projected lines).
    api.set(
        "project",
        lua.create_function(|lua, opts: Option<Table>| {
            let elements = parse_project_elements(lua, opts)?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::Project { elements }) }
        })?,
    )?;

    api.set(
        "revolve",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let faces = collect_extrude_faces(lua, &opts)?;
            if faces.is_empty() {
                return Err(mlua::Error::external(
                    "revolve requires `profiles` (a circle, a line loop, or a list of those)",
                ));
            }
            let axis = parse_revolve_axis(lua, opts.get::<mlua::Value>("axis")?, "revolve")?;
            // #1242: `revolutions` (turns) wins over `angle` (degrees) when both are set.
            // Either may be a number or an expression string (#1489).
            let (angle_deg, angle_expression, angle_is_revolutions) =
                if let Some((turns, turns_expr)) = scalar_arg(lua, &opts, "revolutions")? {
                    let expr = turns_expr.unwrap_or_default();
                    let turns = if expr.is_empty() {
                        turns
                    } else {
                        crate::value::eval_length_mm_in_doc(&expr, unsafe { &tick.state().doc })
                            .unwrap_or(turns)
                    };
                    (turns * 360.0, expr, true)
                } else if let Some((deg, deg_expr)) = scalar_arg(lua, &opts, "angle")? {
                    let expr = deg_expr.unwrap_or_default();
                    let deg = if expr.is_empty() {
                        deg
                    } else {
                        crate::value::eval_angle_rad_in_doc(&expr, unsafe { &tick.state().doc })
                            .map(|r| r.to_degrees())
                            .unwrap_or(deg)
                    };
                    (deg, expr, false)
                } else {
                    (360.0, String::new(), false)
                };
            check_keys(
                &opts,
                "revolve",
                &[
                    "profiles",
                    "circle",
                    "circles",
                    "polygon",
                    "polygons",
                    "axis",
                    "symmetric",
                    "bodies",
                    "body",
                    "revolutions",
                    "angle",
                    "pitch",
                    "name", "shape_name", "body_name",
                ],
            )?;
            // Helical pitch (mm per full turn) is `pitch` only (#1894).
            let pitch_arg = scalar_arg(lua, &opts, "pitch")?;
            let (pitch_mm, pitch_expression) = if let Some((v, e)) = pitch_arg {
                let expr = e.unwrap_or_default();
                let v = if expr.is_empty() {
                    v
                } else {
                    crate::value::eval_length_mm_in_doc(&expr, unsafe { &tick.state().doc })
                        .unwrap_or(v)
                };
                (v, expr)
            } else {
                (0.0, String::new())
            };
            let symmetric: bool = opts.get::<Option<bool>>("symmetric")?.unwrap_or(false);
            let bodies: Vec<usize> = opts.ordinal_list("bodies")?;
            let body = crate::actions::RevolveBodyChoice::from_script(
                opts.get::<Option<String>>("body")?.as_deref(),
            )
            .map_err(mlua::Error::external)?;
            unsafe {
                tick.exec(Instruction::Revolve {
                    faces,
                    axis,
                    angle_deg,
                    angle_expression,
                    angle_is_revolutions,
                    pitch_mm,
                    pitch_expression,
                    symmetric,
                    body,
                    bodies,
                })?;
            }
            let key = unsafe { tick.state().doc.bodies.keys().last() };
            let element =
                SceneElement::Body(key.ok_or_else(|| mlua::Error::external("no body was made"))?);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    api.set(
        "edit_revolve",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(
                &opts,
                "edit_revolve",
                &[
                    "index",
                    "circle",
                    "circles",
                    "polygon",
                    "axis",
                    "angle",
                    "revolutions",
                    "pitch",
                    "offset",
                    "gap",
                    "symmetric",
                    "body",
                    "bodies",
                    "name", "shape_name", "body_name",
                ],
            )?;
            let op: usize = opts.ordinal_req("index")?;
            let faces = named_profile_faces(lua, &opts, false)?;
            let axis = match opts.get::<Option<mlua::Value>>("axis")? {
                Some(v) if !matches!(v, mlua::Value::Nil) => {
                    Some(parse_revolve_axis(lua, v, "edit_revolve")?)
                }
                _ => None,
            };
            let (angle_deg, angle_expression, angle_is_revolutions) =
                if let Some((turns, turns_expr)) = scalar_arg(lua, &opts, "revolutions")? {
                    let expr = turns_expr.unwrap_or_default();
                    let turns = if expr.is_empty() {
                        turns
                    } else {
                        crate::value::eval_length_mm_in_doc(&expr, unsafe { &tick.state().doc })
                            .unwrap_or(turns)
                    };
                    (Some(turns * 360.0), Some(expr), Some(true))
                } else if let Some((deg, deg_expr)) = scalar_arg(lua, &opts, "angle")? {
                    let expr = deg_expr.unwrap_or_default();
                    let deg = if expr.is_empty() {
                        deg
                    } else {
                        crate::value::eval_angle_rad_in_doc(&expr, unsafe { &tick.state().doc })
                            .map(|r| r.to_degrees())
                            .unwrap_or(deg)
                    };
                    (Some(deg), Some(expr), Some(false))
                } else {
                    (None, None, None)
                };
            let pitch_arg = match scalar_arg(lua, &opts, "pitch")? {
                Some(v) => Some(v),
                None => match scalar_arg(lua, &opts, "offset")? {
                    Some(v) => Some(v),
                    None => scalar_arg(lua, &opts, "gap")?,
                },
            };
            let (pitch_mm, pitch_expression) = if let Some((v, e)) = pitch_arg {
                let expr = e.unwrap_or_default();
                let v = if expr.is_empty() {
                    v
                } else {
                    crate::value::eval_length_mm_in_doc(&expr, unsafe { &tick.state().doc })
                        .unwrap_or(v)
                };
                (Some(v), Some(expr))
            } else {
                (None, None)
            };
            let symmetric: Option<bool> = opts.get("symmetric")?;
            let bodies = opts.ordinal_list_opt("bodies")?;
            let body = match opts.get::<Option<String>>("body")? {
                Some(s) => Some(
                    crate::actions::RevolveBodyChoice::from_script(Some(s.as_str()))
                        .map_err(mlua::Error::external)?,
                ),
                None => None,
            };
            let element = unsafe {
                tick.exec(Instruction::EditRevolve {
                    op,
                    faces,
                    axis,
                    angle_deg,
                    angle_expression,
                    angle_is_revolutions,
                    pitch_mm,
                    pitch_expression,
                    symmetric,
                    body,
                    bodies,
                })?;
                SceneElement::Revolution(
                    tick.state()
                        .doc
                        .revolutions
                        .keys()
                        .nth(op)
                        .ok_or_else(|| mlua::Error::external(format!("no revolution {op}")))?,
                )
            };
            drop(tick);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    // Primitive shapes (#909/#1883): `bearcad.cuboid{ … }`, aliases `cube`/`box`
    // (`cube{ size = 10 }` for equal sides), `bearcad.cylinder{ r|radius|diameter, height }`,
    // `bearcad.sphere{ r|radius|diameter }`. Every dimension takes a number or an expression
    // string; `at` defaults to the origin and `normal` to +Z (the ground).
    // `bearcad.edit_shape{ index =, shape = "cuboid", ... }` re-points one.
    for (call, kind) in [
        ("cuboid", crate::model::PrimitiveKind::Cuboid),
        ("cube", crate::model::PrimitiveKind::Cuboid),
        ("box", crate::model::PrimitiveKind::Cuboid),
        ("cylinder", crate::model::PrimitiveKind::Cylinder),
        ("sphere", crate::model::PrimitiveKind::Sphere),
    ] {
        api.set(
            call,
            lua.create_function(move |lua, opts: Option<Table>| {
                let opts = match opts {
                    Some(t) => t,
                    None => lua.create_table()?,
                };
                let shape = parse_shape_args(lua, &opts, kind, call)?;
                let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
                unsafe { tick.exec(Instruction::Shape { shape })? };
                let key = unsafe { tick.state().doc.primitives.keys().last() };
                let element = SceneElement::Shape(
                    key.ok_or_else(|| mlua::Error::external("shape was not created"))?,
                );
                drop(tick);
                apply_optional_name(lua, element, Some(opts))
            })?,
        )?;
    }

    api.set(
        "edit_shape",
        lua.create_function(|lua, opts: Table| {
            check_shape_keys(&opts, "edit_shape")?;
            // The script's `index` is the shape's ordinal among the live ones (#1055).
            let ordinal: usize = opts.ordinal_req("index")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let index = unsafe { tick.state().doc.primitives.keys().nth(ordinal) }
                .ok_or_else(|| mlua::Error::external(format!("no shape {ordinal}")))?;
            let existing = unsafe { tick.state().doc.primitives.get(index).cloned() };
            drop(tick);
            let kind = match opts.get::<Option<String>>("shape")? {
                Some(name) => crate::model::PrimitiveKind::from_name(&name).ok_or_else(|| {
                    mlua::Error::external(format!(
                        "unknown shape '{name}' (cuboid|cylinder|sphere)"
                    ))
                })?,
                None => existing
                    .as_ref()
                    .map(|s| s.kind)
                    .ok_or_else(|| mlua::Error::external(format!("no shape {ordinal}")))?,
            };
            let mut shape = parse_shape_args(lua, &opts, kind, "edit_shape")?;
            // Unmentioned dimensions keep what the shape already had.
            if let Some(old) = existing {
                let size_set = opts.contains_key("size")?;
                if !opts.contains_key("width")? && !size_set {
                    shape.width = old.width.clone();
                }
                if !opts.contains_key("depth")? && !size_set {
                    shape.depth = old.depth.clone();
                }
                if !opts.contains_key("height")? && !size_set {
                    shape.height = old.height.clone();
                }
                if !opts.contains_key("radius")?
                    && !opts.contains_key("r")?
                    && !opts.contains_key("diameter")?
                {
                    shape.radius = old.radius.clone();
                }
                if !opts.contains_key("at")? {
                    shape.origin = old.origin;
                    // …and the expressions driving it (#1929), or an edit that only
                    // changed a size would freeze the placement it left alone.
                    shape.origin_expression = old.origin_expression.clone();
                }
                if !opts.contains_key("normal")? { shape.normal = old.normal; }
                if !opts.contains_key("u_axis")? { shape.u_axis = old.u_axis; }
            }
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::EditShape { index: ordinal, shape })? };
            drop(tick);
            apply_optional_name(lua, SceneElement::Shape(index), Some(opts))
        })?,
    )?;
    // Reopen a committed shape in the Shape tool (#1901): the Context pane's ValueInputs
    // load the current dimensions so they can be edited. `bearcad.ui.begin_edit_shape{ index }`.
    api.set(
        "begin_edit_shape",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "begin_edit_shape", &["index"])?;
            let ordinal: usize = opts.ordinal_req("index")?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            unsafe { tick.exec(Instruction::BeginEditShape { index: ordinal }) }
        })?,
    )?;

    // Sweep profiles along a path of sketch lines (SPEC §3.5 Sweep):
    // `bearcad.sweep{ profiles = circle | {lines} | {…}, path = {line, ...},
    // body = "add"|"cut"?, bodies = {i, ...}? }`. Each face's sketch is inferred
    // like `extrude`'s; the path lines are chained tip-to-tail.
    api.set(
        "sweep",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let faces = collect_extrude_faces(lua, &opts)?;
            if faces.is_empty() {
                return Err(mlua::Error::external(
                    "sweep requires `profiles` (a circle, a line loop, or a list of those)",
                ));
            }
            let path =
                line_keys_from_ordinals(lua, opts.ordinal_list("path")?)?;
            if path.is_empty() {
                return Err(mlua::Error::external(
                    "sweep requires `path` (a list of line indices)",
                ));
            }
            let bodies: Vec<usize> = opts.ordinal_list("bodies")?;
            let body = crate::actions::RevolveBodyChoice::from_script(
                opts.get::<Option<String>>("body")?.as_deref(),
            )
            .map_err(mlua::Error::external)?;
            unsafe {
                tick.exec(Instruction::Sweep { faces, path, body, bodies })?;
            }
            let key = unsafe { tick.state().doc.bodies.keys().last() };
            let element =
                SceneElement::Body(key.ok_or_else(|| mlua::Error::external("no body was made"))?);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    api.set(
        "edit_sweep",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(
                &opts,
                "edit_sweep",
                &[
                    "index",
                    "circle",
                    "circles",
                    "polygon",
                    "path",
                    "body",
                    "bodies",
                    "name", "shape_name", "body_name",
                ],
            )?;
            let op: usize = opts.ordinal_req("index")?;
            let faces = named_profile_faces(lua, &opts, false)?;
            let path = match opts.ordinal_list_opt("path")? {
                Some(lines) => {
                    let path = line_keys_from_ordinals(lua, lines)?;
                    if path.is_empty() {
                        return Err(mlua::Error::external(
                            "edit_sweep `path` must name at least one line",
                        ));
                    }
                    Some(path)
                }
                None => None,
            };
            let bodies = opts.ordinal_list_opt("bodies")?;
            let body = match opts.get::<Option<String>>("body")? {
                Some(s) => Some(
                    crate::actions::RevolveBodyChoice::from_script(Some(s.as_str()))
                        .map_err(mlua::Error::external)?,
                ),
                None => None,
            };
            let element = unsafe {
                tick.exec(Instruction::EditSweep {
                    op,
                    faces,
                    path,
                    body,
                    bodies,
                })?;
                SceneElement::SweepOp(
                    tick.state()
                        .doc
                        .sweeps
                        .keys()
                        .nth(op)
                        .ok_or_else(|| mlua::Error::external(format!("no sweep {op}")))?,
                )
            };
            drop(tick);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    // Loft a solid through two or more closed cross-section profiles (SPEC §3.5).
    // `profiles` lists the sections (circle handles, line loops, or a mix); `circle`/
    // `circles`/`polygon`/`polygons` stay as aliases. Section order along the loft is
    // recovered from the geometry.
    api.set(
        "loft",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let faces = collect_extrude_faces(lua, &opts)?;
            if faces.len() < 2 {
                return Err(mlua::Error::external(
                    "loft requires at least two sections (`profiles`)",
                ));
            }
            let bodies: Vec<usize> = opts.ordinal_list("bodies")?;
            let body = crate::actions::RevolveBodyChoice::from_script(
                opts.get::<Option<String>>("body")?.as_deref(),
            )
            .map_err(mlua::Error::external)?;
            unsafe {
                tick.exec(Instruction::Loft { faces, body, bodies })?;
            }
            let key = unsafe { tick.state().doc.bodies.keys().last() };
            let element =
                SceneElement::Body(key.ok_or_else(|| mlua::Error::external("no body was made"))?);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    api.set(
        "edit_loft",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(
                &opts,
                "edit_loft",
                &[
                    "index",
                    "circle",
                    "circles",
                    "polygon",
                    "polygons",
                    "body",
                    "bodies",
                    "name", "shape_name", "body_name",
                ],
            )?;
            let op: usize = opts.ordinal_req("index")?;
            let faces = named_profile_faces(lua, &opts, true)?;
            if let Some(faces) = &faces {
                if faces.len() < 2 {
                    return Err(mlua::Error::external(
                        "edit_loft requires at least two sections (`circles`/`polygons`)",
                    ));
                }
            }
            let bodies = opts.ordinal_list_opt("bodies")?;
            let body = match opts.get::<Option<String>>("body")? {
                Some(s) => Some(
                    crate::actions::RevolveBodyChoice::from_script(Some(s.as_str()))
                        .map_err(mlua::Error::external)?,
                ),
                None => None,
            };
            let element = unsafe {
                tick.exec(Instruction::EditLoft {
                    op,
                    faces,
                    body,
                    bodies,
                })?;
                SceneElement::Loft(
                    tick.state()
                        .doc
                        .lofts
                        .keys()
                        .nth(op)
                        .ok_or_else(|| mlua::Error::external(format!("no loft {op}")))?,
                )
            };
            drop(tick);
            apply_optional_name(lua, element, Some(opts))
        })?,
    )?;

    // Technical drawings (#180): `bearcad.drawing{ name? }` creates a drawing (and opens its
    // pane), returning a handle; `bearcad.drawing_view{ drawing, body|bodies|component|sketch,
    // orientation? }` adds a projection. Multi-body and whole-component views are #1190/#1191.
    api.set(
        "drawing",
        lua.create_function(|lua, opts: Option<Table>| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let name: Option<String> = match &opts {
                Some(t) => t.get("name")?,
                None => None,
            };
            unsafe { tick.exec(Instruction::CreateDrawing { name }) }
        })?,
    )?;
    // Cross-section views (#1671): `bearcad.cross_section{ name? }` adds one and returns a
    // handle. The planes it cuts with are added with the View workbench's plane tool.
    api.set(
        "cross_section",
        lua.create_function(|lua, opts: Option<Table>| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let name: Option<String> = match &opts {
                Some(t) => {
                    check_keys(t, "cross_section", &["name"])?;
                    t.get("name")?
                }
                None => None,
            };
            unsafe { tick.exec(Instruction::CreateCrossSection { name }) }
        })?,
    )?;
    // #1687/#1769: a cross-section view's cutting planes. `plane` anchors on a construction
    // plane's frame; `origin`/`normal` set it outright. `view` defaults to the open one.
    // `bodies` scopes the cut (`"all"`, the default, or a list of body indices); so does
    // `exclude_bodies`, whose list is spared even when the cut covers them.
    api.set(
        "section_plane",
        lua.create_function(|lua, opts: Table| {
            check_keys(
                &opts,
                "section_plane",
                &["view", "plane", "origin", "normal", "offset", "roll", "depth", "flip", "bodies", "exclude_bodies"],
            )?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let view: Option<usize> = opts.ordinal_opt("view")?;
            let cut_bodies =
                section_plane_body_scope(&opts, "bodies")?.unwrap_or(None);
            let exclude_bodies = match section_plane_body_scope(&opts, "exclude_bodies")? {
                None => Vec::new(),
                Some(None) => {
                    return Err(mlua::Error::external(
                        "exclude_bodies takes \"none\" or a table of body indices",
                    ))
                }
                Some(Some(list)) => list,
            };
            let instr = Instruction::AddSectionPlane {
                view,
                plane: opts.get("plane")?,
                origin: match opts.get::<Option<Table>>("origin")? {
                    Some(_) => Some(parse_xyz(&opts, "origin")?),
                    None => None,
                },
                normal: match opts.get::<Option<Table>>("normal")? {
                    Some(_) => Some(parse_xyz(&opts, "normal")?),
                    None => None,
                },
                offset: opts.get("offset")?,
                roll_deg: opts.get("roll")?,
                // `depth` is the cut depth (#1845): a length, or absent/`false` to run
                // all the way through.
                depth: cut_depth(&opts)?.flatten(),
                flip: opts.get("flip")?,
                cut_bodies,
                exclude_bodies,
            };
            unsafe { tick.exec(instr)? };
            let state = unsafe { tick.state() };
            let key = match view {
                Some(ordinal) => state.doc.cross_sections.keys().nth(ordinal),
                None => state.editing_cross_section,
            };
            Ok(key
                .and_then(|k| state.doc.cross_sections.get(k))
                .map(|v| v.cuts.len().saturating_sub(1))
                .unwrap_or(0))
        })?,
    )?;
    // #1689: section a projection already on the page, or clear its section with `false`.
    api.set(
        "drawing_view_section",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "drawing_view_section", &["drawing", "view", "cross_section"])?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            // #1951: every operand here takes a handle, an id or a name like the rest of
            // the API — `drawing` and `view` read a raw number, so passing the handle
            // `bearcad.drawing{}` returned failed with a Lua-userdata conversion error.
            let cross_section = match opts.get::<Value>("cross_section")? {
                Value::Nil | Value::Boolean(false) => None,
                ref value => Some(
                    Ordinal::from_lua(value.clone(), lua)
                        .map_err(|e| {
                            mlua::Error::external(format!(
                                "cross_section expects a cross-section view or false, got {}: {e}",
                                describe_lua_value(value)
                            ))
                        })?
                        .0,
                ),
            };
            let instr = Instruction::SetDrawingViewCrossSection {
                drawing: opts.ordinal_req("drawing")?,
                view: opts.ordinal_req("view")?,
                cross_section,
            };
            unsafe { tick.exec(instr) }
        })?,
    )?;
    api.set(
        "edit_section_plane",
        lua.create_function(|lua, opts: Table| {
            check_keys(
                &opts,
                "edit_section_plane",
                &["view", "cut", "offset", "roll", "depth", "flip", "bodies", "exclude_bodies"],
            )?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let instr = Instruction::EditSectionPlane {
                view: opts.ordinal_opt("view")?,
                cut: opts.ordinal_req("cut")?,
                offset: opts.get("offset")?,
                roll_deg: opts.get("roll")?,
                // `depth` is left alone when absent; `false` runs the cut through again;
                // a length bounds it (#1845).
                depth: cut_depth(&opts)?,
                flip: opts.get("flip")?,
                // `bodies` is left alone when absent; `"all"`/`true` restores every body;
                // a table restricts the cut to those bodies (#1769).
                cut_bodies: section_plane_body_scope(&opts, "bodies")?,
                // `exclude_bodies` likewise; `false`/an empty table clears the exclusions.
                exclude_bodies: match section_plane_body_scope(&opts, "exclude_bodies")? {
                    None => None,
                    Some(None) => Some(Vec::new()),
                    Some(Some(list)) => Some(list),
                },
            };
            unsafe { tick.exec(instr) }
        })?,
    )?;
    api.set(
        "delete_section_plane",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "delete_section_plane", &["view", "cut"])?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let instr = Instruction::DeleteSectionPlane {
                view: opts.ordinal_opt("view")?,
                cut: opts.ordinal_req("cut")?,
            };
            unsafe { tick.exec(instr) }
        })?,
    )?;
    // Open the live edit draft of a cutting plane (#1787): the offset/tilt gizmos preview
    // in place of the plane being edited (#1783) until Enter commits or Esc cancels.
    // `bearcad.ui.begin_edit_section_plane{ view?, cut }`.
    api.set(
        "begin_edit_section_plane",
        lua.create_function(|lua, opts: Table| {
            check_keys(&opts, "begin_edit_section_plane", &["view", "cut"])?;
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let instr = Instruction::BeginEditSectionPlane {
                view: opts.ordinal_opt("view")?,
                cut: opts.ordinal_req("cut")?,
            };
            unsafe { tick.exec(instr) }
        })?,
    )?;
    // Read a view's cutting planes back: `{ origin, normal, offset, roll (degrees), flip,
    // bodies ("all" or body indices), excludes (body indices) }`.
    api.set(
        "section_planes",
        lua.create_function(|lua, view: Option<Value>| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            let state = unsafe { tick.state() };
            // The view is a cross-section: give its ordinal, or its name (#1800).
            let key = match view {
                None => state.editing_cross_section,
                Some(Value::Integer(i)) => state.doc.cross_sections.keys().nth(i as usize),
                Some(Value::Number(n)) => state.doc.cross_sections.keys().nth(n.round() as usize),
                Some(Value::String(s)) => {
                    let name = s.to_str()?.to_string();
                    let found = state
                        .doc
                        .cross_sections
                        .iter()
                        .find(|(_, v)| v.name.as_deref() == Some(name.as_str()))
                        .map(|(k, _)| k);
                    let found = found.ok_or_else(|| {
                        mlua::Error::external(format!(
                            "section_planes: no cross-section view named '{name}'"
                        ))
                    })?;
                    Some(found)
                }
                Some(other) => {
                    return Err(mlua::Error::external(format!(
                        "section_planes: `view` must be a cross-section index or name, got {other:?}"
                    )))
                }
            };
            let out = lua.create_table()?;
            let Some(view) = key.and_then(|k| state.doc.cross_sections.get(k)) else {
                return Ok(out);
            };
            for (i, cut) in view.cuts.iter().enumerate() {
                let t = lua.create_table()?;
                t.set("origin", vec3_lua(lua, cut.origin)?)?;
                t.set("normal", vec3_lua(lua, cut.normal)?)?;
                t.set("offset", cut.offset_mm)?;
                t.set("roll", cut.roll.to_degrees())?;
                // The cut depth (#1845): a length, or `false` when the cut runs through.
                match cut.depth_mm {
                    Some(depth) => t.set("depth", depth)?,
                    None => t.set("depth", false)?,
                }
                t.set("flip", cut.flip)?;
                match &cut.cut_bodies {
                    None => t.set("bodies", "all")?,
                    Some(list) => {
                        let bodies: Vec<usize> = list
                            .iter()
                            .map(|&k| state.doc.bodies.keys().position(|b| b == k).unwrap_or(0))
                            .collect();
                        t.set("bodies", bodies)?;
                    }
                }
                let excludes: Vec<usize> = cut
                    .exclude_bodies
                    .iter()
                    .map(|&k| state.doc.bodies.keys().position(|b| b == k).unwrap_or(0))
                    .collect();
                t.set("excludes", excludes)?;
                out.set(i + 1, t)?;
            }
            Ok(out)
        })?,
    )?;

    api.set(
        "drawing_view",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(
                &opts,
                "drawing_view",
                &["drawing", "body", "bodies", "component", "sketch", "cross_section", "orientation"],
            )?;
            let drawing: usize = opts.ordinal_req("drawing")?;
            let orientation = match opts.get::<Option<String>>("orientation")? {
                Some(name) => crate::model::DrawingOrientation::from_name(&name).ok_or_else(|| {
                    mlua::Error::external(format!("unknown drawing orientation '{name}'"))
                })?,
                None => crate::model::DrawingOrientation::default(),
            };
            // A view projects a body, several bodies, a component, or a sketch (#278/#403/#1190/#1191).
            let body: Option<usize> = opts.ordinal_opt("body")?;
            let bodies: Option<Vec<usize>> = opts.ordinal_list_opt("bodies")?;
            let component: Option<usize> = opts.ordinal_opt("component")?;
            let sketch: Option<usize> = opts.ordinal_opt("sketch")?;
            // A whole cross-section view can be imported too (#1689): the model's bodies, cut.
            let cross_section: Option<usize> = opts.ordinal_opt("cross_section")?;
            let source_count = usize::from(body.is_some())
                + usize::from(bodies.is_some())
                + usize::from(component.is_some())
                + usize::from(sketch.is_some())
                + usize::from(cross_section.is_some());
            // `cross_section` alone imports the whole view; alongside a body source it
            // sections *those* bodies instead (#1689).
            let sections_bodies = cross_section.is_some() && source_count == 2 && sketch.is_none();
            if source_count != 1 && !sections_bodies {
                return Err(mlua::Error::external(
                    "drawing_view requires exactly one of `body`, `bodies`, `component`, `sketch`, or `cross_section`",
                ));
            }
            unsafe {
                if let Some(view) = cross_section {
                    if source_count == 1 {
                        // The view alone: the whole model, cut.
                        return tick.exec(Instruction::AddDrawingCrossSectionView {
                            drawing,
                            view,
                            orientation,
                        });
                    }
                }
                if let Some(sketch) = sketch {
                    return tick.exec(Instruction::AddDrawingSketchView {
                        drawing,
                        sketch,
                        orientation,
                    });
                }
                let bodies = if let Some(body) = body {
                    vec![body]
                } else if let Some(bodies) = bodies {
                    if bodies.is_empty() {
                        return Err(mlua::Error::external("`bodies` must not be empty"));
                    }
                    bodies
                } else {
                    let ci = component.expect("component set");
                    let state = tick.state();
                    let Some(ck) = state.doc.components.keys().nth(ci) else {
                        return Err(mlua::Error::external(format!("No component {ci}")));
                    };
                    let bodies: Vec<usize> = state
                        .component_body_indices(ck)
                        .into_iter()
                        .filter_map(|bk| state.doc.bodies.keys().position(|k| k == bk))
                        .collect();
                    if bodies.is_empty() {
                        return Err(mlua::Error::external(
                            "This component has no bodies to project",
                        ));
                    }
                    bodies
                };
                tick.exec(Instruction::AddDrawingView {
                    drawing,
                    bodies,
                    orientation,
                })?;
                // Bodies imported *from* a view are shown cut by it (#1689).
                if let Some(view) = cross_section {
                    let placed = tick
                        .state()
                        .doc
                        .drawings
                        .keys()
                        .nth(drawing)
                        .and_then(|k| tick.state().doc.drawings.get(k))
                        .map(|d| d.views.len().saturating_sub(1))
                        .unwrap_or(0);
                    tick.exec(Instruction::SetDrawingViewCrossSection {
                        drawing,
                        view: placed,
                        cross_section: Some(view),
                    })?;
                }
                Ok(Created(Vec::new()))
            }
        })?,
    )?;
    // Append bodies to an existing projection (#1191) — the scripted form of shift-click.
    api.set(
        "drawing_view_add",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(
                &opts,
                "drawing_view_add",
                &["drawing", "view", "body", "bodies", "component"],
            )?;
            let drawing: usize = opts.ordinal_req("drawing")?;
            let view: usize = opts.ordinal_req("view")?;
            let body: Option<usize> = opts.ordinal_opt("body")?;
            let bodies: Option<Vec<usize>> = opts.ordinal_list_opt("bodies")?;
            let component: Option<usize> = opts.ordinal_opt("component")?;
            let source_count = usize::from(body.is_some())
                + usize::from(bodies.is_some())
                + usize::from(component.is_some());
            if source_count != 1 {
                return Err(mlua::Error::external(
                    "drawing_view_add requires exactly one of `body`, `bodies`, or `component`",
                ));
            }
            unsafe {
                let bodies = if let Some(body) = body {
                    vec![body]
                } else if let Some(bodies) = bodies {
                    if bodies.is_empty() {
                        return Err(mlua::Error::external("`bodies` must not be empty"));
                    }
                    bodies
                } else {
                    let ci = component.expect("component set");
                    let state = tick.state();
                    let Some(ck) = state.doc.components.keys().nth(ci) else {
                        return Err(mlua::Error::external(format!("No component {ci}")));
                    };
                    let bodies: Vec<usize> = state
                        .component_body_indices(ck)
                        .into_iter()
                        .filter_map(|bk| state.doc.bodies.keys().position(|k| k == bk))
                        .collect();
                    if bodies.is_empty() {
                        return Err(mlua::Error::external(
                            "This component has no bodies to project",
                        ));
                    }
                    bodies
                };
                tick.exec(Instruction::AddBodiesToDrawingView {
                    drawing,
                    view,
                    bodies,
                })
            }
        })?,
    )?;

    // Set a drawing's page size and margin in millimetres (#406) — the scripted page-settings
    // editor. Omitted keys keep the drawing's current value, so partial updates work.
    api.set(
        "drawing_page",
        lua.create_function(|lua, opts: Table| {
            let tick = lua.app_data_ref::<ScriptTickData>().unwrap();
            check_keys(&opts, "drawing_page", &["drawing", "width", "height", "margin"])?;
            let drawing: usize = opts.ordinal_req("drawing")?;
            let doc = unsafe { &tick.state().doc };
            let page = Instruction::SetDrawingPage {
                drawing,
                width_mm: length_mm_opt(lua, doc, &opts, "drawing_page", "width")?,
                height_mm: length_mm_opt(lua, doc, &opts, "drawing_page", "height")?,
                margin_mm: length_mm_opt(lua, doc, &opts, "drawing_page", "margin")?,
            };
            unsafe { tick.exec(page) }
        })?,
    )?;

