    /// #33: `bearcad.ui.shading(...)` drives the HUD shading-mode popup's underlying state.
    #[test]
    fn lua_shading_sets_camera_shading_mode() {
        let state = run_lua(r#"bearcad.ui.shading("wireframe")"#);
        assert_eq!(state.cam.shading_mode(), ShadingMode::Wireframe);
    }

    #[test]
    fn lua_shading_accepts_all_mode_names() {
        for (name, expected) in [
            ("wireframe", ShadingMode::Wireframe),
            ("transparent", ShadingMode::TransparentSolid),
            ("solid", ShadingMode::Solid),
            ("solid_wireframe", ShadingMode::SolidWireframe),
            ("realistic", ShadingMode::Realistic),
            ("loose_pencil", ShadingMode::LoosePencil),
            ("dark_pencil", ShadingMode::DarkPencil),
            // The dark-mode pencil answers to what a hand would call it, too (#1844).
            ("chalk", ShadingMode::DarkPencil),
            ("color_pencil", ShadingMode::ColorPencil),
            ("watercolor", ShadingMode::Watercolor),
        ] {
            let state = run_lua(&format!(r#"bearcad.ui.shading("{name}")"#));
            assert_eq!(state.cam.shading_mode(), expected, "shading({name})");
        }
    }

    /// #1805: a script can read the view settings back, not just set them — the pencil view
    /// went in with no way for a test to assert it had taken.
    #[test]
    fn lua_camera_reports_shading_and_ground() {
        let state = run_lua(
            r#"
            bearcad.ui.shading("loose_pencil")
            bearcad.ui.ground("off")
            local c = bearcad.ui.camera{}
            assert(c.shading == "loose_pencil", "shading, got " .. tostring(c.shading))
            assert(c.ground == "off", "ground, got " .. tostring(c.ground))
            bearcad.ui.shading("solid")
            assert(bearcad.ui.camera{}.shading == "solid", "reads the change back")
        "#,
        );
        assert_eq!(state.cam.shading_mode(), ShadingMode::Solid);
    }

    #[test]
    fn lua_shading_rejects_unknown_mode() {
        let mut runner = ScriptRunner::from_lua_source(r#"bearcad.ui.shading("nonsense")"#)
            .unwrap();
        runner.verbose = false;
        let mut state = AppState::default();
        let mut synthetic = SyntheticInput::default();
        let ctx = egui::Context::default();
        let vp = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(960.0, 560.0));
        while !runner.done {
            runner.tick(&mut state, &mut synthetic, Some(vp), &ctx);
        }
        assert!(runner.error.is_some(), "unknown shading mode should error");
    }

    /// #1771: `camera{}` read every view setting back but only *wrote* the pose — a
    /// `projection`/`shading`/`ground` key was silently dropped, so a script that asked for an
    /// orthographic camera quietly kept running perspective.
    #[test]
    fn lua_camera_sets_the_view_settings_it_reports() {
        let state = run_lua(
            r#"
            bearcad.ui.camera{ projection = "orthographic" }
            local c = bearcad.ui.camera{}
            assert(c.projection == "orthographic", "projection, got " .. tostring(c.projection))
            -- and alongside the pose, in one call
            bearcad.ui.camera{ distance = 250, projection = "perspective",
                               shading = "loose_pencil", ground = "off" }
            c = bearcad.ui.camera{}
            assert(c.projection == "perspective", "projection, got " .. tostring(c.projection))
            assert(c.distance == 250, "distance, got " .. tostring(c.distance))
            assert(c.shading == "loose_pencil", "shading, got " .. tostring(c.shading))
            assert(c.ground == "off", "ground, got " .. tostring(c.ground))
            "#,
        );
        assert_eq!(state.cam.projection_mode(), ProjectionMode::Natural);
        assert_eq!(state.cam.shading_mode(), ShadingMode::LoosePencil);
        assert_eq!(state.cam.distance, 250.0);
    }

    /// #1771: and a key `camera{}` does not understand is an error, not a silent no-op —
    /// a misspelled setting used to leave the script running against the wrong view.
