    /// Tab script API queues workspace ops on the runner (App applies them each frame).
    #[test]
    fn lua_tab_ops_queue_on_runner() {
        let mut runner = ScriptRunner::from_lua_source(
            r#"
            bearcad.ui.new_tab()
            bearcad.ui.new_tab{ same = true }
            bearcad.ui.tab(0)
            bearcad.ui.close_tab(1)
            bearcad.ui.reorder_tab(0, 1)
            bearcad.ui.detach_tab()
            assert(bearcad.ui.tab_count() == 1)
            local tabs = bearcad.ui.tabs()
            assert(#tabs == 1)
            assert(tabs[1].title == "Untitled")
            "#,
        )
        .unwrap();
        runner.verbose = false;
        let mut state = AppState::default();
        let mut synthetic = SyntheticInput::default();
        let ctx = egui::Context::default();
        let vp = egui::Rect::from_min_size(egui::pos2(0.0, 40.0), egui::vec2(960.0, 560.0));
        while !runner.done {
            runner.tick(&mut state, &mut synthetic, Some(vp), &ctx);
        }
        assert!(runner.error.is_none(), "script error: {:?}", runner.error);
        use crate::script::TabOp;
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::NewBlank)),
            "new_tab should queue NewBlank: {:?}",
            runner.pending_tab_ops
        );
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::NewSameDocument)),
            "same-document new_tab should queue: {:?}",
            runner.pending_tab_ops
        );
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::Select { index: 0 })),
            "tab(0) should queue Select: {:?}",
            runner.pending_tab_ops
        );
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::Close { index: Some(1) })),
            "close_tab(1) should queue: {:?}",
            runner.pending_tab_ops
        );
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::Reorder { from: 0, to: 1 })),
            "reorder_tab should queue: {:?}",
            runner.pending_tab_ops
        );
        assert!(
            runner
                .pending_tab_ops
                .iter()
                .any(|op| matches!(op, TabOp::Detach { index: None })),
            "detach_tab should queue: {:?}",
            runner.pending_tab_ops
        );
    }

    /// #1326: `bearcad.ui.os_open` rides the same pending-open queue as a Finder
    /// double-click, so the drain path is scriptable.
    #[test]
    fn lua_os_open_opens_via_the_finder_queue() {
        let path = std::env::temp_dir().join(format!(
            "bearcad_os_open_{}.bearcad",
            std::process::id()
        ));
        let path_s = path.to_string_lossy().replace('\\', "\\\\");
        let state = run_lua(&format!(
            r#"
            bearcad.new()
            bearcad.rect{{ width = 10, height = 10 }}
            bearcad.save("{path_s}")
            bearcad.new()
            assert(bearcad.count("line") == 0)
            bearcad.ui.os_open("{path_s}")
            bearcad.ui.wait(2)
            assert(bearcad.count("line") == 4, "os_open should load the saved document")
        "#
        ));
        let _ = std::fs::remove_file(&path);
        assert_eq!(state.doc.lines.len(), 4);
    }

    /// #1341: adding a body after save writes one body row; a second connection
    /// still sees the last commit until Save; existing lines are not rewritten.
    #[test]
    fn lua_incremental_body_write() {
        let path = std::env::temp_dir().join(format!(
            "bearcad_lua_incr_{}.bearcad",
            std::process::id()
        ));
        let path_s = path.to_string_lossy().replace('\\', "\\\\");
        let _ = std::fs::remove_file(&path);
        let state = run_lua(&format!(
            r#"
            bearcad.new()
            bearcad.rect{{ width = 20, height = 10 }}
            bearcad.cuboid{{ width = 8, depth = 8, height = 8 }}
            bearcad.save("{path_s}")
            local bodies0 = bearcad.count_saved("body")
            local lines0 = bearcad.count_saved("line")
            assert(bodies0 == 1, "one body after first save")
            bearcad.cuboid{{ width = 4, depth = 4, height = 4, at = {{20, 0, 0}} }}
            local w = bearcad.debug.session_writes()
            assert(w.bodies and w.bodies.inserts == 1, "bodies table grew by one insert")
            assert(not w.lines, "existing lines were not deleted/reinserted")
            assert(
                bearcad.count_saved("body") == bodies0,
                "another connection still sees the last save"
            )
            bearcad.save()
            assert(bearcad.count_saved("body") == bodies0 + 1)
            assert(bearcad.count_saved("line") == lines0)
        "#
        ));
        let _ = std::fs::remove_file(&path);
        assert_eq!(state.doc.bodies.len(), 2);
    }

    /// #1343: open a boolean-heavy file; first-frame meshes come from geometry_cache.
    #[test]
    fn lua_open_boolean_meshes_come_from_cache() {
        let path = std::env::temp_dir().join(format!(
            "bearcad_lua_geom_cache_{}.bearcad",
            std::process::id()
        ));
        let path_s = path.to_string_lossy().replace('\\', "\\\\");
        let _ = std::fs::remove_file(&path);
        let state = run_lua(&format!(
            r#"
            bearcad.new()
            bearcad.cuboid{{ width = 20, depth = 20, height = 20 }}
            bearcad.cuboid{{ width = 8, depth = 8, height = 30, at = {{0, 0, 5}} }}
            bearcad.combine{{ op = "cut", a = {{0}}, b = {{1}} }}
            -- Force a committed mesh so Save writes geometry_cache.
            assert(bearcad.body_stats(2).triangles > 0, "boolean result must mesh")
            bearcad.save("{path_s}")
            assert(bearcad.debug.sqlite_scalar("SELECT COUNT(*) FROM geometry_cache") >= 1,
                "saved file must hold a cache row")
            bearcad.new()
            bearcad.open("{path_s}")
            local s = bearcad.debug.mesh_cache()
            assert(s.warmed >= 1, "open must warm meshes from geometry_cache")
            local misses = s.misses
            assert(bearcad.body_stats(2).triangles > 0)
            local s2 = bearcad.debug.mesh_cache()
            assert(s2.misses == misses, "first-frame boolean mesh must come from cache")
            bearcad.rebuild_geometry()
            -- discard is in the open txn; another connection still sees the last save
            assert(bearcad.debug.sqlite_scalar("SELECT COUNT(*) FROM geometry_cache") >= 1)
            bearcad.save()
            assert(bearcad.debug.sqlite_scalar("SELECT COUNT(*) FROM geometry_cache") == 0,
                "Save after rebuild publishes the discarded table")
        "#
        ));
        let _ = std::fs::remove_file(&path);
        assert!(
            state.doc.bodies.len() >= 1,
            "boolean file should still have bodies"
        );
    }

    /// #1342: importing a unit persists `units.document` as a nested `.bearcad` blob.
    /// Syncing the source replaces that one blob; a second connection still sees the
    /// last save until ⌘S.
    #[test]
    fn lua_unit_document_is_a_nested_blob() {
        let pid = std::process::id();
        let source = std::env::temp_dir().join(format!("bearcad_lua_unit_src_{pid}.bearcad"));
        let host = std::env::temp_dir().join(format!("bearcad_lua_unit_host_{pid}.bearcad"));
        let source_s = source.to_string_lossy().replace('\\', "\\\\");
        let host_s = host.to_string_lossy().replace('\\', "\\\\");
        let _ = std::fs::remove_file(&source);
        let _ = std::fs::remove_file(&host);
        let state = run_lua(&format!(
            r#"
            bearcad.new()
            bearcad.add_parameter("width", "10")
            bearcad.save("{source_s}")
            bearcad.new()
            bearcad.save("{host_s}")
            bearcad.import_unit{{ path = "{source_s}", link = "static", name = "part" }}
            bearcad.save()
            assert(bearcad.debug.sqlite_scalar("SELECT typeof(document) FROM units") == "blob",
                "units.document must be a blob")
            assert(bearcad.debug.sqlite_scalar("SELECT CAST(substr(document, 1, 15) AS TEXT) FROM units")
                == "SQLite format 3", "nested blob must be a .bearcad")
            bearcad.open("{source_s}")
            bearcad.set_parameter("width", "99")
            bearcad.save()
            bearcad.open("{host_s}")
            bearcad.sync_unit(0)
            local w = bearcad.debug.session_writes()
            assert(w.units and w.units.updates == 1, "sync replaces the one unit blob")
            assert(not w.unit_instances, "instances stay rows of their own")
            assert(
                bearcad.debug.sqlite_scalar("SELECT CAST(substr(document, 1, 15) AS TEXT) FROM units")
                    == "SQLite format 3",
                "committed file still has the last save's blob"
            )
            bearcad.save()
            assert(bearcad.debug.sqlite_scalar("SELECT typeof(document) FROM units") == "blob")
        "#
        ));
        let _ = std::fs::remove_file(&source);
        let _ = std::fs::remove_file(&host);
        assert_eq!(state.doc.units.len(), 1);
    }

    /// #46: GUI/UI manipulation lives under `bearcad.ui.*`; modeling stays top-level.
    #[test]
    fn lua_ui_functions_live_under_ui_namespace() {
        run_lua_expect_ok(
            r#"
            assert(bearcad.ui ~= nil, "bearcad.ui table missing")
            for _, name in ipairs({ "move", "click", "tool", "view", "orbit", "pan",
                                    "key", "type", "pane", "pane_rect", "pane_scroll",
                                    "menu_items", "menu_item_rect",
                                    "add_geometric_constraint",
                                    "scroll_pane", "ai_sections", "ai_mcp", "menu_structure",
                                    "palette", "wait", "help",
                                    "toolbar_shortcuts", "toolbar_tools", "changelog",
                                    "mcmaster", "report_issue", "windows", "focused_window",
                                    "new_tab", "close_tab", "tab", "tabs", "tab_count",
                                    "window_count", "reorder_tab", "detach_tab" }) do
                assert(type(bearcad.ui[name]) == "function", "bearcad.ui." .. name .. " missing")
                assert(bearcad[name] == nil, "bearcad." .. name .. " should move to bearcad.ui")
            end
            -- #1633: the AI pane's two sections, in draw order.
            local sections = bearcad.ui.ai_pane_sections()
            assert(#sections == 2, "the AI pane has two sections, got " .. #sections)
            assert(sections[1] == "MCP Server")
            assert(sections[2] == "Agent Skill")
            -- drag_vertex/drag_line take sketch-local coordinates, so they live in the
            -- modeling namespace (#114) — one home, no ui alias (#1874).
            for _, name in ipairs({ "drag_vertex", "drag_line" }) do
                assert(type(bearcad[name]) == "function", "bearcad." .. name .. " missing")
                assert(bearcad.ui[name] == nil, "bearcad.ui." .. name .. " should not alias the modeling call")
            end
            -- #1873: live-tool arm/preview verbs sit under ui so agents don't confuse them
            -- with the committing modeling twins.
            for _, name in ipairs({ "begin_combine", "begin_move", "begin_joint",
                                    "begin_edit_section_plane", "begin_edit_shape" }) do
                assert(type(bearcad.ui[name]) == "function", "bearcad.ui." .. name .. " missing")
                assert(bearcad[name] == nil, "bearcad." .. name .. " should move to bearcad.ui")
            end
            -- #1874: verbs that need an armed tool, a widget, or viewport hover/fan.
            for _, name in ipairs({ "set_dim", "edit_dim", "commit_dim", "set_dim_label_offset",
                                    "commit_plane", "edit_plane",
                                    "gizmos", "gizmo", "set_gizmo", "drag_gizmo",
                                    "constraint_shortcut",
                                    "pickers", "picker", "hovered", "exploder",
                                    "move_preview" }) do
                assert(type(bearcad.ui[name]) == "function", "bearcad.ui." .. name .. " missing")
                assert(bearcad[name] == nil, "bearcad." .. name .. " should move to bearcad.ui")
            end
            -- declarative modeling stays at the top level
            for _, name in ipairs({ "rect", "line", "circle", "extrude", "new", "select",
                                    "constrain", "dimension", "add_parameter", "export_stl", "export_3mf",
                                    "export_step", "export_preview",
                                    "import_stl", "import_step", "import_lua", "chamfer_vertex",
                                    "fillet_vertex", "chamfer", "chamfer_edge", "fillet",
                                    "fillet_edge", "project",
                                    "sketch_faces",
                                    "combine", "move_bodies", "joint", "begin_sketch",
                                    "edit_section_plane",
                                    "globals", "count_saved", "version" }) do
                assert(type(bearcad[name]) == "function", "bearcad." .. name .. " should stay top-level")
            end
            assert(bearcad.debug ~= nil, "bearcad.debug table missing")
            for _, name in ipairs({ "sqlite_scalar", "session_writes", "mesh_cache",
                                    "tool_table", "tool_row", "widget_id_warnings" }) do
                assert(type(bearcad.debug[name]) == "function",
                  "bearcad.debug." .. name .. " missing")
                assert(bearcad[name] == nil, "bearcad." .. name .. " should move to bearcad.debug")
            end
            assert(bearcad.ui.widget_id_warnings == nil,
              "widget_id_warnings should not live under ui")
            for _, name in ipairs({ "first_person", "first_person_look", "first_person_move",
                                    "first_person_jump", "first_person_fly",
                                    "first_person_advance", "first_person_scale" }) do
                assert(type(bearcad.ui[name]) == "function", "bearcad.ui." .. name .. " missing")
                assert(bearcad[name] == nil, "bearcad." .. name .. " should move to bearcad.ui")
            end
            for _, name in ipairs({ "fps", "fps_look", "fps_move", "fps_jump", "fps_fly",
                                    "fps_advance", "fps_scale" }) do
                assert(bearcad.ui[name] == nil, "dropped fps name still present: " .. name)
            end
            -- #1616: there is no AI namespace at all, and no flat spelling of one.
            assert(bearcad.ai == nil, "bearcad.ai should not exist")
            for _, name in ipairs({ "ai_send", "ai_api", "ai_backends", "ai_mcp_start",
                                    "ai_install_skill", "ai_run_block" }) do
                assert(bearcad[name] == nil, "bearcad." .. name .. " should not exist")
            end
        "#,
        );
    }

    /// #1800: assorted scripting ergonomics — `ui.view("iso")`, `ui.wait()` with no
    /// argument, and `section_planes` taking a cross-section index or name.
    #[test]
    fn lua_ui_ergonomic_defaults() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            -- "iso" is a standard view (the Home corner), not an error.
            bearcad.ui.view("iso")
            -- wait() defaults to one frame.
            bearcad.ui.wait()
            -- section_planes takes an index or a name; a bogus name is refused loudly.
            assert(#bearcad.section_planes(0) == 0, "no cross-section yet")
            local ok, err = pcall(bearcad.section_planes, "top")
            assert(not ok, "an unknown cross-section name must be refused")
            assert(tostring(err):find("no cross%-section"), "unexpected error: " .. tostring(err))
        "#,
        );
        assert_eq!(state.doc.primitives.len(), 1);
    }

    /// #1800: the datum planes a document opens with are what reads as a "phantom" translucent
    /// square in a script's screenshots, and a script had no way to sweep them out of the
    /// picture or to check that it had. `set_visible{ kind = … }` with no index now hides
    /// every element of that kind, and `bearcad.visible` reads the flag back.
    #[test]
    fn lua_set_visible_by_kind_hides_every_element_of_that_kind() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            assert(bearcad.count("plane") == 3, "three datum planes")
            for i = 0, 2 do
                assert(bearcad.visible({ kind = "plane", index = i }), "plane " .. i .. " starts visible")
            end
            -- No index: every plane at once.
            bearcad.set_visible({ kind = "plane" }, false)
            for i = 0, 2 do
                assert(not bearcad.visible({ kind = "plane", index = i }), "plane " .. i .. " hidden")
            end
            -- The body is untouched by a plane-kind sweep.
            assert(bearcad.visible({ kind = "body", index = 0 }), "body still visible")
            -- And back again.
            bearcad.set_visible({ kind = "plane" }, true)
            for i = 0, 2 do
                assert(bearcad.visible({ kind = "plane", index = i }), "plane " .. i .. " shown again")
            end
            -- A kind with nothing in it is refused rather than silently doing nothing.
            local ok, err = pcall(bearcad.set_visible, { kind = "image" }, false)
            assert(not ok, "an empty kind must be refused")
            assert(tostring(err):find("no 'image'"), "unexpected error: " .. tostring(err))
            -- #1890: boolean only — not "hide"/"show"/"toggle".
            local hide_ok = pcall(bearcad.set_visible, { kind = "plane" }, "hide")
            assert(not hide_ok, "set_visible must refuse the old hide/show strings")
        "#,
        );
        assert_eq!(state.doc.construction_planes.len(), 3);
    }

    /// #1890: one `set_visible` / `set_construction` takes a handle, a list, or a kind;
    /// selection/live-tool forms live on `bearcad.ui`.
    #[test]
    fn lua_set_visible_and_set_construction_take_handle_list_or_kind() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local box = bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local p0 = bearcad.element("plane", 0)
            local p1 = bearcad.element("plane", 1)
            bearcad.set_visible({ p0, p1 }, false)
            assert(not bearcad.visible(p0) and not bearcad.visible(p1), "list hide")
            bearcad.set_visible(p0, true)
            assert(bearcad.visible(p0) and not bearcad.visible(p1), "handle show")

            bearcad.rect{ width = 10, height = 10 }
            bearcad.set_construction({ kind = "line" }, true)
            assert(bearcad.get{ kind = "line", index = 0 }.construction)
            assert(bearcad.get{ kind = "line", index = 3 }.construction)
            local sides = { bearcad.element("line", 0), bearcad.element("line", 1) }
            bearcad.set_construction(sides, false)
            assert(not bearcad.get{ kind = "line", index = 0 }.construction)
            assert(not bearcad.get{ kind = "line", index = 1 }.construction)
            assert(bearcad.get{ kind = "line", index = 2 }.construction)

            assert(type(bearcad.ui.toggle_visibility) == "function")
            assert(type(bearcad.ui.apply_visibility) == "function")
            assert(type(bearcad.ui.toggle_construction) == "function")
            assert(type(bearcad.ui.apply_construction) == "function")
            assert(bearcad.toggle_visibility == nil)
            assert(bearcad.apply_visibility == nil)
            assert(bearcad.toggle_construction == nil)
            assert(bearcad.apply_construction == nil)

            bearcad.select(box)
            bearcad.ui.apply_visibility(false)
            assert(not bearcad.visible(box))
            bearcad.ui.toggle_visibility()
            assert(bearcad.visible(box))

            bearcad.select({ kind = "line", index = 2 })
            bearcad.ui.apply_construction(false)
            assert(not bearcad.get{ kind = "line", index = 2 }.construction)
            bearcad.ui.toggle_construction()
            assert(bearcad.get{ kind = "line", index = 2 }.construction)
        "#,
        );
    }

    /// #1801: a creation call hands back a stable handle for what it made, and every operand
    /// that takes an ordinal takes a handle too. Ordinals shift when elements are deleted or
    /// consumed; a handle names the same element for as long as that element exists.
    #[test]
    fn lua_creation_calls_return_stable_handles() {
        let state = run_lua(
            r#"
            -- A rect is four lines: the call hands back all four.
            local sides = bearcad.rect{ x = 0, y = 0, width = 20, height = 10 }
            assert(#sides == 4, "rect returns its four lines, got " .. tostring(#sides))
            assert(sides[1]:kind() == "line", "a side is a line")
            -- An extrude hands back the body it made, not the extrusion.
            local box = bearcad.extrude{ polygon = sides, distance = 5 }
            assert(box:kind() == "body", "extrude returns the body, got " .. box:kind())
            assert(box:index() == 0, "the only body is ordinal 0")

            -- Face specs take the same line handles (not {0,1,2,3}).
            bearcad.begin_sketch{
              kind = "extrude_cap", extrusion = 0,
              profile = "polygon", profile_lines = sides, top = true,
            }
            bearcad.exit_sketch()

            -- Ordinals shift under your feet; the handle does not.
            local plate = bearcad.cuboid{ width = 4, depth = 4, height = 4 }
            assert(plate:index() == 1, "second body")
            bearcad.select({ kind = "body", index = 0 })
            bearcad.delete_selection()
            assert(plate:index() == 0, "the handle followed its body to ordinal 0")
            assert(not box:exists(), "the deleted body's handle is dead")

            -- The ID is a string, unique in the document, and survives a round trip.
            local id = plate:id()
            assert(type(id) == "string", "an id is a string")
            assert(bearcad.element(id):id() == id, "id round-trips through bearcad.element")
            assert(bearcad.id(plate) == id, "bearcad.id agrees with the method")

            -- An id is never handed out twice: delete and rebuild, and the old one is gone.
            bearcad.select(plate)
            bearcad.delete_selection()
            local again = bearcad.cuboid{ width = 4, depth = 4, height = 4 }
            assert(again:id() ~= id, "a fresh body never reuses a retired id")
            local ok = pcall(bearcad.element, id)
            assert(not ok, "a retired id resolves to nothing")

            -- Names still resolve, alongside handles and ids — including a body's (#1806).
            local edge = bearcad.element("line", 0)
            bearcad.set_name(edge, "Front")
            assert(bearcad.find("Front"):id() == edge:id(), "find still works")
            assert(bearcad.id("Front") == edge:id(), "a name resolves to the same id")
            bearcad.set_name(again, "Plate")
            assert(bearcad.find("Plate"):id() == again:id(), "a named body is findable")
        "#,
        );
        assert_eq!(state.doc.bodies.len(), 1);
    }

    /// #1864: drawing, component, and cross_section hand back a handle (not a shifting
    /// ordinal), so `d:kind()` works and the same handle still names the element after
    /// another of that kind is inserted.
    #[test]
    fn lua_drawing_component_and_cross_section_return_handles() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local d = bearcad.drawing{ name = "Plan" }
            assert(d:kind() == "drawing", "drawing returns a handle, got " .. tostring(d))
            assert(d:index() == 0)
            assert(d:name() == "Plan")
            local d2 = bearcad.drawing{}
            assert(d:index() == 0 and d2:index() == 1, "handles keep their drawings")

            local c = bearcad.component{ name = "Frame" }
            assert(c:kind() == "component", "component returns a handle, got " .. tostring(c))
            assert(c:name() == "Frame")
            bearcad.move_to_component{ kind = "drawing", index = d, component = c }

            local v = bearcad.cross_section{ name = "Front half" }
            assert(v:kind() == "cross_section", "cross_section returns a handle, got " .. tostring(v))
            assert(v:name() == "Front half")
            "#,
        );
    }

    /// #1864: fillet/chamfer, geometric constraints, and `add_parameter` hand back
    /// what they made, so the new op can be named and selected without hunting `count-1`.
    #[test]
    fn lua_fillet_constraint_and_parameter_return_handles() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local p = bearcad.add_parameter("w", "24")
            assert(p:kind() == "parameter", "add_parameter returns a handle, got " .. tostring(p))
            assert(p:name() == "w")
            assert(p:index() == 0)
            bearcad.set_parameter(p, "30")
            assert(bearcad.parameter_value("w") == 30)

            bearcad.rect{ width = 20, height = 10 }
            local par = bearcad.constrain("parallel",
                { kind = "line", index = 0 }, { kind = "line", index = 2 })
            assert(par:kind() == "constraint", "constrain returns a handle")

            local box = bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 8 }
            local fillet = bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                radius = 1,
            }
            assert(fillet ~= nil, "fillet_edge returns what it made")
            assert(fillet:exists(), "fillet_edge handle is live")
            local chamfer = bearcad.chamfer_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 1 },
                distance = 1,
            }
            assert(chamfer ~= nil and chamfer:exists(), "chamfer_edge returns what it made")
            "#,
        );

        let state = run_lua_against_a_right_angle_corner(
            r#"
            local f = bearcad.fillet_vertex{
                point = { kind = "line", index = 0, endpoint = "end" },
                radius = 3,
            }
            assert(f ~= nil, "fillet_vertex returns what it made")
            if type(f) == "table" then
                assert(f[1]:exists(), "fillet_vertex list entries are handles")
            else
                assert(f:exists(), "fillet_vertex handle is live")
            end
            "#,
        );
        assert_eq!(state.doc.sketch_vertex_treatment_ops.len(), 1);

        let state = run_lua_against_a_right_angle_corner(
            r#"
            local c = bearcad.chamfer_vertex{
                point = { kind = "line", index = 0, endpoint = "end" },
                distance = 3,
            }
            assert(c ~= nil, "chamfer_vertex returns what it made")
            if type(c) == "table" then
                assert(c[1]:exists(), "chamfer_vertex list entries are handles")
            else
                assert(c:exists(), "chamfer_vertex handle is live")
            end
            "#,
        );
        assert_eq!(state.doc.sketch_vertex_treatment_ops.len(), 1);
    }

    /// #1801: an operand that names an element by ordinal takes a handle or an id instead —
    /// so a script can chain operations without tracking which ordinal moved where.
    #[test]
    fn lua_operands_accept_handles_and_ids() {
        let state = run_lua(
            r#"
            local a = bearcad.cuboid{ width = 10, depth = 10, height = 10, at = { 0, 0, 0 } }
            local b = bearcad.cuboid{ width = 6, depth = 6, height = 20, at = { 0, 0, 0 } }
            -- `a`/`b` take handles; a difference that leaves an offcut hands back both bodies.
            local cut = bearcad.combine{ a = { a }, b = { b }, op = "xor" }
            assert(#cut == 2, "xor makes the result and its offcut, got " .. tostring(#cut))
            -- `bodies` takes an id string just as happily.
            local moved = bearcad.move_bodies{ bodies = { cut[1]:id() }, z = 5 }
            assert(moved:kind() == "body", "move_bodies returns the moved body")
            -- `get` takes one too.
            assert(bearcad.get{ kind = "body", index = moved } ~= nil, "get by handle")
            -- The positional read-backs take one too.
            assert(bearcad.body_stats(moved).volume > 0, "body_stats by handle")
            assert(#bearcad.body_faces(moved) > 0, "body_faces by handle")
            -- A handle whose element is gone says so rather than naming its replacement.
            bearcad.select(moved)
            bearcad.delete_selection()
            local ok, err = pcall(bearcad.body_stats, moved)
            assert(not ok, "a dead handle is refused")
            assert(tostring(err):find("no longer exists"), "unexpected error: " .. tostring(err))
        "#,
        );
        // Two cuboids, the difference and its offcut; the moved copy was deleted again.
        assert_eq!(state.doc.bodies.len(), 4);
    }

    /// #189: selecting a point and a sketch origin axis, then applying Coincident, pins the
    /// point onto that axis — the full select→constrain flow, no mouse simulation.
    #[test]
    fn lua_constrain_point_to_origin_axis() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 5, y = 5, x1 = 12, y1 = 8 }
            bearcad.constrain("coincident",
                { kind = "line", index = 0, endpoint = "start" },
                { kind = "axis", axis = "x" })
        "#,
        );
        assert!(
            state.doc.lines[lkey(0)].y0.abs() < 1e-3,
            "the start point should be pinned to the X axis (v = 0), got y0={}",
            state.doc.lines[lkey(0)].y0
        );
    }

    /// #839: `around = true` turns the copies about the axis; the copies land on the circle.
    #[test]
    fn lua_repeat_around_the_axis_turns_the_copies() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ x = 20, y = -3, width = 8, height = 6 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 4 }
            bearcad.exit_sketch()
            bearcad.repeat_bodies{ bodies = {0}, axis = "z", around = true,
                                   mode = "count_gap", count = 4, spacing = "90deg" }
        "#,
        );
        let op = &state.doc.repeat_ops.values().nth(0).unwrap();
        assert!(op.around_axis);
        assert_eq!(op.outputs.len(), 3, "4 instances = the original plus 3 copies");
        // The first copy is a quarter turn round: its bounds swap x for y.
        let source = crate::extrude::body_solid_mesh(&state.doc, bkey(0)).expect("source mesh");
        let copy = crate::extrude::body_solid_mesh(&state.doc, op.outputs[0]).expect("copy mesh");
        let (smin, smax) = source.bounds().unwrap();
        let (cmin, cmax) = copy.bounds().unwrap();
        assert!(smin.x > 0.0 && smax.x > 0.0, "the source sits out along +X");
        assert!(cmin.y > 0.0 && cmax.y > 0.0, "the quarter-turn copy sits out along +Y");
        assert!(cmax.x.abs() < 4.0, "and no longer along X, got {}", cmax.x);
    }

    /// #1473: `count_fit_ends` on a full-turn rotational repeat spaces n distinct items
    /// (last short of 360°); `count_fit_centers` puts the last copy on top of the first.
    #[test]
    fn lua_rotational_angle_toggle_spaces_distinct_items_or_stacks_the_last() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ x = 20, y = -3, width = 8, height = 6 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 4 }
            bearcad.exit_sketch()
            bearcad.repeat_bodies{ bodies = {0}, axis = "z", around = true,
                                   mode = "count_fit_ends", count = 5, length = 360 }
            local src = bearcad.body_stats(0).bbox
            local last = bearcad.body_stats(4).bbox
            local function cx(b) return (b.min.x + b.max.x) / 2 end
            local function cy(b) return (b.min.y + b.max.y) / 2 end
            assert(math.abs(cx(src) - cx(last)) > 8,
                "end-mode last copy must not sit on the first, src x=" .. cx(src) .. " last x=" .. cx(last))
            assert(cy(last) < -10,
                "end-mode last copy is at 288°, south of the origin, y=" .. cy(last))

            bearcad.edit_repeat{ index = 0, bodies = {0}, axis = "z", around = true,
                                 mode = "count_fit_centers", count = 5, length = 360 }
            last = bearcad.body_stats(4).bbox
            assert(math.abs(cx(src) - cx(last)) < 1,
                "start-mode last copy sits on the first, src x=" .. cx(src) .. " last x=" .. cx(last))
            assert(math.abs(cy(src) - cy(last)) < 1,
                "start-mode last copy sits on the first, src y=" .. cy(src) .. " last y=" .. cy(last))
        "#,
        );
    }

    /// #834: materials from scripts — created with a color, handed to bodies, reassigned.
    #[test]
    fn lua_materials_are_scriptable() {
        let state = run_lua(
            r##"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.material{ name = "Brass", color = "#c88a4a", bodies = {0} }
            bearcad.material{ name = "Steel" }
        "##,
        );
        // The document starts with the default palette (#928), so the scripted pair lands
        // after it.
        let seeded = crate::model::Material::DEFAULTS.len();
        assert_eq!(state.doc.materials.len(), seeded + 2);
        let brass = state.doc.materials.keys().nth(seeded).expect("Brass");
        assert_eq!(state.doc.materials[brass].name, "Brass");
        assert_eq!(state.doc.materials[brass].color, [0xc8, 0x8a, 0x4a]);
        assert_eq!(state.doc.bodies[bkey(0)].material, Some(brass), "Brass was handed to it");

        let state = run_lua(&format!(
            r##"
            bearcad.new()
            bearcad.rect{{ x = 0, y = 0, width = 10, height = 10 }}
            bearcad.extrude{{ polygon = {{0, 1, 2, 3}}, distance = 5 }}
            bearcad.material{{ name = "Brass", color = "#c88a4a", bodies = {{0}} }}
            bearcad.material{{ name = "Steel" }}
            bearcad.set_material{{ body = 0, material = {} }}
        "##,
            seeded + 1
        ));
        // A script names a material by its ordinal among the live ones; the boundary
        // resolves that to the key the body actually holds (#1055).
        let steel = state.doc.materials.keys().nth(seeded + 1).expect("Steel");
        assert_eq!(state.doc.bodies[bkey(0)].material, Some(steel), "reassigned to Steel");
    }

    /// #1475/#1474: repeating a standalone add extrusion of disjoint cylinders makes one
    /// body per instance, and each instance can take its own material.
    #[test]
    fn lua_repeat_add_extrusion_makes_separate_bodies_with_materials() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.circle{ x = 20, y = 0, r = 2 }
            bearcad.extrude{ circle = 0, distance = 10 }
            bearcad.repeat_cut{ cuts = {0}, axis = "z", around = true,
                                mode = "count_fit_ends", count = 6, length = 360 }
            bearcad.set_material{ body = 2, material = 1 }
            assert(bearcad.count("body") == 6, "expected 6 bodies, got " .. bearcad.count("body"))
            local v0 = bearcad.body_stats(0).volume
            for i = 1, 5 do
                local v = bearcad.body_stats(i).volume
                assert(math.abs(v - v0) < v0 * 0.15,
                    "instance " .. i .. " volume " .. v .. " vs source " .. v0)
            end
            assert(bearcad.get{ kind = "body", index = 2 }.material == 1)
            assert(bearcad.get{ kind = "body", index = 0 }.material == nil
                or bearcad.get{ kind = "body", index = 0 }.material == 0)
        "#,
        );
        let live: Vec<_> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .collect();
        assert_eq!(live.len(), 6, "disjoint repeated extrudes are separate bodies");
        let blue = state.doc.materials.keys().nth(1).expect("Blue");
        let painted = live
            .iter()
            .filter(|(_, b)| b.material == Some(blue))
            .count();
        assert_eq!(painted, 1, "only the assigned instance is Blue");
    }

    /// #1862: `repeat_cut` takes `cuts` (handles or ordinals), not `bodies`, and fails
    /// when that list is empty.
    #[test]
    fn lua_repeat_cut_requires_cuts_and_rejects_bodies() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.circle{ x = 20, y = 0, r = 2 }
            bearcad.extrude{ circle = 0, distance = 10 }
            local cut = bearcad.element("extrusion", 0)
            bearcad.repeat_cut{ cuts = {cut}, axis = "z", around = true,
                                mode = "count_fit_ends", count = 4, length = 360 }
            assert(bearcad.count("body") == 4, "handle list must punch copies")

            local ok, err = pcall(function()
                bearcad.repeat_cut{ bodies = {0}, axis = "z", around = true,
                                    mode = "count_fit_ends", count = 4, length = 360 }
            end)
            assert(not ok, "bodies must fail as an unknown key")
            assert(tostring(err):find("unknown key `bodies`"), tostring(err))
            assert(tostring(err):find("cuts"), tostring(err))

            ok, err = pcall(function()
                bearcad.repeat_cut{ cuts = {}, axis = "z", around = true,
                                    mode = "count_fit_ends", count = 4, length = 360 }
            end)
            assert(not ok, "empty cuts must fail")
            assert(tostring(err):find("cuts"), tostring(err))

            ok, err = pcall(function()
                bearcad.repeat_cut{ axis = "z", around = true,
                                    mode = "count_fit_ends", count = 4, length = 360 }
            end)
            assert(not ok, "missing cuts must fail")
            "#,
        );
    }

    /// #1475: the reported polar-repeat-of-an-extrude document has one body per
    /// cylinder, not one compound of all six.
    #[test]
    fn lua_issue_1475_repeated_cylinders_are_separate_bodies() {
        let path = format!(
            "{}/tests/fixtures/issue_1475.json",
            env!("CARGO_MANIFEST_DIR")
        );
        let path = path.replace('\\', "\\\\");
        let state = run_lua(&format!(r#"bearcad.open("{path}")"#));
        let live: Vec<_> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .collect();
        assert_eq!(
            live.len(),
            7,
            "disk + 6 cylinders; got {} live bodies",
            live.len()
        );
        let op = state.doc.repeat_ops.values().next().expect("repeat");
        assert_eq!(op.outputs.len(), 5, "6 instances = original + 5 copies");
        assert_eq!(op.targets.len(), 1);
    }

    /// #1492: "Up to" the bottom face of the reported body — a **moved** body, whose
    /// surfaces have no analytic identity, so its faces are `BodyMeshFace`s. Every target
    /// that was not an extrusion cap or side wall used to be refused outright ("body face
    /// must be an extrusion cap or side wall"), which is why the cut could not be aimed at
    /// the face right under it.
    #[test]
    fn lua_issue_1492_cut_up_to_a_moved_bodys_bottom_face() {
        let path = format!(
            "{}/tests/fixtures/issue_1491.json",
            env!("CARGO_MANIFEST_DIR")
        );
        let path = path.replace('\\', "\\\\");
        let state = run_lua(&format!(
            r#"
            bearcad.open("{path}")
            local function q(v)
              return {{ math.floor(v[1]*100+0.5), math.floor(v[2]*100+0.5), math.floor(v[3]*100+0.5) }}
            end
            -- The sketched circle sits on body 4's top face; aim the cut at its bottom.
            local bottom
            for _, f in ipairs(bearcad.body_faces(4)) do
              if f.normal[3] < -0.9 and (bottom == nil or f.face[3] < bottom.face[3]) then
                bottom = f
              end
            end
            assert(bottom, "the moved body has a downward-facing bottom")
            local before = bearcad.body_stats(4).volume
            bearcad.extrude{{ circle = 0, body = "cut", to = {{ face = {{
              kind = "body_mesh_face", body = 4,
              centroid = q(bottom.face), normal = q(bottom.normal) }} }} }}
            local after = bearcad.body_stats(bearcad.count("body") - 1).volume
            assert(after < before - 1000,
              "the bore should run to the bottom face: " .. after .. " vs " .. before)
            assert(after > before * 0.5,
              "and the body must survive it: " .. after .. " vs " .. before)
            "#
        ));
        let ext = state.doc.extrusions.values().last().expect("the cut extrusion");
        assert!(
            matches!(
                ext.target,
                Some(crate::model::ExtrudeTarget::BodyFace(
                    crate::model::FaceId::BodyMeshFace { .. }
                ))
            ),
            "the cut is target-driven by the mesh face, got {:?}",
            ext.target
        );
    }

    /// #1492: a Shape-tool cuboid's own faces are valid "Up to" planes, not just
    /// extrusion caps/side walls.
    #[test]
    fn lua_issue_1492_cut_up_to_a_primitive_bottom_face() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 40, depth = 30, height = 20 }
            bearcad.begin_sketch{ kind = "primitive_face", primitive = 0, face = "top" }
            bearcad.circle{ x = 20, y = 15, r = 6 }
            local before = bearcad.body_stats(0).volume
            bearcad.extrude{ circle = 0, body = "cut", to = { face = {
              kind = "primitive_face", primitive = 0, face = "bottom" } } }
            local after = bearcad.body_stats(bearcad.count("body") - 1).volume
            assert(after < before - 100,
              "the bore should remove material: " .. after .. " vs " .. before)
            assert(after > before * 0.5,
              "the cuboid must survive the cut: " .. after .. " vs " .. before)
            "#,
        );
        let ext = state.doc.extrusions.values().next().expect("the cut");
        assert!(
            matches!(
                ext.target,
                Some(crate::model::ExtrudeTarget::BodyFace(
                    crate::model::FaceId::PrimitiveFace {
                        face: crate::model::PrimitiveFace::CuboidBottom,
                        ..
                    }
                ))
            ),
            "the cut is target-driven by the cuboid bottom, got {:?}",
            ext.target
        );
        let depth = crate::extrude::effective_distance(&state.doc, ext);
        assert!(
            (depth.abs() - 20.0).abs() < 0.05,
            "up to the bottom should be 20 mm, got {depth}"
        );
    }

    /// #1218: scripts can turn any body into a shadow body (and back).
    #[test]
    fn lua_set_body_shadow_is_scriptable() {
        let state = run_lua(
            r##"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.set_body_shadow{ body = 0, shadow = true }
        "##,
        );
        assert!(
            state.doc.bodies[bkey(0)].shadow,
            "set_body_shadow marks the body as a shadow"
        );

        let state = run_lua(
            r##"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.set_body_shadow{ body = 0, shadow = true }
            bearcad.set_body_shadow{ body = 0, shadow = false }
        "##,
        );
        assert!(
            !state.doc.bodies[bkey(0)].shadow,
            "set_body_shadow restores a live body"
        );
    }

    /// Modeling half of `docs-site/screenshots/materials.lua` (the capture/quit tail is
    /// stripped so this can run without a GPU frame).
    fn materials_screenshot_modeling_lua() -> String {
        let src = include_str!("../docs-site/screenshots/materials.lua");
        let cut = src
            .find("bearcad.clear_selection()")
            .expect("materials.lua should separate modeling from the capture tail");
        src[..cut].to_string()
    }

    /// The materials screenshot is eight colored corner cubes plus a same-size centre
    /// cube that overlaps them all, with a through-hole, a sphere bite, a chamfer and a
    /// fillet each on a different corner cube.
    #[test]
    fn lua_materials_screenshot_scene_connects_cubes_and_features() {
        let state = run_lua(&materials_screenshot_modeling_lua());

        let cuboids: Vec<_> = state
            .doc
            .primitives
            .values()
            .filter(|p| p.kind == crate::model::PrimitiveKind::Cuboid)
            .collect();
        let spheres: Vec<_> = state
            .doc
            .primitives
            .values()
            .filter(|p| p.kind == crate::model::PrimitiveKind::Sphere)
            .collect();
        assert_eq!(cuboids.len(), 9, "eight corners plus a centre cube");
        assert_eq!(spheres.len(), 1, "one sphere to subtract from a side");
        assert_eq!(state.doc.extrusions.len(), 1, "circle extruded through one cube");
        assert_eq!(state.doc.boolean_ops.len(), 1, "sphere subtract is a Combine cut");
        assert_eq!(
            state.doc.boolean_ops.values().next().unwrap().kind,
            crate::model::BooleanOpKind::Cut
        );
        assert_eq!(
            state.doc.edge_treatment_ops.len(),
            2,
            "one chamfer and one fillet"
        );
        let kinds: Vec<_> = state
            .doc
            .edge_treatment_ops
            .values()
            .map(|op| op.kind)
            .collect();
        assert!(kinds.contains(&VertexTreatmentKind::Chamfer));
        assert!(kinds.contains(&VertexTreatmentKind::Fillet));

        let live: Vec<_> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .collect();
        assert_eq!(live.len(), 9, "nine live colored bodies (sphere is a shadow)");

        let mats: std::collections::HashSet<_> =
            live.iter().filter_map(|(_, b)| b.material).collect();
        assert_eq!(mats.len(), 9, "each live body keeps a distinct material");

        let mut volumes: Vec<f32> = live
            .iter()
            .filter_map(|(k, _)| {
                crate::extrude::body_solid_mesh(&state.doc, *k)
                    .map(|m| crate::extrude::mesh_signed_volume(&m).abs())
            })
            .collect();
        volumes.sort_by(|a, b| a.partial_cmp(b).unwrap());
        assert_eq!(volumes.len(), 9);
        let full = 20.0 * 20.0 * 20.0;
        let treated = volumes.iter().filter(|&&v| v < full - 50.0).count();
        assert!(
            treated >= 4,
            "hole, sphere bite, chamfer and fillet should each remove volume, got {volumes:?}"
        );

        let centre = cuboids
            .iter()
            .find(|p| (p.origin[0]).abs() < 1e-3 && (p.origin[1]).abs() < 1e-3)
            .expect("a same-size cube centred in the cluster");
        assert_eq!(centre.width, "20");
        assert_eq!(centre.depth, "20");
        assert_eq!(centre.height, "20");
    }

