    /// #1866: `["end"]` is no longer accepted — scripts must use `endpoint`.
    #[test]
    fn lua_select_line_end_key_is_rejected() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            local ok, err = pcall(function()
                bearcad.select{ kind = "line", index = 0, ["end"] = "start" }
            end)
            assert(not ok, "the reserved-word `end` key must be rejected")
            err = tostring(err)
            assert(err:find("endpoint"), "error should name the canonical key, got: " .. err)
        "#,
        );
        assert!(state.scene_selection.is_empty(), "failed select must not pick the line");
    }

    /// #1866: a line handle names its endpoints as `start()` / `endpoint("end")`.
    #[test]
    fn lua_line_handle_start_and_endpoint() {
        let state = run_lua(
            r#"
            bearcad.new()
            local a = bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            local b = bearcad.line{ x = 20, y = 0, x1 = 30, y1 = 0 }
            bearcad.constrain("coincident", a:endpoint("end"), b:start())
        "#,
        );
        let end_point = crate::model::ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
            line: lkey(0),
            end: LineEnd::End,
        });
        let start_point = crate::model::ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
            line: lkey(1),
            end: LineEnd::Start,
        });
        assert!(
            state.doc.constraints.values().any(|c| {
                matches!(
                        &c.kind,
                        crate::model::ConstraintKind::Coincident { a, b }
                            if (*a == end_point && *b == start_point)
                                || (*a == start_point && *b == end_point)
                    )
            }),
            "expected a Coincident constraint from line handle endpoints, got: {:?}",
            state.doc.constraints
        );
    }

    /// #1803: a refused geometric constraint must say *why* — what the selection is
    /// missing — instead of a bare "not enabled for the current selection".
    #[test]
    fn lua_refused_geometric_constraint_error_says_what_is_missing() {
        let state = run_lua(
            r#"
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            bearcad.select{ kind = "line", index = 0 }
            local ok, err = pcall(bearcad.ui.add_geometric_constraint, "coincident")
            assert(not ok, "coincident needs two entities; one line must be refused")
            err = tostring(err)
            assert(err:find("still needs"), "unexpected error: " .. err)
            assert(err:find("point"), "error should name the missing role: " .. err)
        "#,
        );
        assert_eq!(state.doc.constraints.len(), 0);
    }

    /// #1803: with nothing selected the error says the selection has no sketch entities.
    #[test]
    fn lua_refused_geometric_constraint_error_covers_an_empty_selection() {
        let state = run_lua(
            r#"
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            local ok, err = pcall(bearcad.ui.add_geometric_constraint, "coincident")
            assert(not ok, "coincident with an empty selection must be refused")
            assert(
                tostring(err):find("no sketch entities"),
                "unexpected error: " .. tostring(err)
            )
        "#,
        );
        assert_eq!(state.doc.constraints.len(), 0);
    }

    /// The explicit-refs form `constrain(kind, a, b)` creates the
    /// constraint and leaves the script's own selection untouched.
    #[test]
    fn lua_add_geometric_constraint_refs_form_constrains_and_restores_selection() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 40, y1 = 0 }
            bearcad.line{ x = 0, y = 20, x1 = 40, y1 = 20 }
            bearcad.select{ kind = "line", index = 0 }
            bearcad.constrain("parallel",
                { kind = "line", index = 0 }, { kind = "line", index = 1 })
        "#,
        );
        assert_eq!(
            state.doc.constraints.len(),
            1,
            "the refs form must create the constraint"
        );
        assert_eq!(
            state.scene_selection.ordered(),
            vec![SceneElement::Line(lkey(0))],
            "the script's selection must survive the refs-form call"
        );
    }

    /// #1868: modeling uses `constrain(kind, a, b, …)` with handles / point tables.
    /// The call does not mutate the script's selection.
    #[test]
    fn lua_constrain_explicit_operands_does_not_mutate_selection() {
        let state = run_lua(
            r#"
            bearcad.new()
            local a = bearcad.line{ x = 0, y = 0, x1 = 40, y1 = 0 }
            local b = bearcad.line{ x = 0, y = 20, x1 = 40, y1 = 20 }
            bearcad.select(a)
            local par = bearcad.constrain("parallel", a, b)
            assert(par:kind() == "constraint", "constrain returns a handle")
            local sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "line" and sel[1].index == 0,
              "constrain must not change the script's selection")
        "#,
        );
        assert_eq!(
            state.doc.constraints.len(),
            1,
            "constrain must create the constraint"
        );
        assert_eq!(
            state.scene_selection.ordered(),
            vec![SceneElement::Line(lkey(0))],
            "the script's selection must survive constrain()"
        );
    }

    /// #1868: coincident takes endpoint handles; no select dance.
    #[test]
    fn lua_constrain_coincident_from_endpoint_handles() {
        let state = run_lua(
            r#"
            bearcad.new()
            local a = bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            local b = bearcad.line{ x = 20, y = 0, x1 = 30, y1 = 0 }
            bearcad.constrain("coincident", a:endpoint("end"), b:start())
        "#,
        );
        let end_point = crate::model::ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
            line: lkey(0),
            end: LineEnd::End,
        });
        let start_point = crate::model::ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
            line: lkey(1),
            end: LineEnd::Start,
        });
        assert!(
            state.doc.constraints.values().any(|c| {
                matches!(
                        &c.kind,
                        crate::model::ConstraintKind::Coincident { a, b }
                            if (*a == end_point && *b == start_point)
                                || (*a == start_point && *b == end_point)
                    )
            }),
            "expected Coincident from constrain(), got: {:?}",
            state.doc.constraints
        );
        assert!(
            state.scene_selection.is_empty(),
            "constrain must not select the operands"
        );
    }

    /// #1868: `dimension{ kind, …, value }` is the one call for length and angle.
    /// Angle `value` is a number or an expression.
    #[test]
    fn lua_dimension_table_sets_length_and_angle() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 40, y1 = 0 }
            bearcad.line{ x = 0, y = 0, x1 = 0, y1 = 30 }
            bearcad.dimension{ kind = "line", index = 0, value = "leg = 40mm" }
            bearcad.dimension{ kind = "angle", a = 0, b = 1, value = 90 }
        "#,
        );
        let expressions: Vec<String> = state
            .doc
            .constraints
            .values()
            .map(|c| c.expression.clone())
            .collect();
        assert!(
            expressions.iter().any(|e| e == "leg"),
            "length dimension should reference the inline parameter, got {expressions:?}"
        );
        assert!(
            expressions.iter().any(|e| e == "90"),
            "angle value may be a number, got {expressions:?}"
        );
        assert!(state.doc.parameters.values().any(|p| p.name == "leg"));
        assert!(
            state
                .doc
                .constraints
                .values()
                .any(|c| matches!(c.kind, crate::model::ConstraintKind::Angle { .. })),
            "expected an angle dimension, got: {:?}",
            state.doc.constraints
        );
    }

    /// #1868: the split modeling APIs are gone; selection-based apply lives under ui.
    #[test]
    fn lua_old_constraint_apis_are_gone_and_ui_uses_selection() {
        let state = run_lua(
            r#"
            assert(bearcad.add_constraint == nil, "add_constraint should be gone")
            assert(bearcad.add_angle_constraint == nil, "add_angle_constraint should be gone")
            assert(bearcad.add_geometric_constraint == nil,
              "add_geometric_constraint should move off the modeling namespace")
            assert(type(bearcad.constrain) == "function")
            assert(type(bearcad.dimension) == "function")
            assert(type(bearcad.ui.add_geometric_constraint) == "function")
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0, name = "a" }
            bearcad.line{ x = 0, y = 5, x1 = 3, y1 = 5, name = "b" }
            bearcad.select("a")
            bearcad.select("b", true)
            bearcad.ui.add_geometric_constraint("equal")
        "#,
        );
        assert!(
            state
                .doc
                .constraints
                .values()
                .any(|c| matches!(c.kind, crate::model::ConstraintKind::Equal { .. })),
            "ui.add_geometric_constraint should apply to the current selection"
        );
    }

    /// #1795: a begin_sketch that cannot resolve its face must fail the script — the
    /// next drawing verb silently falling back to the ground sketch is the bug.
    #[test]
    fn lua_begin_sketch_refuses_an_unresolvable_face_loudly() {
        let state = run_lua(
            r#"
            bearcad.new()
            -- A full-turn revolve has no caps: the flat faces are `revolve_side`s.
            bearcad.rect{ x = 5, y = 0, width = 5, height = 3 }
            bearcad.revolve{ polygon = {0, 1, 2, 3}, axis = "y", angle = 360 }
            local ok, err = pcall(bearcad.begin_sketch,
                { kind = "revolve_cap", revolution = 0,
                  profile = "polygon", profile_lines = {0, 1, 2, 3}, ["end"] = true })
            assert(not ok, "a cap sketch on a capless revolve must be refused")
            assert(tostring(err):find("cap"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("sketch") == 1, "no new sketch may be created")
        "#,
        );
        assert_eq!(state.doc.sketches.len(), 1);
        assert_eq!(state.doc.lines.len(), 4, "only the rect's lines");
    }

    /// #1795: `begin_sketch{ kind = "extrude_cap", extrusion = 0 }` against a revolve
    /// body names the revolve spellings instead of a bare "no extrusion 0".
    #[test]
    fn lua_begin_sketch_extrude_cap_on_a_revolve_names_the_alternative() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ x = 5, y = 0, width = 5, height = 3 }
            bearcad.revolve{ polygon = {0, 1, 2, 3}, axis = "y", angle = 360 }
            local ok, err = pcall(bearcad.begin_sketch,
                { kind = "extrude_cap", extrusion = 0,
                  profile = "polygon", profile_lines = {0, 1, 2, 3}, top = true })
            assert(not ok, "extrude_cap needs an extrusion; a revolve must be refused")
            err = tostring(err)
            assert(err:find("revolve_cap") and err:find("revolve_side"),
              "the error should name the revolve spellings: " .. err)
        "#,
        );
        assert_eq!(state.doc.sketches.len(), 1, "no new sketch");
    }

    /// #1795: the flat washer faces of a full-turn revolve are `revolve_side`s —
    /// sketching on one works, and the sketch session lands on it.
    #[test]
    fn lua_begin_sketch_revolve_side_hosts_a_sketch() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ x = 5, y = 0, width = 5, height = 3 }
            bearcad.revolve{ polygon = {0, 1, 2, 3}, axis = "y", angle = 360 }
            bearcad.begin_sketch{ kind = "revolve_side", revolution = 0,
                profile = "polygon", profile_lines = {0, 1, 2, 3}, edge = 2 }
            bearcad.circle{ x = 7, y = 1, r = 1 }
        "#,
        );
        assert_eq!(state.doc.sketches.len(), 2, "the cap sketch is created");
        let circle = &state.doc.circles.values().next().unwrap();
        let sketch_face = state.doc.sketch_face(circle.sketch).unwrap();
        assert!(
            matches!(sketch_face, crate::model::FaceId::RevolveSide { .. }),
            "the circle must land in the revolve-side sketch, got {sketch_face:?}"
        );
    }

    /// #1799: `kind = "top"` / `"bottom"` are accepted spellings for cap edges — a
    /// disc's rim can be filleted without knowing the `cap` + `top` dance.
    #[test]
    fn lua_fillet_edge_accepts_top_and_bottom_edge_kinds() {
        let state = run_lua(
            r#"
            bearcad.circle{ x = 0, y = 0, r = 20 }
            bearcad.extrude{ circle = 0, distance = 5 }
            bearcad.fillet_edge{ extrusion = 0,
                edge = { kind = "top", face = 0, edge = 0 }, radius = 2 }
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
    }

    /// #1799: `extrude_edges(i)` lists the edge refs `fillet_edge`/`chamfer_edge`
    /// actually accept, and each one round-trips into a real fillet call.
    #[test]
    fn lua_extrude_edges_lists_filletable_edges() {
        let state = run_lua(
            r#"
            bearcad.circle{ x = 0, y = 0, r = 20 }
            bearcad.extrude{ circle = 0, distance = 5 }
            local edges = bearcad.extrude_edges(0)
            assert(#edges == 2, "a disc has two rim edges, got " .. #edges)
            local kinds = {}
            for _, e in ipairs(edges) do
              assert(e.face == 0 and e.edge == 0, "rim refs name face 0 edge 0")
              kinds[e.kind] = true
            end
            assert(kinds.top and kinds.bottom, "both cap rims listed")
            -- Every listed edge must be accepted by fillet_edge.
            bearcad.fillet_edge{ extrusion = 0, edge = edges[1], radius = 1 }
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);

        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            local edges = bearcad.extrude_edges(0)
            assert(#edges == 12, "a box has 4 vertical + 8 cap edges, got " .. #edges)
            local vertical, cap = 0, 0
            for _, e in ipairs(edges) do
              if e.kind == "vertical" then vertical = vertical + 1 else cap = cap + 1 end
            end
            assert(vertical == 4 and cap == 8, "4 vertical + 8 cap edges")
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 1);
    }

    #[test]
    fn lua_select_circle_center_with_explicit_point_flag() {
        // #68: kind="circle" alone still selects the whole circle (unchanged); `point = true`
        // is required to target just its center point.
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.circle{ x = 0, y = 0, r = 5, name = "hole" }
            bearcad.select{ kind = "circle", index = 0, point = true }
        "#,
        );
        assert_eq!(
            state.scene_selection.iter().next(),
            Some(SceneElement::Point(ConstraintPoint::CircleCenter(rkey(0))))
        );
    }

    #[test]
    fn lua_line_creates_line_on_ground_plane() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ length = 80, name = "Guide" }
        "#,
        );
        assert_eq!(state.doc.lines.len(), 1);
        assert!((state.doc.lines[lkey(0)].length() - 80.0).abs() < 1e-2);
        assert_eq!(
            find_element_by_name(&state.doc, "Guide"),
            Some(SceneElement::Line(lkey(0)))
        );
    }

    /// Builds a state with a corner (two lines coincident at (10,0), the second running to
    /// `b_far`) and runs `source` against it. Pre-builds the coincident vertex directly in Rust
    /// (rather than via `bearcad.select{..., end=...}` + `add_geometric_constraint("coincident")`,
    /// #68) for brevity, then lets the script call `bearcad.chamfer_vertex`/`fillet_vertex`
    /// against it. Returns the final state and any script error.
    fn run_lua_against_corner(source: &str, b_far: (f32, f32)) -> (AppState, Option<String>) {
        use crate::model::{Constraint, ConstraintEntity, ConstraintKind, Line, LineEnd, ShapeKind};

        let mut runner = ScriptRunner::from_lua_source(source).unwrap();
        runner.verbose = false;
        let mut state = AppState::default();
        let sketch = state.doc.add_sketch(FaceId::ConstructionPlane(pkey(0)));
        state.doc.lines.insert(Line::from_local_endpoints(sketch, 0.0, 0.0, 10.0, 0.0));
        state
            .doc
            .lines
            .insert(Line::from_local_endpoints(sketch, 10.0, 0.0, b_far.0, b_far.1));
        state.doc.shape_order.extend([ShapeKind::Line, ShapeKind::Line]);
        state.doc.constraints.insert(Constraint {
            sketch,
            kind: ConstraintKind::Coincident {
                a: ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
                    line: lkey(0),
                    end: LineEnd::End,
                }),
                b: ConstraintEntity::Point(ConstraintPoint::LineEndpoint {
                    line: lkey(1),
                    end: LineEnd::Start,
                }),
            },
            expression: String::new(),
            dim_offset: None,
            name: None,
        });
        let mut synthetic = SyntheticInput::default();
        let ctx = egui::Context::default();
        while !runner.done {
            runner.tick(&mut state, &mut synthetic, None, &ctx);
        }
        (state, runner.error)
    }

    /// [`run_lua_against_corner`] with a 90-degree corner and no script error expected.
    fn run_lua_against_a_right_angle_corner(source: &str) -> AppState {
        let (state, error) = run_lua_against_corner(source, (10.0, 10.0));
        assert!(error.is_none(), "script error: {error:?}");
        state
    }

    #[test]
    fn lua_chamfer_vertex_truncates_and_bridges_the_corner() {
        let state = run_lua_against_a_right_angle_corner(
            r#"
            bearcad.chamfer_vertex{
                point = { kind = "line", index = 0, endpoint = "end" },
                distance = 3,
            }
        "#,
        );
        // #538: two sources shadowed + two trimmed copies + one bridge = 5 lines.
        assert_eq!(state.doc.lines.len(), 5, "trimmed copies + a bridge should be added");
        assert_eq!(state.doc.sketch_vertex_treatment_ops.len(), 1);
        let bridge = state.doc.lines.values().last().unwrap();
        assert!(!bridge.is_curved(), "chamfer bridges with a straight line");
    }

    #[test]
    fn lua_fillet_vertex_bridges_with_a_curve() {
        let state = run_lua_against_a_right_angle_corner(
            r#"
            bearcad.fillet_vertex{
                point = { kind = "line", index = 0, endpoint = "end" },
                radius = 3,
            }
        "#,
        );
        // #538: two sources shadowed + two trimmed copies + one bridge = 5 lines.
        assert_eq!(state.doc.lines.len(), 5, "trimmed copies + a bridge should be added");
        let bridge = state.doc.lines.values().last().unwrap();
        assert!(bridge.is_curved(), "fillet bridges with a curved line");
    }

    /// #1519: `points = { ... }` is one operation, matching `fillet_edge{ edges = { ... } }`.
    #[test]
    fn lua_fillet_vertex_points_is_one_operation() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 30 }
            bearcad.fillet_vertex{ points = {
                { kind = "line", index = 0, endpoint = "end" },
                { kind = "line", index = 1, endpoint = "end" },
            }, radius = 3 }
            "#,
        );
        assert_eq!(
            state.doc.sketch_vertex_treatment_ops.len(),
            1,
            "one call must be one sketch_vertex_treatment_op, got {}",
            state.doc.sketch_vertex_treatment_ops.len()
        );
        let op = state.doc.sketch_vertex_treatment_ops.values().next().unwrap();
        assert_eq!(op.corners.len(), 2, "both corners belong to that one op");
    }

    /// #1519: `chamfer_vertex{ points = { ... } }` is also one operation.
    #[test]
    fn lua_chamfer_vertex_points_is_one_operation() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 30 }
            bearcad.chamfer_vertex{ points = {
                { kind = "line", index = 0, endpoint = "end" },
                { kind = "line", index = 1, endpoint = "end" },
            }, distance = 3 }
            "#,
        );
        assert_eq!(state.doc.sketch_vertex_treatment_ops.len(), 1);
        let op = state.doc.sketch_vertex_treatment_ops.values().next().unwrap();
        assert_eq!(op.corners.len(), 2);
    }

    /// #110: a corner within ~1° of straight (SPEC §3.1) must be *rejected at commit*, not
    /// silently accepted into a micro-bridge. The second line here leaves the shared vertex
    /// (10,0) toward (20, 0.01) — about 0.06° off dead-straight from the first line.
    #[test]
    fn lua_fillet_vertex_errors_on_a_near_straight_corner() {
        let (state, error) = run_lua_against_corner(
            r#"
            local ok, err = pcall(bearcad.fillet_vertex, {
                point = { kind = "line", index = 0, endpoint = "end" },
                radius = 3,
            })
            assert(not ok, "near-straight corner fillet should error")
            assert(tostring(err):find("degenerate"), "unexpected error: " .. tostring(err))
        "#,
            (20.0, 0.01),
        );
        assert!(error.is_none(), "script error: {error:?}");
        assert_eq!(state.doc.lines.len(), 2, "no bridging line should be created");
    }

    /// #109: fillet/chamfer at a vertex that only one line touches must error (previously a
    /// silent no-op), and create nothing.
    #[test]
    fn lua_fillet_vertex_errors_on_a_one_line_vertex() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            local ok, err = pcall(bearcad.fillet_vertex, {
                point = { kind = "line", index = 0, endpoint = "end" },
                radius = 3,
            })
            assert(not ok, "fillet at a one-line vertex should error")
            assert(tostring(err):find("exactly two lines"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("line") == 1, "no bridging line should be created")
            local ok2, err2 = pcall(bearcad.chamfer_vertex, {
                point = { kind = "line", index = 0, endpoint = "end" },
                distance = 3,
            })
            assert(not ok2, "chamfer at a one-line vertex should error")
            assert(bearcad.count("line") == 1, "no bridging line should be created")
        "#,
        );
        assert_eq!(state.doc.lines.len(), 1);
    }

    /// #109: a vertex where three lines join is just as invalid for chamfer/fillet as one.
    #[test]
    fn lua_fillet_vertex_errors_on_a_three_line_vertex() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            bearcad.line{ x = 10, y = 0, x1 = 20, y1 = 5 }
            bearcad.line{ x = 10, y = 0, x1 = 10, y1 = 10 }
            bearcad.constrain("coincident",
                { kind = "line", index = 0, endpoint = "end" },
                { kind = "line", index = 1, endpoint = "start" })
            bearcad.constrain("coincident",
                { kind = "line", index = 0, endpoint = "end" },
                { kind = "line", index = 2, endpoint = "start" })
            local ok, err = pcall(bearcad.fillet_vertex, {
                point = { kind = "line", index = 0, endpoint = "end" },
                radius = 3,
            })
            assert(not ok, "fillet at a three-line vertex should error")
            assert(tostring(err):find("exactly two lines"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("line") == 3, "no bridging line should be created")
        "#,
        );
        assert_eq!(state.doc.lines.len(), 3);
    }

    /// #104: degenerate (zero-size) rect/circle/line calls must raise Lua errors and create
    /// nothing, instead of silently succeeding.
    #[test]
    fn lua_zero_size_shapes_error_and_create_nothing() {
        let state = run_lua(
            r#"
            bearcad.new()
            local ok, err = pcall(bearcad.rect, { width = 0, height = 0 })
            assert(not ok, "zero-size rect should error")
            assert(tostring(err):find("width and height"), "unexpected error: " .. tostring(err))
            local ok2, err2 = pcall(bearcad.circle, { r = 0 })
            assert(not ok2, "zero-radius circle should error")
            assert(tostring(err2):find("radius"), "unexpected error: " .. tostring(err2))
            local ok3, err3 = pcall(bearcad.line, { x = 20, y = 0, x1 = 20, y1 = 0 })
            assert(not ok3, "zero-length line should error")
            assert(tostring(err3):find("too short"), "unexpected error: " .. tostring(err3))
            assert(bearcad.count("line") == 0, "no lines should be created")
            assert(bearcad.count("circle") == 0, "no circles should be created")
        "#,
        );
        assert_eq!(state.doc.lines.len(), 0);
        assert_eq!(state.doc.circles.len(), 0);
    }

    /// #104: a zero-distance extrude must error and create nothing (previously it created an
    /// invisible extrusion).
    #[test]
    fn lua_zero_distance_extrude_errors_and_creates_nothing() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            local ok, err = pcall(bearcad.extrude, { polygon = {0, 1, 2, 3}, distance = 0 })
            assert(not ok, "zero-distance extrude should error")
            assert(tostring(err):find("non%-zero"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("extrusion") == 0, "no extrusion should be created")
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 0);
        assert_eq!(state.doc.bodies.len(), 0);
    }

    /// #112: extruding a polygon face whose line indices don't exist (or don't form a closed
    /// loop) must error and create nothing, instead of creating a dead extrusion.
    #[test]
    fn lua_extrude_errors_on_a_missing_polygon_line() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            local ok, err = pcall(bearcad.extrude, {
                polygon = {0, 1, 2, 99}, distance = 5, body = "add",
            })
            assert(not ok, "extrude with a nonexistent line index should error")
            -- The ordinal is resolved to a key at the script boundary (#1055), so a line that
            -- isn't there is caught by name before the loop check ever runs.
            assert(tostring(err):find("no line 99"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("extrusion") == 0, "extrusion count must be unchanged")
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 0);
    }

    /// #112: line indices that all exist but don't form a closed loop are rejected too.
    #[test]
    fn lua_extrude_errors_on_a_non_loop_polygon() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            local ok, err = pcall(bearcad.extrude, { polygon = {0, 1, 2}, distance = 5 })
            assert(not ok, "extrude with an open line set should error")
            assert(tostring(err):find("closed loop"), "unexpected error: " .. tostring(err))
            assert(bearcad.count("extrusion") == 0, "extrusion count must be unchanged")
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 0);
    }

    /// #1791: a closed chain of individual `bearcad.line` calls — endpoints coinciding
    /// exactly, with no `Coincident` constraints — is a valid face for `extrude`.
    #[test]
    fn lua_extrude_accepts_a_geometrically_closed_line_chain() {
        let state = run_lua(
            r#"
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0 }
            bearcad.line{ x = 10, y = 0, x1 = 10, y1 = 5 }
            bearcad.line{ x = 10, y = 5, x1 = 0, y1 = 5 }
            bearcad.line{ x = 0, y = 5, x1 = 0, y1 = 0 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 2 }
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 1, "chain should extrude");
        assert_eq!(state.doc.bodies.len(), 1);
    }

    /// #1791: the same geometrically closed chain revolves too — and when it doesn't,
    /// the error names the axis or the profile, not both at once.
    #[test]
    fn lua_revolve_accepts_a_geometrically_closed_line_chain() {
        let state = run_lua(
            r#"
            bearcad.line{ x = 2, y = 0, x1 = 7, y1 = 0 }
            bearcad.line{ x = 7, y = 0, x1 = 7, y1 = 5 }
            bearcad.line{ x = 7, y = 5, x1 = 2, y1 = 5 }
            bearcad.line{ x = 2, y = 5, x1 = 2, y1 = 0 }
            bearcad.revolve{ polygon = {0, 1, 2, 3}, axis = "y", angle = 360 }
        "#,
        );
        assert_eq!(state.doc.revolutions.len(), 1, "chain should revolve");
    }

    /// #1791: with a valid profile but a broken axis, the error must blame the axis —
    /// not conflate profile and axis in one message.
    #[test]
    fn lua_revolve_error_names_the_axis_when_the_profile_is_fine() {
        let state = run_lua(
            r#"
            bearcad.line{ x = 2, y = 0, x1 = 7, y1 = 0 }
            bearcad.line{ x = 7, y = 0, x1 = 7, y1 = 5 }
            bearcad.line{ x = 7, y = 5, x1 = 2, y1 = 5 }
            bearcad.line{ x = 2, y = 5, x1 = 2, y1 = 0 }
            -- A degenerate (zero-length) body-edge axis parses fine but is no real axis.
            bearcad.cuboid{ width = 1, depth = 1, height = 1 }
            local ok, err = pcall(bearcad.revolve,
                { polygon = {0, 1, 2, 3}, axis = { body = 0, from = {0,0,0}, to = {0,0,0} }, angle = 360 })
            assert(not ok, "revolve with a degenerate axis line should error")
            err = tostring(err)
            assert(err:find("axis is not a real line"), "unexpected error: " .. err)
            assert(not err:find("profile"), "error should not blame the profile: " .. err)
        "#,
        );
        assert_eq!(state.doc.revolutions.len(), 0);
    }

    /// #1796/#1797: deleting a sketch that a feature depends on is refused, naming the
    /// dependent — the feature must not silently revert (nor leave `body_stats` nil).
    #[test]
    fn lua_deleting_a_sketch_a_feature_depends_on_is_refused() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            local vol = bearcad.body_stats(0).volume
            bearcad.select{ kind = "sketch", index = 0 }
            local ok, err = pcall(bearcad.delete_selection)
            assert(not ok, "deleting a sketch a feature uses must be refused")
            err = tostring(err)
            assert(err:find("extrusion"), "the error should name the dependent: " .. err)
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 1, "the extrusion must survive");
        let mesh = crate::extrude::body_solid_mesh(&state.doc, state.doc.bodies.keys().nth(0).unwrap()).unwrap();
        assert!(mesh.triangles.len() > 0, "the body still meshes");
    }

    /// #1796: the pocket repro — a cut sketched on a face; deleting that sketch is refused.
    #[test]
    fn lua_deleting_the_pocket_sketch_is_refused() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.circle{ x = 0, y = 0, r = 20 }
            bearcad.extrude{ circle = 0, distance = 7 }
            bearcad.begin_sketch{ kind = "extrude_cap", extrusion = 0, profile = "circle", top = true }
            bearcad.circle{ x = 0, y = 0, r = 10 }
            bearcad.extrude{ circle = 1, distance = 3, body = "cut" }
            bearcad.exit_sketch()
            local vol = bearcad.body_stats(0).volume
            bearcad.select{ kind = "sketch", index = 1 }
            local ok, err = pcall(bearcad.delete_selection)
            assert(not ok, "deleting the pocket's sketch must be refused")
            assert(tostring(err):find("extrusion"), "unexpected error: " .. tostring(err))
            assert(math.abs(bearcad.body_stats(0).volume - vol) < 1e-3,
              "the cut must survive intact")
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 2);
    }

    /// A sketch no feature depends on deletes normally.
    #[test]
    fn lua_deleting_an_unreferenced_sketch_still_works() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.line{ x = 50, y = 50, x1 = 60, y1 = 60 }
            bearcad.select{ kind = "sketch", index = 0 }
            bearcad.delete_selection()
        "#,
        );
        assert_eq!(state.doc.sketches.len(), 0, "the sketch deletes");
        assert_eq!(state.doc.lines.len(), 0, "its lines go with it");
    }

    /// #1792: a combine result is a live recomputation of its inputs, so deleting an
    /// input must be refused (naming the dependent body) instead of silently gutting it.
    #[test]
    fn lua_deleting_a_combine_input_is_refused_and_the_result_survives() {
        let state = run_lua(
            r#"
            bearcad.cylinder{ radius = 47.5, height = 7 }
            bearcad.cylinder{ radius = 44.5, height = 7 }
            bearcad.combine{ op = "difference", a = {0}, b = {1} }   -- ring
            bearcad.cylinder{ radius = 47.5, height = 4 }            -- base
            bearcad.combine{ op = "union", a = {2}, b = {3} }      -- coaster
            local vol = bearcad.body_stats(2).volume
            bearcad.select{ kind = "body", index = 0 }
            bearcad.select({ kind = "body", index = 1 }, true)
            local ok, err = pcall(bearcad.delete_selection)
            assert(not ok, "deleting a combine input must be refused")
            err = tostring(err)
            assert(err:find("body 2") or err:find("body 3"),
              "the error should name the dependent body: " .. err)
            assert(math.abs(bearcad.body_stats(2).volume - vol) < 1e-3,
              "the coaster must survive intact")
        "#,
        );
        assert_eq!(state.doc.bodies.len(), 5, "no body was deleted");
    }

    /// #1794: concentric circles extrude into a ring — the inner circle is a hole, not
    /// a swallowed disc — and the same for revolve.
    #[test]
    fn lua_concentric_circles_extrude_to_a_ring() {
        let state = run_lua(
            r#"
            bearcad.circle{ x = 0, y = 0, r = 47.5 }
            bearcad.circle{ x = 0, y = 0, r = 44.5 }
            bearcad.extrude{ circles = {0, 1}, distance = 7 }
            local s = bearcad.body_stats(0)
            assert(s, "the ring must have stats")
            local disc = 3.14159 * 47.5 * 47.5 * 7
            local ring = 3.14159 * (47.5 * 47.5 - 44.5 * 44.5) * 7
            assert(s.volume < disc * 0.5, "inner circle must not be swallowed: " .. s.volume)
            assert(math.abs(s.volume - ring) < ring * 0.1,
              string.format("ring volume %.0f, got %.0f", ring, s.volume))
        "#,
        );
        assert_eq!(state.doc.extrusions.len(), 1);
    }

    /// #1895: `profiles` takes a circle handle or a list; a rect's four lines are one loop.
    #[test]
    fn lua_extrude_profiles_takes_a_rect_or_circle() {
        let state = run_lua(
            r#"
            local box = bearcad.rect{ width = 10, height = 8 }
            bearcad.extrude{ profiles = box, distance = 3 }
            local hole = bearcad.circle{ x = 20, y = 0, r = 2 }
            bearcad.extrude{ profiles = hole, distance = 4 }
            local a = bearcad.circle{ x = 40, y = 0, r = 5 }
            local b = bearcad.circle{ x = 40, y = 0, r = 2 }
            bearcad.extrude{ profiles = {a, b}, distance = 2 }
            "#,
        );
        let faces: Vec<_> = state
            .doc
            .extrusions
            .values()
            .map(|e| e.faces.clone())
            .collect();
        assert_eq!(faces.len(), 3);
        assert!(
            matches!(faces[0].as_slice(), [crate::model::ExtrudeFace::Polygon(lines)] if lines.len() == 4),
            "rect return is one polygon, got {:?}",
            faces[0]
        );
        assert!(
            matches!(faces[1].as_slice(), [crate::model::ExtrudeFace::Circle(_)]),
            "one circle handle is one circle profile, got {:?}",
            faces[1]
        );
        assert_eq!(faces[2].len(), 2, "two circle handles are two profiles");
        assert!(faces[2]
            .iter()
            .all(|f| matches!(f, crate::model::ExtrudeFace::Circle(_))));
    }

    /// #1895: two closed loops in one `profiles` list — the key that export was missing.
    #[test]
    fn lua_extrude_profiles_takes_two_polygons() {
        let state = run_lua(
            r#"
            local a = bearcad.rect{ width = 20, height = 20 }
            local b = bearcad.rect{ x = 5, y = 5, width = 8, height = 8 }
            bearcad.extrude{ profiles = {a, b}, distance = 5 }
            "#,
        );
        let ex = state.doc.extrusions.values().next().expect("one extrusion");
        assert_eq!(ex.faces.len(), 2, "both loops survive in one call");
        assert!(ex
            .faces
            .iter()
            .all(|f| matches!(f, crate::model::ExtrudeFace::Polygon(_))));
    }

    /// #1888: `sketch_faces` lists closed loops a later `extrude{ profiles = face }` consumes.
    #[test]
    fn lua_sketch_faces_lists_loops_circles_and_feeds_extrude() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 20, height = 20 }
            bearcad.rect{ x = 5, y = 5, width = 6, height = 6 }
            bearcad.circle{ x = 10, y = 10, r = 2 }
            local faces = bearcad.sketch_faces()
            assert(#faces == 3, "two rects and a circle, got " .. #faces)
            bearcad.extrude{ profiles = faces, distance = 4, body = "join" }
            "#,
        );
        let ex = state.doc.extrusions.values().next().expect("one extrusion");
        assert_eq!(ex.faces.len(), 3);
        let polygons = ex
            .faces
            .iter()
            .filter(|f| matches!(f, crate::model::ExtrudeFace::Polygon(_)))
            .count();
        let circles = ex
            .faces
            .iter()
            .filter(|f| matches!(f, crate::model::ExtrudeFace::Circle(_)))
            .count();
        assert_eq!(polygons, 2);
        assert_eq!(circles, 1);
    }

    /// #1793: `combine{ bake = true }` ends with exactly one body — the result baked
    /// into a standalone solid, inputs consumed — so a script can union and move on.
    #[test]
    fn lua_combine_bake_ends_with_exactly_one_body() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            bearcad.cuboid{ at = {5, 0, 0}, width = 10, depth = 10, height = 10 }
            bearcad.combine{ op = "union", a = {0}, b = {1}, bake = true }
            assert(bearcad.count("body") == 1, "expected exactly one body, got " .. bearcad.count("body"))
            local s = bearcad.body_stats(0)
            assert(s, "the baked body must have stats")
            assert(math.abs(s.volume - 1500) < 1, "union volume, got " .. s.volume)
        "#,
        );
        assert_eq!(state.doc.boolean_ops.len(), 0, "the op is gone");
        assert_eq!(state.doc.bodies.len(), 1);
    }

    /// #1793: without `bake`, combine keeps its shadowed inputs (unchanged behavior).
    #[test]
    fn lua_combine_without_bake_keeps_shadowed_inputs() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            bearcad.cuboid{ at = {5, 0, 0}, width = 10, depth = 10, height = 10 }
            bearcad.combine{ op = "union", a = {0}, b = {1} }
        "#,
        );
        assert_eq!(state.doc.bodies.len(), 3);
        assert_eq!(state.doc.boolean_ops.len(), 1);
    }

    /// A body no op depends on deletes normally.
    #[test]
    fn lua_deleting_an_unreferenced_body_still_works() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            bearcad.cuboid{ at = {50, 0, 0}, width = 5, depth = 5, height = 5 }
            bearcad.select{ kind = "body", index = 1 }
            bearcad.delete_selection()
        "#,
        );
        assert_eq!(state.doc.bodies.len(), 1);
    }

    /// #1878: `bearcad.delete(element)` removes that element without requiring or replacing
    /// the scene selection. `delete_selection` stays the GUI-equivalent.
    #[test]
    fn lua_delete_does_not_clobber_selection() {
        let state = run_lua(
            r#"
            local keep = bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local gone = bearcad.cuboid{ at = {50, 0, 0}, width = 5, depth = 5, height = 5 }
            bearcad.select(keep)
            local sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "body" and sel[1].index == keep:index(),
              "select the body we mean to keep")
            bearcad.delete(gone)
            assert(not gone:exists(), "the targeted body is gone")
            assert(keep:exists(), "the selected body is untouched")
            sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "body" and sel[1].index == keep:index(),
              "delete must not replace the scene selection")
            -- `{ kind, index }` form, and the handle method, take the same path.
            local extra = bearcad.cuboid{ at = {80, 0, 0}, width = 3, depth = 3, height = 3 }
            bearcad.delete{ kind = "body", index = extra:index() }
            assert(not extra:exists())
            local last = bearcad.cuboid{ at = {110, 0, 0}, width = 2, depth = 2, height = 2 }
            last:delete()
            assert(not last:exists())
            sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "body" and sel[1].index == keep:index(),
              "later deletes still leave the original selection")
            -- A list deletes every named element in one go.
            local a = bearcad.cuboid{ at = {0, 50, 0}, width = 2, depth = 2, height = 2 }
            local b = bearcad.cuboid{ at = {20, 50, 0}, width = 2, depth = 2, height = 2 }
            bearcad.delete{ a, b }
            assert(not a:exists() and not b:exists())
            assert(keep:exists())
            -- Dependent deletes are still refused, without selecting first.
            local sides = bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            local box = bearcad.extrude{ polygon = sides, distance = 5 }
            local ok, err = pcall(bearcad.delete, { kind = "sketch", index = 0 })
            assert(not ok, "deleting a sketch a feature uses must be refused")
            assert(tostring(err):find("extrusion"), "unexpected error: " .. tostring(err))
            assert(box:exists(), "the extrusion's body survives")
            local empty_ok, empty_err = pcall(bearcad.delete, {})
            assert(not empty_ok, "an empty list is nothing to delete")
            assert(tostring(empty_err):find("delete"), "unexpected error: " .. tostring(empty_err))
        "#,
        );
        assert!(state.doc.bodies.len() >= 1);
    }

    /// #1879: `bearcad.ui.picker(name)` / `bearcad.ui.gizmo(name)` return the named row, or nil.
    #[test]
    fn lua_picker_and_gizmo_lookup_by_name() {
        run_lua_expect_ok(
            r#"
            assert(type(bearcad.ui.picker) == "function")
            assert(type(bearcad.ui.gizmo) == "function")
            assert(bearcad.ui.picker("nope") == nil, "an unknown picker is nil, not an error")
            assert(bearcad.ui.gizmo("nope") == nil, "an unknown gizmo is nil, not an error")

            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.ui.begin_move{ bodies = {0} }
            bearcad.ui.tool_mode("free")
            local rz = bearcad.ui.gizmo("move_rz")
            assert(rz and rz.name == "move_rz", "gizmo looks up by name")
            assert(rz.kind == "rotate")
            local listed
            for _, g in ipairs(bearcad.ui.gizmos()) do
                if g.name == "move_rz" then listed = g end
            end
            assert(listed and listed.value == rz.value, "the named row matches gizmos()")
            bearcad.ui.set_gizmo{ name = "move_rz", value = 45 }
            assert(math.abs(bearcad.ui.gizmo("move_rz").value - 45) < 1e-3)
        "#,
        );
    }

    /// #77: `bearcad.chamfer_edge`/`fillet_edge` chamfer/fillet an analytic edge of an
    /// extrusion's 3D solid — declared directly (extrusion index + structured edge reference),
    /// not via screen-space picking.
    #[test]
    fn lua_chamfer_edge_bevels_a_vertical_edge_and_visibly_changes_the_mesh() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.chamfer_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                distance = 2,
            }
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
        assert_eq!(state.doc.edge_treatment_ops.values().nth(0).unwrap().kind, VertexTreatmentKind::Chamfer);
        // The chamfer's beveled output body has more than the 12 triangles of the plain box.
        let output = state.doc.edge_treatment_ops.values().nth(0).unwrap().outputs[0];
        let mesh = crate::extrude::body_solid_mesh(&state.doc, output).unwrap();
        assert_ne!(mesh.triangles.len(), 12);
    }

    /// #1875: `edit_chamfer` / `edit_fillet` change a committed edge treatment in place.
    #[test]
    fn lua_edit_fillet_and_chamfer_change_amount_in_place() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 20, height = 20 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                radius = 1,
            }
            local n = bearcad.count("edge_treatment")
            bearcad.edit_fillet{ index = 0, radius = 3 }
            assert(bearcad.count("edge_treatment") == n)
            local f = bearcad.get{ kind = "edge_treatment", index = 0 }
            assert(math.abs(f.amount - 3) < 1e-3, "fillet stayed " .. tostring(f.amount))

            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 20, height = 20 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.chamfer_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                distance = 1,
            }
            bearcad.edit_chamfer{ index = 0, distance = 2.5 }
            local c = bearcad.get{ kind = "edge_treatment", index = 0 }
            assert(math.abs(c.amount - 2.5) < 1e-3, "chamfer stayed " .. tostring(c.amount))
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
        assert!((state.doc.edge_treatment_ops.values().nth(0).unwrap().amount - 2.5).abs() < 1e-3);
    }

    /// #672: `edges = { ... }` treats the whole set in ONE operation (one undo, one amount).
    /// Sequential one-edge calls now chain onto the live body (#1323); a set is still the
    /// way to apply the same radius to several edges at once.
    #[test]
    fn lua_fillet_edge_treats_an_edge_set_as_one_operation() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 80, height = 50 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 20 }
            bearcad.fillet_edge{
                extrusion = 0,
                edges = {
                    { kind = "vertical", face = 0, edge = 0 },
                    { kind = "vertical", face = 0, edge = 1 },
                    { kind = "vertical", face = 0, edge = 2 },
                    { kind = "vertical", face = 0, edge = 3 },
                },
                radius = 8,
            }
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1, "one operation, not one per edge");
        assert_eq!(state.doc.edge_treatment_ops.values().nth(0).unwrap().edges.len(), 4);
        // One output body, and it carries all four rounds (far more than the box's 12 triangles).
        assert_eq!(state.doc.edge_treatment_ops.values().nth(0).unwrap().outputs.len(), 1);
        let output = state.doc.edge_treatment_ops.values().nth(0).unwrap().outputs[0];
        let mesh = crate::extrude::body_solid_mesh(&state.doc, output).unwrap();
        assert!(mesh.triangles.len() > 12, "{} triangles", mesh.triangles.len());
    }

    #[test]
    fn lua_fillet_edge_bevels_a_cap_edge_with_a_faceted_arc() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 1, top = true },
                radius = 1.5,
            }
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
        assert_eq!(state.doc.edge_treatment_ops.values().nth(0).unwrap().kind, VertexTreatmentKind::Fillet);
        assert!(matches!(
            state.doc.edge_treatment_ops.values().nth(0).unwrap().edges[0].edge,
            ExtrusionEdgeRef::Cap { face: 0, edge: 1, top: true }
        ));
    }

    /// #1565: chamfering every top-cap edge of a cutoff rectangle (the chamfer tutorial
    /// solid) must keep all five sides — adjacent cap edges share a corner, but that is
    /// two bevels, not a 3-edge vertex miter.
    #[test]
    fn lua_chamfer_edge_treats_every_top_edge_of_a_cutoff_box() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 40, height = 40 }
            bearcad.chamfer_vertex{
                point = { kind = "line", index = 1, endpoint = "end" },
                distance = 5,
            }
            bearcad.extrude{ polygon = {0, 4, 6, 5, 3}, distance = 10 }
            bearcad.chamfer_edge{
                extrusion = 0,
                edges = {
                    { kind = "cap", face = 0, edge = 0, top = true },
                    { kind = "cap", face = 0, edge = 1, top = true },
                    { kind = "cap", face = 0, edge = 2, top = true },
                    { kind = "cap", face = 0, edge = 3, top = true },
                    { kind = "cap", face = 0, edge = 4, top = true },
                },
                distance = 3,
            }
        "#,
        );
        let treated: usize = state
            .doc
            .edge_treatment_ops
            .values()
            .map(|op| op.edges.len())
            .sum();
        assert_eq!(
            treated, 5,
            "all five top-face edges should be chamfered, got {treated}; status={}",
            state.status
        );
        let output = state
            .doc
            .edge_treatment_ops
            .values()
            .next()
            .expect("one chamfer op")
            .outputs[0];
        let mesh = crate::extrude::body_solid_mesh(&state.doc, output).expect("beveled mesh");
        assert!(
            mesh.triangles.len() > 16,
            "five cap chamfers should add bevel faces, got {} triangles",
            mesh.triangles.len()
        );
    }

    /// #1321: `fillet_edge` with radius 0 is a no-op — no error, no operation, no extra body.
    #[test]
    fn lua_fillet_edge_zero_radius_is_a_noop() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                radius = 0,
            }
            assert(bearcad.count("body") == 1, "zero-radius fillet must not spawn a body")
        "#,
        );
        assert!(
            state.doc.edge_treatment_ops.is_empty(),
            "zero-radius fillet must not create an operation"
        );
        assert!(!state.doc.bodies.values().nth(0).unwrap().shadow);
    }

    /// #1323: two sequential `fillet_edge` calls on different edges of the same body chain —
    /// the second consumes the first's output — instead of forking two sibling bodies.
    #[test]
    fn lua_fillet_edge_stacks_a_second_fillet_on_the_same_body() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 20, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 2, top = true },
                radius = 2.3,
            }
            local v1 = bearcad.body_stats(1).volume
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 0, top = true },
                radius = 0.5,
            }
            -- Body 0 original (shadow), body 1 first fillet (shadow), body 2 both (live).
            local v2 = bearcad.body_stats(2).volume
            assert(v2 < v1 - 0.1, "stacked fillet must cut more than the first alone: " .. v2 .. " vs " .. v1)
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 2);
        let ops: Vec<_> = state.doc.edge_treatment_ops.values().collect();
        assert_eq!(ops[1].targets, ops[0].outputs);
        let live: Vec<_> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .map(|(k, _)| k)
            .collect();
        assert_eq!(live, ops[1].outputs);
    }

    /// #192/#531: a fillet shows in the Elements pane as its own operation node (with its
    /// beveled output body nested under it), labelled by kind; re-opening it for edit and
    /// committing a new amount rebuilds the operation rather than stacking a second one.
    #[test]
    fn edge_treatment_is_an_editable_operation_element() {
        let mut state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                radius = 1.5,
            }
        "#,
        );
        // It appears as a top-level operation node, labelled by its kind.
        let node = crate::hierarchy::HierarchyNode::EdgeTreatmentOp(etkey(0));
        let nodes = crate::hierarchy::build_element_list(&state.doc, state.sketch_session);
        assert!(nodes.contains(&node), "fillet op should show in the elements pane");
        assert!(crate::names::node_label(&state.doc, node).starts_with("Fillet"));
        // Its beveled output body nests under the operation node in the real tree.
        let tree = crate::hierarchy::build_hierarchy(&state.doc, state.sketch_session);
        let op_entry = crate::hierarchy::find_hierarchy_entry(&tree, node).expect("op entry");
        let output = state.doc.edge_treatment_ops.values().nth(0).unwrap().outputs[0];
        assert!(op_entry
            .children
            .iter()
            .any(|c| c.node == crate::hierarchy::HierarchyNode::Body(output)));

        // Re-opening the op for edit and committing a new amount leaves one live operation.
        assert_eq!(
            state.apply(crate::actions::Action::EditEdgeTreatmentOp {
                op: crate::model::edge_treatment_op_key_for_slot(0)
            }),
            crate::actions::ActionResult::Ok
        );
        let edge = crate::model::ExtrusionEdgeRef::Vertical { face: 0, edge: 0 };
        assert_eq!(
            state.apply(crate::actions::Action::CommitEdgeTreatments {
                edges: vec![(crate::model::TreatableSolid::Extrusion(xkey(0)), edge)],
                kind: VertexTreatmentKind::Fillet,
                amount: 2.75,
                expression: String::new(),
            }),
            crate::actions::ActionResult::Ok
        );
        let live: Vec<_> = state
            .doc
            .edge_treatment_ops
            .values()
            .collect();
        assert_eq!(live.len(), 1);
        assert!((live[0].amount - 2.75).abs() < 1e-4);
    }

    /// #1329: `fillet_edge` / `chamfer_edge` treat a Shape-tool cuboid the same way they
    /// treat a rectangular extrusion — `primitive =` names the shape, `edge` is the same
    /// vertical/cap address.
    #[test]
    fn lua_fillet_edge_treats_a_cuboid_primitive() {
        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 40, depth = 50, height = 22 }
            local v0 = bearcad.body_stats(0).volume
            bearcad.fillet_edge{
                primitive = 0,
                edge = { kind = "cap", face = 0, edge = 0, top = true },
                radius = 3,
            }
            local v1 = bearcad.body_stats(1).volume
            assert(v1 < v0 - 1, "fillet must cut the cuboid: " .. v1 .. " vs " .. v0)
        "#,
        );
        assert_eq!(state.doc.edge_treatment_ops.len(), 1);
        assert_eq!(
            state.doc.edge_treatment_ops.values().nth(0).unwrap().kind,
            VertexTreatmentKind::Fillet
        );
        let live: Vec<_> = state
            .doc
            .bodies
            .iter()
            .filter(|(_, b)| !b.shadow)
            .map(|(k, _)| k)
            .collect();
        assert_eq!(live.len(), 1, "one live filleted body");
    }

    /// #1871/#1872: `body_faces` entries, `body:face("top")`, and `body_edges` feed
    /// `begin_sketch` / `extrude_face` / `fillet` / `chamfer` without restating an
    /// extrusion-vs-primitive encoding. One `fillet{ body, edges }` is one operation.
    #[test]
    fn lua_body_faces_and_edges_are_the_identity_fillet_and_sketch_accept() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local box = bearcad.cuboid{ width = 40, depth = 30, height = 20 }
            local v0 = bearcad.body_stats(box).volume
            local faces = bearcad.body_faces(box)
            assert(#faces >= 6, "a cuboid has six flats")
            local top
            for _, f in ipairs(faces) do
                assert(f.body ~= nil and f.face ~= nil and f.normal ~= nil,
                    "body_faces keeps the joint centroid form")
                if f.normal[3] > 0.9 then top = f end
            end
            assert(top, "cuboid has a +Z face")
            bearcad.begin_sketch(top)
            bearcad.exit_sketch()
            assert(bearcad.count("sketch") >= 1, "begin_sketch accepted a body_faces entry")

            local named = box:face("top")
            bearcad.begin_sketch(named)
            bearcad.circle{ x = 20, y = 15, r = 4 }
            bearcad.extrude{ profiles = 0, distance = -8, body = "cut" }
            local after_cut = bearcad.body_stats(bearcad.count("body") - 1).volume
            assert(after_cut < v0 - 50, "cut through box:face('top') must remove material")

            bearcad.new()
            local block = bearcad.cuboid{ width = 40, depth = 40, height = 20 }
            local n_ext = bearcad.count("extrusion")
            local raised = bearcad.extrude_face{ face = block:face("top"), distance = 5 }
            assert(raised ~= nil, "extrude_face returns what it made")
            assert(bearcad.count("extrusion") == n_ext + 1, "extrude_face accepted box:face('top')")

            bearcad.new()
            local solid = bearcad.cuboid{ width = 40, depth = 40, height = 20 }
            local v1 = bearcad.body_stats(solid).volume
            local edges = bearcad.body_edges(solid)
            assert(#edges >= 12, "a cuboid has twelve edges")
            local vertical = {}
            for _, e in ipairs(edges) do
                local a, b = e.edge[1], e.edge[2]
                if math.abs(a[3] - b[3]) > 5 then
                    vertical[#vertical + 1] = e
                end
            end
            assert(#vertical == 4, "four vertical edges, got " .. #vertical)
            local op = bearcad.fillet{ body = solid, edges = vertical, radius = 3 }
            assert(op ~= nil, "fillet returns what it made")
            assert(bearcad.count("edge_treatment") == 1, "one call is one operation")
            local v2 = bearcad.body_stats(bearcad.count("body") - 1).volume
            assert(v2 < v1 - 10, "fillet{ body, edges } must cut the cuboid")

            bearcad.new()
            local sides = bearcad.rect{ width = 20, height = 10 }
            local extruded = bearcad.extrude{ profiles = sides, distance = 8 }
            local c0 = bearcad.body_stats(extruded).volume
            bearcad.chamfer{
                body = extruded,
                edges = {
                    { kind = "vertical", face = 0, edge = 0 },
                    { kind = "vertical", face = 0, edge = 1 },
                },
                distance = 2,
            }
            assert(bearcad.count("edge_treatment") == 1)
            local c1 = bearcad.body_stats(bearcad.count("body") - 1).volume
            assert(c1 < c0 - 1, "chamfer{ body, edges } must cut the extrusion")
            "#,
        );
    }

    /// #1872: `fillet` / `chamfer` are the modeling names; `fillet_edge` / `chamfer_edge`
    /// stay as aliases. Analytic `extrusion=` / `primitive=` remain optional.
    #[test]
    fn lua_fillet_and_chamfer_are_aliases_of_the_edge_verbs() {
        run_lua_expect_ok(
            r#"
            assert(type(bearcad.fillet) == "function")
            assert(type(bearcad.chamfer) == "function")
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 30, height = 20 }
            bearcad.fillet{
                primitive = 0,
                edge = { kind = "vertical", face = 0, edge = 0 },
                radius = 2,
            }
            assert(bearcad.count("edge_treatment") == 1)
            bearcad.new()
            bearcad.rect{ width = 20, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 8 }
            bearcad.chamfer_edge{
                body = 0,
                edges = { { kind = "vertical", face = 0, edge = 0 } },
                distance = 1,
            }
            assert(bearcad.count("edge_treatment") == 1)
            "#,
        );
    }

    /// #1324: fillets created through the scripted API must not draw a Document spoke
    /// once they have the treated body as an input.
    #[test]
    fn lua_fillet_has_no_document_graph_spoke() {
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 20, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 0, top = true },
                radius = 2.3,
            }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 1, top = true },
                radius = 0.5,
            }
            bearcad.fillet_edge{
                extrusion = 0,
                edge = { kind = "cap", face = 0, edge = 2, top = true },
                radius = 7.0,
            }
            "#,
        );
        let tree = crate::hierarchy::build_hierarchy(&state.doc, state.sketch_session);
        let positions = crate::hierarchy::graph_node_positions(&tree);
        let parents = crate::hierarchy::graph_parent_edges(&positions, &state.doc);
        assert_eq!(state.doc.edge_treatment_ops.len(), 3);
        for (oi, _) in state.doc.edge_treatment_ops.iter() {
            let fillet = crate::hierarchy::HierarchyNode::EdgeTreatmentOp(oi);
            assert!(
                !parents.iter().any(|(p, c)| {
                    *p == crate::hierarchy::HierarchyNode::Document && *c == fillet
                }),
                "fillet {oi:?} must not connect to Document"
            );
        }
        assert!(
            parents.iter().any(|(p, c)| {
                *p == crate::hierarchy::HierarchyNode::Document
                    && matches!(c, crate::hierarchy::HierarchyNode::ConstructionPlane(_))
            }),
            "root planes still hang off Document"
        );
    }

    /// #1425: moving a cuboid shadows its body; with shadows hidden (the default graph
    /// filter) the Move must still dash to the cuboid Shape that produced that body.
    #[test]
    fn lua_hidden_shadow_move_skips_to_the_shape() {
        use crate::hierarchy::{
            build_hierarchy, filter_hierarchy, graph_node_positions, graph_shadow_skip_edges,
            prune_shadow_bodies, ElementFilter, HierarchyNode,
        };
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 20, depth = 20, height = 20 }
            bearcad.cuboid{ width = 30, depth = 10, height = 40 }
            bearcad.move_bodies{ bodies = {0}, x = 10 }
            "#,
        );
        let filter = ElementFilter::default();
        assert!(!filter.shadow_bodies);
        let mut tree = filter_hierarchy(&build_hierarchy(&state.doc, None), &filter);
        prune_shadow_bodies(&mut tree, &state.doc);
        let present: std::collections::HashSet<HierarchyNode> =
            graph_node_positions(&tree).into_iter().map(|p| p.node).collect();

        let (shadow_bi, _) = state
            .doc
            .bodies
            .iter()
            .find(|(_, b)| b.shadow)
            .expect("move shadows the first cuboid");
        let shape = match &state.doc.bodies[shadow_bi].source {
            crate::model::BodySource::Primitive(pi) => *pi,
            other => panic!("shadowed body should be the cuboid primitive, got {other:?}"),
        };
        let (move_op, _) = state.doc.move_ops.iter().next().expect("one move");
        assert!(
            !present.contains(&HierarchyNode::Body(shadow_bi)),
            "default graph hides the shadow body"
        );
        let skips = graph_shadow_skip_edges(&state.doc, &present);
        assert!(
            skips.contains(&(HierarchyNode::Shape(shape), HierarchyNode::MoveOp(move_op))),
            "Move should dash to the cuboid that produced the hidden shadow: {skips:?}"
        );
    }

    #[test]
    fn lua_chamfer_edge_rejects_an_out_of_range_edge() {
        // `tick.exec` turns a failed declarative-modeling action into a Lua error
        // (#104/#109/#110/#112) — catchable with `pcall` — in addition to reporting it
        // through `AppState::status` like the interactive gizmo tool would see it.
        let state = run_lua(
            r#"
            bearcad.rect{ x = 0, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            local ok, err = pcall(bearcad.chamfer_edge, {
                extrusion = 0,
                edge = { kind = "vertical", face = 0, edge = 99 },
                distance = 2,
            })
            assert(not ok, "an out-of-range edge should error")
            assert(tostring(err):lower():find("edge"), "unexpected error: " .. tostring(err))
        "#,
        );
        assert!(
            state.doc.extrusions[xkey(0)].edge_treatments.is_empty(),
            "an out-of-range edge shouldn't be stored"
        );
        assert!(
            state.status.to_ascii_lowercase().contains("edge"),
            "status should explain the rejection: {}",
            state.status
        );
    }

    #[test]
    fn lua_line_with_bezier_creates_a_curve() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0, bezier = { {3, 4}, {7, 4} }, name = "Curve" }
        "#,
        );
        assert_eq!(state.doc.lines.len(), 1);
        let line = &state.doc.lines[lkey(0)];
        assert!(line.is_curved());
        assert_eq!(line.bezier, Some([(3.0, 4.0), (7.0, 4.0)]));
        assert_eq!(
            find_element_by_name(&state.doc, "Curve"),
            Some(SceneElement::Line(lkey(0)))
        );
    }

    #[test]
    fn lua_get_line_length_reports_arc_length_for_curves() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.line{ x = 0, y = 0, x1 = 10, y1 = 0, bezier = { {3, 4}, {7, 4} } }
            local l = bearcad.get{ kind = "line", index = 0 }
            assert(l.curved == true)
            -- Arc length of the curve, not the 10 mm endpoint chord.
            assert(l.length > 10.5, "expected arc length > chord, got " .. l.length)
        "#,
        );
    }

    /// #105: one `undo()` reverts one whole user action — the entire rectangle
    /// gesture (4 lines + its coincident/H/V/dimension constraints), not a single
    /// shape_order entry at a time.
    #[test]
    fn lua_undo_reverts_a_whole_rectangle_gesture() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 30 }
            bearcad.circle{ x = 60, y = 0, r = 8 }
            -- First undo removes only the circle gesture...
            bearcad.undo()
            assert(bearcad.count("circle") == 0, "circle should be undone first")
            assert(bearcad.count("line") == 4, "rect must survive the circle undo")
            -- ...second undo removes the whole rectangle in ONE step.
            bearcad.undo()
            assert(bearcad.count("line") == 0, "one undo must revert all 4 rect lines")
            assert(bearcad.count("constraint") == 0, "and every rect constraint")
        "#,
        );
    }

    /// #105: a cut extrusion undoes as one gesture — the cut extrusion disappears
    /// and the target body's volume is restored.
    #[test]
    fn lua_undo_reverts_a_cut_extrusion_gesture() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 30 }
            bearcad.extrude{ polygon = {0,1,2,3}, distance = 20 }
            bearcad.begin_sketch{ kind = "extrude_cap", extrusion = 0,
                                  profile = "polygon", profile_lines = {0,1,2,3}, top = true }
            bearcad.circle{ x = 10, y = 10, r = 5 }
            bearcad.extrude{ circle = 0, distance = -25, body = "cut" }
            local live = bearcad.count("body") - 1
            assert(bearcad.body_stats(live).volume < 23999, "cut should remove volume")
            bearcad.undo()
            local v = bearcad.body_stats(0).volume
            assert(math.abs(v - 24000) < 1, "cut undo must restore the body, got " .. v)
            assert(bearcad.count("extrusion") == 1, "cut extrusion removed from the doc")
        "#,
        );
    }

    /// #106: file-I/O failures surface as catchable Lua errors instead of silent
