    /// #107: `bearcad.get{ kind, index }` returns a table of the entity's fields, or nil
    /// when the index is out of range (or the entity is deleted).
    #[test]
    fn lua_get_returns_entity_fields_and_nil_out_of_range() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.line{ x = 1, y = 2, x1 = 11, y1 = 2, name = "Edge" }
            bearcad.circle{ x = 10, y = 5, r = 12 }
            local l = bearcad.get{ kind = "line", index = 0 }
            assert(math.abs(l.x0 - 1) < 1e-4 and math.abs(l.y0 - 2) < 1e-4)
            assert(math.abs(l.x1 - 11) < 1e-4 and math.abs(l.y1 - 2) < 1e-4)
            assert(l.curved == false and l.construction == false)
            assert(l.bezier == nil)
            assert(math.abs(l.length - 10) < 1e-3)
            assert(l.name == "Edge")
            assert(l.sketch == 0)
            local c = bearcad.get{ kind = "circle", index = 0 }
            assert(math.abs(c.x - 10) < 1e-4 and math.abs(c.y - 5) < 1e-4)
            assert(math.abs(c.r - 12) < 1e-4 and math.abs(c.diameter - 24) < 1e-4)
            assert(c.construction == false and c.name == nil)
            local s = bearcad.get{ kind = "sketch", index = 0 }
            assert(s.face == "plane")
            assert(math.abs(s.origin.x) < 1e-4 and math.abs(s.origin.y) < 1e-4 and math.abs(s.origin.z) < 1e-4)
            local p = bearcad.get{ kind = "plane", index = 0 }
            assert(p.origin[3] == 0 and p.normal[3] == 1)
            assert(bearcad.get{ kind = "line", index = 99 } == nil)
            assert(bearcad.get{ kind = "body", index = 0 } == nil)
        "#,
        );
    }

    /// #107: `bearcad.body_stats(index)` reports volume (divergence-theorem), triangle count,
    /// and world bbox for a body's solid mesh; nil for missing bodies.
    #[test]
    fn lua_body_stats_reports_volume_triangles_and_bbox() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ x = 0, y = 0, width = 40, height = 30 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            local s = bearcad.body_stats(0)
            assert(s ~= nil, "body_stats should return a table for body 0")
            assert(math.abs(s.volume - 12000) < 120, "volume " .. tostring(s.volume))
            assert(s.triangles > 0)
            -- #1887: bbox corners are { x, y, z }, matching camera target — not a 1-based array.
            assert(s.bbox.min.x ~= nil and s.bbox.min.y ~= nil and s.bbox.min.z ~= nil,
              "bbox.min should have named x,y,z")
            assert(math.abs((s.bbox.max.x - s.bbox.min.x) - 40) < 0.1)
            assert(math.abs((s.bbox.max.y - s.bbox.min.y) - 30) < 0.1)
            assert(math.abs((s.bbox.max.z - s.bbox.min.z) - 10) < 0.1)
            assert(s.bbox.min[3] == s.bbox.min.z, "array indices stay as aliases")
            assert(bearcad.body_stats(5) == nil)
        "#,
        );
    }

    /// #1615: cutting a through hole must subtract the cylinder, not a sliver of it.
    /// Cap-sketch (x, y) is the same frame as the profile, so the hole is centred
    /// in the 40×40 block — `x = 0, y = 0` would only notch a corner.
    #[test]
    fn lua_body_stats_volume_of_a_block_with_a_through_hole() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 40 }
            bearcad.extrude{ polygon = {0,1,2,3}, distance = 10 }
            bearcad.begin_sketch{ kind = "extrude_cap", extrusion = 0, profile = "polygon",
                                  profile_lines = {0,1,2,3}, top = true }
            bearcad.circle{ x = 20, y = 20, r = 5 }
            bearcad.extrude{ circle = 0, distance = 20, body = "cut" }
            local live = bearcad.count("body") - 1
            local cyls = bearcad.body_cylinders(live)
            assert(#cyls == 1, "the cut should leave one cylindrical hole, got " .. #cyls)
            assert(math.abs(cyls[1].radius - 5) < 0.01, "hole radius, got " .. cyls[1].radius)
            assert(math.abs(cyls[1].length - 10) < 0.1, "through-hole length, got " .. cyls[1].length)
            local expected = 40 * 40 * 10 - math.pi * 25 * 10
            local v = bearcad.body_stats(live).volume
            assert(math.abs(v - expected) < 20,
              "through-hole volume " .. v .. " expected " .. expected)
        "#,
        );
    }

    /// #1615: a hole sketched with the block (boolean difference extrusion) is the
    /// same solid: block minus cylinder.
    #[test]
    fn lua_body_stats_volume_of_a_boolean_extrude_through_hole() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 40 }
            bearcad.circle{ x = 20, y = 20, r = 5 }
            bearcad.extrude{
              boolean = { op = "difference", a = { polygon = {0,1,2,3} }, b = { circle = 0 } },
              distance = 10,
            }
            local expected = 40 * 40 * 10 - math.pi * 25 * 10
            local v = bearcad.body_stats(0).volume
            assert(math.abs(v - expected) < 20,
              "boolean-extrude through-hole volume " .. v .. " expected " .. expected)
        "#,
        );
    }

    /// #1615: `circle{ x = 0, y = 0 }` on an extrude cap uses the profile's origin, which
    /// for `rect{ width = 40, height = 40 }` is a corner — a quarter-cylinder notch, not a
    /// centred through hole. Volume must match that geometry (the 15804 figure from the
    /// issue), not block minus a full cylinder.
    #[test]
    fn lua_body_stats_volume_of_a_corner_notch_cut() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 40 }
            bearcad.extrude{ polygon = {0,1,2,3}, distance = 10 }
            bearcad.begin_sketch{ kind = "extrude_cap", extrusion = 0, profile = "polygon",
                                  profile_lines = {0,1,2,3}, top = true }
            bearcad.circle{ x = 0, y = 0, r = 5 }
            bearcad.extrude{ circle = 0, distance = 20, body = "cut" }
            local live = bearcad.count("body") - 1
            local expected = 40 * 40 * 10 - 0.25 * math.pi * 25 * 10
            local v = bearcad.body_stats(live).volume
            assert(math.abs(v - expected) < 20,
              "corner-notch volume " .. v .. " expected " .. expected)
        "#,
        );
    }

    /// #1509: `bearcad.ui.tool_hints(...)` shows/hides/toggles the viewport hint line.
    #[test]
    fn lua_tool_hints_toggles() {
        let state = run_lua("bearcad.ui.tool_hints(false)");
        assert!(!state.show_tool_hints, "explicit off");
        assert_eq!(state.status, "Tool hints off");

        let state = run_lua("bearcad.ui.tool_hints(false)\nbearcad.ui.tool_hints()");
        assert!(state.show_tool_hints, "bare call toggles");
        assert_eq!(state.status, "Tool hints on");

        let state = run_lua("bearcad.ui.tool_hints(true)\nbearcad.ui.tool_hints(true)");
        assert!(state.show_tool_hints, "setting it on twice leaves it on");
    }

