    /// #1882: `get` (and `handle:get()`) echoes the keys create/edit accept, plus evaluated
    /// numbers. Extrusion reports body/to/taper/expression; combine reports a/b lists.
    /// `selection()` tables work as handles; a point selection keeps its identity.
    #[test]
    fn lua_get_is_the_inverse_of_create() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.add_parameter("h", "12")
            local sides = bearcad.rect{ width = 20, height = 10 }
            local box = bearcad.extrude{
              profiles = sides, distance = "h", taper = 2, taper_mode = "distance",
              body = "new", name = "Block",
            }
            local ext = bearcad.get{ kind = "extrusion", index = 0 }
            assert(ext.body == "new", "body mode, got " .. tostring(ext.body))
            assert(ext.expression == "h", "expression, got " .. tostring(ext.expression))
            assert(math.abs(ext.distance - 12) < 1e-3, "evaluated distance " .. tostring(ext.distance))
            assert(math.abs(ext.taper - 2) < 1e-3, "taper " .. tostring(ext.taper))
            assert(ext.taper_mode == "distance", "taper_mode " .. tostring(ext.taper_mode))
            assert(ext.to == nil, "no up-to target")
            assert(ext.name == "Block")
            local eg = bearcad.element("extrusion", 0):get()
            assert(eg.body == "new" and eg.expression == "h",
              "handle:get extrusion, body=" .. tostring(eg.body) .. " expr=" .. tostring(eg.expression))
            assert(box:kind() == "body", "extrude returns a body, got " .. tostring(box:kind()))
            local bg = box:get()
            assert(bg ~= nil, "body handle:get()")
            box:select()
            local sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "body",
              "select body, got " .. (#sel > 0 and tostring(sel[1].kind) or "nothing"))
            bearcad.clear_selection()
            bearcad.select(sel[1])
            assert(#bearcad.selection() == 1, "selection table works as a handle")
            assert(math.abs(box:stats().volume - bearcad.body_stats(box).volume) < 1e-3,
              "stats vs body_stats")

            -- Up-to a construction plane round-trips as `to`.
            bearcad.new()
            bearcad.rect{ width = 10, height = 10 }
            bearcad.exit_sketch()
            bearcad.extrude{ polygon = {0, 1, 2, 3}, to = { plane = 0 } }
            ext = bearcad.get{ kind = "extrusion", index = 0 }
            assert(ext.to ~= nil and ext.to.plane == 0, "to.plane, got " .. tostring(ext.to and ext.to.plane))

            -- Add/cut body modes.
            bearcad.new()
            bearcad.rect{ width = 40, height = 40 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.begin_sketch{
              kind = "extrude_cap", extrusion = 0,
              profile = "polygon", profile_lines = {0, 1, 2, 3}, top = true,
            }
            bearcad.rect{ x = 5, y = 5, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 4, body = "add" }
            ext = bearcad.get{ kind = "extrusion", index = 1 }
            assert(ext.body == "add", "add body mode, got " .. tostring(ext.body))
            bearcad.rect{ x = 20, y = 20, width = 8, height = 8 }
            bearcad.extrude{ polygon = {8, 9, 10, 11}, distance = 12, body = "cut" }
            ext = bearcad.get{ kind = "extrusion", index = 2 }
            assert(ext.body == "cut", "cut body mode, got " .. tostring(ext.body))

            -- Combine get lists the operand bodies, not just counts.
            bearcad.new()
            local a = bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local b = bearcad.cuboid{ width = 6, depth = 6, height = 20, at = {0, 0, 0} }
            bearcad.combine{ op = "cut", a = {a}, b = {b} }
            local c = bearcad.get{ kind = "combine", index = 0 }
            assert(c.op == "cut")
            assert(type(c.a) == "table" and #c.a == 1, "a list, got " .. type(c.a))
            assert(type(c.b) == "table" and #c.b == 1)
            assert(c.a[1] == a:index() or (type(c.a[1]) == "userdata" and c.a[1]:index() == a:index()),
              "a[1] names the first body")
            bearcad.edit_combine{ index = 0, a = c.a, b = c.b, op = "cut" }

            -- Circle get already has radius; line get includes create's x/y.
            bearcad.new()
            bearcad.circle{ x = 3, y = 4, radius = 5 }
            local circ = bearcad.get{ kind = "circle", index = 0 }
            assert(math.abs(circ.radius - 5) < 1e-4 and math.abs(circ.r - 5) < 1e-4)
            local ln = bearcad.line{ x = 1, y = 2, x1 = 11, y1 = 2 }
            local lg = ln:get()
            assert(math.abs(lg.x - 1) < 1e-4 and math.abs(lg.y - 2) < 1e-4)
            assert(math.abs(lg.x1 - 11) < 1e-4)

            -- Point selections keep identity and work as handles.
            bearcad.clear_selection()
            bearcad.select{ kind = "line", index = 0, endpoint = "start" }
            sel = bearcad.selection()
            assert(#sel == 1)
            assert(sel[1].kind == "point" or sel[1].kind == "line",
              "point kind, got " .. tostring(sel[1].kind))
            assert(sel[1].index == 0, "point parent index, got " .. tostring(sel[1].index))
            assert(sel[1].endpoint == "start", "endpoint, got " .. tostring(sel[1].endpoint))
            bearcad.clear_selection()
            bearcad.select(sel[1])
            assert(#bearcad.selection() == 1, "point selection table works as a handle")
            "#,
        );
    }

    /// #1891: missing identity is nil on find-style reads; a missing write operand and an
    /// unknown enum error. `body_stats` distinguishes "no such body" from "body has no mesh".
    #[test]
    fn lua_missing_identity_is_nil_unknown_is_an_error() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            -- Find-style reads: missing → nil.
            assert(bearcad.get{ kind = "line", index = 0 } == nil)
            assert(bearcad.find("no-such") == nil)
            assert(bearcad.body_stats(0) == nil)
            assert(bearcad.line_endpoints(0) == nil)
            assert(select(1, bearcad.line_endpoints(0)) == nil)

            local ok, err = pcall(function() return bearcad.get{ kind = "widget", index = 0 } end)
            assert(not ok, "unknown get kind should error")
            assert(tostring(err):find("widget"), tostring(err))

            -- Missing required operand of a write → error.
            ok, err = pcall(function() bearcad.extrude{ distance = 10 } end)
            assert(not ok, "extrude without profiles should error")
            ok, err = pcall(function() bearcad.combine{ op = "cut" } end)
            assert(not ok, "combine without a/b should error")
            ok, err = pcall(function() bearcad.delete() end)
            assert(not ok, "delete without an element should error")

            -- Unknown enums always error.
            bearcad.rect{ width = 10, height = 10 }
            ok, err = pcall(function()
              bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5, taper_mode = "sideways" }
            end)
            assert(not ok, "unknown taper_mode should error")
            assert(tostring(err):find("sideways"), tostring(err))
            ok, err = pcall(function()
              bearcad.combine{ op = "melt", a = {0}, b = {0} }
            end)
            assert(not ok, "unknown boolean op should error")
            "#,
        );

        let mut state = crate::actions::AppState::default();
        let mesh = state.doc.imported_meshes.insert(crate::model::ImportedMesh {
            triangles: Vec::new(),
            source_name: "empty".into(),
            step_bytes: None,
        });
        state.doc.bodies.insert(crate::model::Body {
            source: crate::model::BodySource::Imported(mesh),
            name: None,
            material: None,
            shadow: false,
        });
        run_lua_on(
            state,
            r#"
            assert(bearcad.count("body") == 1)
            assert(bearcad.body_stats(99) == nil, "missing body is nil")
            local ok, err = pcall(bearcad.body_stats, 0)
            assert(not ok, "existing body with no mesh should error, not nil")
            err = tostring(err)
            assert(err:find("mesh") or err:find("no solid"), "unexpected: " .. err)
            "#,
        );
    }

    /// #1747: `bearcad.select` can name a drawing's page items — a projection, a text
    /// annotation, an edge dimension, and a free point-to-point dimension — by
    /// `{ kind, drawing, view/index }` tables, the same ordinals the other drawing verbs take.
    #[test]
    fn lua_select_names_drawing_page_items() {
        // The projection.
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, body = 0, orientation = "front" }
            bearcad.ui.tool("select")
            bearcad.select{ kind = "projection", drawing = d, view = 0 }
            "#,
        );
        assert_eq!(
            state.selected_drawing_elements,
            vec![(dkey(0), crate::context::DrawingElementRef::Projection(0))],
            "the projection is what the script selected"
        );

        // The text annotation and the point-to-point dimension, additively.
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, body = 0, orientation = "front" }
            bearcad.drawing_text{ drawing = d, text = "note", x = 0.1, y = 0.2 }
            bearcad.drawing_point_dimension{ drawing = d, view = 0,
                                             a = {0, 0}, b = {10, 0} }
            bearcad.ui.tool("select")
            bearcad.select{ kind = "annotation", drawing = d, index = 0 }
            bearcad.select({ kind = "dimension", drawing = d, view = 0, index = 0 },
                           { additive = true })
            "#,
        );
        assert_eq!(
            state.selected_drawing_elements,
            vec![
                (dkey(0), crate::context::DrawingElementRef::Text(akey(0))),
                (
                    dkey(0),
                    crate::context::DrawingElementRef::PointDim { view: 0, index: 0 }
                ),
            ],
            "annotation + point dimension selected together"
        );

        // #1910: a zoom loupe is a page item scripts can name the same way.
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, body = 0, orientation = "front" }
            bearcad.drawing_loupe{ drawing = d, view = 0, at = {0, 0}, radius = 4,
                                   to = {10, -20}, to_radius = 20 }
            bearcad.ui.tool("select")
            bearcad.clear_selection()
            bearcad.select{ kind = "drawing_loupe", drawing = d, view = 0, index = 0 }
            "#,
        );
        assert_eq!(
            state.selected_drawing_elements,
            vec![(
                dkey(0),
                crate::context::DrawingElementRef::Loupe {
                    view: 0,
                    index: 0,
                    magnified: true,
                }
            )],
            "the loupe is what the script selected"
        );
    }

    /// #1932: a datum plane's offset is the most natural thing in a model to drive from a
    /// parameter, and `plane{ offset = expr }` baked it to a number. `get` also never told
    /// a script how the plane was defined, only where it landed.
    #[test]
    fn lua_plane_offset_stays_live_and_reads_back() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.add_parameter("u", "10")
            local pl = bearcad.plane{ offset = "u*3", name = "Deck" }
            assert(math.abs(pl:get().origin.z - 30) < 1e-3,
                   "offset evaluates: " .. pl:get().origin.z)
            assert(pl:get().offset ~= nil, "get must report the offset")
            assert(math.abs(pl:get().offset - 30) < 1e-3, "offset in mm: " .. pl:get().offset)
            assert(pl:get().offset_expression == "u*3",
                   "get must report how it was defined: " .. tostring(pl:get().offset_expression))
            bearcad.set_parameter("u", "20")
            assert(math.abs(pl:get().origin.z - 60) < 1e-3,
                   "the expression must stay live: " .. pl:get().origin.z)
            assert(math.abs(pl:get().offset - 60) < 1e-3, "offset follows: " .. pl:get().offset)

            -- An axis plane's angle is the same deal.
            bearcad.add_parameter("tilt", "30")
            local ax = bearcad.plane{ axis = "x", angle = "tilt" }
            assert(ax:get().angle_expression == "tilt",
                   "angle expression: " .. tostring(ax:get().angle_expression))
            assert(math.abs(ax:get().angle - 30) < 1e-3, "angle in degrees: " .. ax:get().angle)
            local n0 = ax:get().normal
            bearcad.set_parameter("tilt", "60")
            local n1 = ax:get().normal
            assert(math.abs(n0.y - n1.y) > 1e-3 or math.abs(n0.z - n1.z) > 1e-3,
                   "the axis plane must re-tilt when its parameter changes")

            -- A plain numeric offset has no expression to report.
            local fixed = bearcad.plane{ offset = 7 }
            assert(math.abs(fixed:get().offset - 7) < 1e-3)
            assert(fixed:get().offset_expression == nil, "no expression for a bare number")
            "#,
        );
    }

    /// #1935: `bearcad.ui.viewport()` reports the origin the docs promise, taken from the
    /// same rect clicks are measured against, in whole pixels so `string.format("%d", …)`
    /// works.
    #[test]
    fn lua_viewport_reports_its_origin_in_whole_pixels() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local v = bearcad.ui.viewport()
            assert(v.x ~= nil and v.y ~= nil, "viewport must report x and y")
            assert(v.x == math.floor(v.x) and v.y == math.floor(v.y), "x/y whole pixels")
            assert(v.width == math.floor(v.width) and v.height == math.floor(v.height),
                   "width/height whole pixels: " .. v.width .. "x" .. v.height)
            assert(string.format("%d,%d", v.x, v.y) ~= nil)
            assert(v.width == 960 and v.height == 560,
                   "the rect clicks address: " .. v.width .. "x" .. v.height)
            assert(v.x == 0 and v.y == 40, "its origin: " .. v.x .. "," .. v.y)
            "#,
        );
    }

    /// #1936: the ground display is an enum whose values were nowhere in the docs, and the
    /// obvious `ground = false` failed with Rust's conversion error. Booleans work now, and
    /// a bad value names the accepted ones.
    #[test]
    fn lua_camera_ground_takes_a_boolean_and_names_its_values() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.ui.camera{ ground = false }
            assert(bearcad.ui.camera{}.ground == "off", bearcad.ui.camera{}.ground)
            bearcad.ui.camera{ ground = true }
            assert(bearcad.ui.camera{}.ground == "grid", bearcad.ui.camera{}.ground)
            bearcad.ui.camera{ ground = "solid" }
            assert(bearcad.ui.camera{}.ground == "solid", bearcad.ui.camera{}.ground)
            bearcad.ui.ground(false)
            assert(bearcad.ui.camera{}.ground == "off", bearcad.ui.camera{}.ground)
            local ok, err = pcall(function() bearcad.ui.camera{ ground = "zzz" } end)
            assert(not ok, "a bogus ground must error")
            assert(tostring(err):find("grid") and tostring(err):find("solid")
                   and tostring(err):find("none"),
                   "the error must name the accepted values: " .. tostring(err))
            "#,
        );
    }

    /// #1934: a consumed (shadow) body is hidden everywhere and omitted from export, so
    /// `bearcad.visible()` must say so — and `live_body` counts and indexes only the bodies
    /// that are really there, which is the assertion a script actually wants to write.
    #[test]
    fn lua_shadow_bodies_read_back_as_hidden_and_are_filterable() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            local a = bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local b = bearcad.cuboid{ width = 10, depth = 10, height = 10, at = {30, 0, 0} }
            bearcad.combine{ op = "union", a = {a}, b = {b} }
            local shadows, live = 0, 0
            for i = 0, bearcad.count("body") - 1 do
              local h = bearcad.element("body", i)
              if bearcad.get("body", i).shadow then
                shadows = shadows + 1
                assert(not bearcad.visible(h), "a shadow body must read back hidden")
              else
                live = live + 1
                assert(bearcad.visible(h), "a live body must read back visible")
              end
            end
            assert(shadows == 2, "two consumed inputs, got " .. shadows)
            assert(bearcad.count("live_body") == live,
                   "live_body must count the real bodies: "
                   .. bearcad.count("live_body") .. " vs " .. live)
            for i = 0, bearcad.count("live_body") - 1 do
              assert(not bearcad.get("live_body", i).shadow,
                     "live_body " .. i .. " must not be a shadow")
              assert(bearcad.visible(bearcad.element("live_body", i)))
            end
            "#,
        );
    }

    /// #1941: `bearcad.clear_selection()` clears drawing page items too — `bearcad.select`
    /// puts them there and `bearcad.selection()` reports them, so the deselect verb has to
    /// reach them. Without it there is no scripted way to drop a projection's resize
    /// handles before screenshotting a sheet.
    #[test]
    fn lua_clear_selection_clears_drawing_page_items() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, body = 0, orientation = "front" }
            bearcad.drawing_text{ drawing = d, text = "note", x = 0.1, y = 0.2 }
            bearcad.ui.tool("select")
            bearcad.select{ kind = "projection", drawing = d, view = 0 }
            bearcad.select({ kind = "annotation", drawing = d, index = 0 }, { additive = true })
            assert(#bearcad.selection() == 2, "two page items selected")
            bearcad.clear_selection()
            assert(#bearcad.selection() == 0,
                   "clear_selection must drop them, still " .. #bearcad.selection())
            "#,
        );
        assert!(
            state.selected_drawing_elements.is_empty(),
            "the page must not keep the items armed either"
        );
    }

    /// #1906: selecting a body (the Elements pane, or `bearcad.select`) replaces drawing-view
    /// selection that isn't that body — a projection of those bodies is not the body.
    #[test]
    fn lua_selecting_a_body_deselects_an_unrelated_projection() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            bearcad.cuboid{ width = 20, depth = 20, height = 20, at = {40, 0, 0} }
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, bodies = {0, 1}, orientation = "front" }
            bearcad.ui.tool("select")
            bearcad.select{ kind = "projection", drawing = d, view = 0 }
            local function has(kind)
              for _, e in ipairs(bearcad.selection()) do
                if e.kind == kind then return true end
              end
              return false
            end
            assert(has("projection"), "the projection starts selected")
            bearcad.select{ kind = "body", index = 0 }
            assert(not has("projection"), "a body pick should drop the projection")
            assert(has("body") or has("primitive") or has("shape"),
              "the body should be selected")
            bearcad.select{ kind = "projection", drawing = d, view = 0 }
            bearcad.select({ kind = "body", index = 0 }, { additive = true })
            bearcad.select({ kind = "body", index = 1 }, { additive = true })
            assert(not has("projection"),
              "additive body picks should drop the projection too")
            local n = 0
            for _, e in ipairs(bearcad.selection()) do
              if e.kind == "body" or e.kind == "primitive" or e.kind == "shape" then
                n = n + 1
              end
            end
            assert(n == 2, "both bodies stay selected, got " .. n)
            "#,
        );
        assert!(
            state.selected_drawing_elements.is_empty(),
            "the drawing page should no longer think the projection is selected"
        );
    }

    /// #402: sizes accept parameter-expression strings anywhere the GUI does — rect
    /// width/height, circle r/radius/diameter, and extrude distance — and store the
    /// expression so the model rebuilds when the parameter changes.
    #[test]
    fn lua_sizes_accept_parameter_expressions() {
        let state = run_lua(
            r#"
            bearcad.add_parameter("w", "24")
            bearcad.rect{ width = "w", height = "w / 3" }
            bearcad.circle{ x = 40, y = 0, radius = "w / 4" }
            bearcad.circle{ x = 60, y = 0, diameter = "w" }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = "w / 2" }
            "#,
        );
        // Geometry evaluated against the parameter.
        let l = &state.doc.lines[lkey(0)];
        let width = ((l.x1 - l.x0).powi(2) + (l.y1 - l.y0).powi(2)).sqrt();
        assert!((width - 24.0).abs() < 1e-3, "rect width, got {width}");
        assert!((state.doc.circles[rkey(0)].r - 6.0).abs() < 1e-3, "radius expr");
        assert!((state.doc.circles[rkey(1)].r - 12.0).abs() < 1e-3, "diameter expr");
        assert!((state.doc.extrusions[xkey(0)].distance - 12.0).abs() < 1e-3);
        // Expressions stored, not baked numbers: the dims reference the parameter…
        assert_eq!(state.doc.extrusions[xkey(0)].expression, "w / 2");
        let exprs: Vec<&str> = state
            .doc
            .constraints
            .values()
            .map(|c| c.expression.as_str())
            .collect();
        assert!(exprs.contains(&"w"), "rect width constraint: {exprs:?}");
        assert!(exprs.contains(&"w / 3"), "rect height constraint: {exprs:?}");
        assert!(exprs.contains(&"(w / 4) * 2"), "radius constraint: {exprs:?}");

        // …so editing the parameter rebuilds the scripted model like a hand-built one.
        let state = run_lua(
            r#"
            bearcad.add_parameter("w", "24")
            bearcad.rect{ width = "w", height = "w / 3" }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = "w / 2" }
            bearcad.set_parameter("w", "30")
            "#,
        );
        let l = &state.doc.lines[lkey(0)];
        let width = ((l.x1 - l.x0).powi(2) + (l.y1 - l.y0).powi(2)).sqrt();
        assert!((width - 30.0).abs() < 1e-3, "rect follows the parameter, got {width}");
        assert!(
            (state.doc.extrusions[xkey(0)].distance - 15.0).abs() < 1e-3,
            "extrusion depth follows the parameter, got {}",
            state.doc.extrusions[xkey(0)].distance
        );
    }

    /// #403/#1894: unknown table keys are an error naming the accepted keys, repeat
    /// takes `spacing`, `count("image")` is a valid kind, and `drawing_view{ sketch = i }`
    /// projects a sketch.
    #[test]
    fn lua_api_polish_key_checks_aliases_and_sketch_views() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 20, height = 20 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }

            -- A typo'd key errors immediately, naming the accepted keys.
            local ok, err = pcall(function()
                bearcad.combine{ kind = "cut", a = {0}, b = {0} }
            end)
            assert(not ok, "combine{kind=} should error")
            assert(tostring(err):find("unknown key `kind`"), tostring(err))
            assert(tostring(err):find("op"), "error should list accepted keys: " .. tostring(err))
            local ok2, err2 = pcall(function()
                bearcad.rect{ width = 10, height = 10, witdh = 3 }
            end)
            assert(not ok2 and tostring(err2):find("witdh"), tostring(err2))

            bearcad.repeat_bodies{ bodies = {0}, axis = "x", count = 3, spacing = 5 }

            -- Images count (zero here, but the kind is valid).
            assert(bearcad.count("image") == 0)

            -- A drawing view of a sketch, not a body.
            local d = bearcad.drawing{}
            bearcad.drawing_view{ drawing = d, sketch = 0, orientation = "top" }
            local ok3 = pcall(function()
                bearcad.drawing_view{ drawing = d }
            end)
            assert(not ok3, "drawing_view without a source should error")
            "#,
        );
        assert_eq!(state.doc.repeat_ops.len(), 1);
        assert_eq!(state.doc.drawings[dkey(0)].views.len(), 1);
    }

    /// #648/#649/#650: naming both points makes a move a **snap** — the picked source corner
    /// lands exactly on the picked target corner, and x/y/z are ignored.
    #[test]
    fn lua_move_snaps_a_start_point_a_onto_a_end_point_a() {
        let state = run_lua(
            r#"
            -- Two 10x10x5 boxes: A at the origin, B 40mm along +X.
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            -- Snap A's origin corner onto B's near-bottom corner.
            bearcad.move_bodies{
                bodies = {0},
                from = { body = 0, vertex = {0, 0, 0} },
                to   = { body = 1, vertex = {40, 0, 0} },
                x = 999,  -- ignored: the points win
            }
            "#,
        );
        let op = &state.doc.move_ops.values().nth(0).unwrap();
        assert_eq!(op.translate_mode, crate::model::MoveTranslateMode::PointSnap);
        assert!(op.has_snap_translation());
        let t = crate::extrude::move_op_translation(&state.doc, op).expect("translation");
        assert!(
            (t - glam::Vec3::new(40.0, 0.0, 0.0)).length() < 1e-3,
            "snap offset should be +40 X, got {t:?}"
        );
        // The moved output really sits over body B.
        let out = op.outputs[0];
        let (min, _) = crate::extrude::body_solid_mesh(&state.doc, out)
            .and_then(|m| m.bounds())
            .expect("moved mesh");
        assert!((min.x - 40.0).abs() < 1e-2, "moved body starts at x=40, got {min:?}");
        // A plain x/y/z move stays free.
        let free = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.move_bodies{ bodies = {0}, x = 7 }
            "#,
        );
        assert_eq!(
            free.doc.move_ops.values().nth(0).unwrap().translate_mode,
            crate::model::MoveTranslateMode::Free
        );
    }

    /// #1889: `from`/`to` are arrays of mate points; `rotate = { x, y, z }` is the free turn.
    /// `from_b`/`to_b`/`from_c`/`to_c` are gone.
    #[test]
    fn lua_move_from_to_are_arrays_and_rotate_is_a_table() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.move_bodies{
                bodies = {0},
                from = {
                    { body = 0, vertex = {0, 0, 0} },
                    { body = 0, vertex = {10, 0, 0} },
                },
                to = {
                    { body = 0, vertex = {0, 0, 0} },
                    { body = 0, vertex = {0, 10, 0} },
                },
            }
            "#,
        );
        let op = &state.doc.move_ops.values().nth(0).unwrap();
        assert!(op.has_snap_rotation(), "a second from/to pair rotates");
        let m = crate::extrude::move_op_transform(&state.doc, op).expect("transform");
        let landed = m.transform_point3(glam::Vec3::new(10.0, 0.0, 0.0));
        assert!(
            (landed - glam::Vec3::new(0.0, 10.0, 0.0)).length() < 1e-2,
            "start B lands on end B, got {landed:?}"
        );

        let turned = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.move_bodies{ bodies = {0}, x = 10, rotate = { z = 90 } }
            "#,
        );
        let op = turned.doc.move_ops.values().next().unwrap();
        assert_eq!(op.rz, "90");

        let state = run_lua(
            r#"
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local ok, err = pcall(bearcad.move_bodies, {
                bodies = {0},
                from_b = { body = 0, vertex = {10, 0, 0} },
            })
            assert(not ok, "from_b must be gone")
            err = tostring(err)
            assert(err:find("from_b"), "the error should name from_b: " .. err)
            "#,
        );
        assert_eq!(state.doc.move_ops.len(), 0);
    }

    /// #669: a second `from`/`to` pair adds the rotation — the bodies turn about end
    /// point A so start point B lands on end point B.
    #[test]
    fn lua_move_b_pair_adds_the_rotation() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            -- No translation (A start = A end), then a quarter turn: the corner at
            -- (10, 0, 0) swings onto (0, 10, 0), both 10 from the pivot.
            bearcad.move_bodies{
                bodies = {0},
                from = {
                    { body = 0, vertex = {0, 0, 0} },
                    { body = 0, vertex = {10, 0, 0} },
                },
                to = {
                    { body = 0, vertex = {0, 0, 0} },
                    { body = 0, vertex = {0, 10, 0} },
                },
            }
            "#,
        );
        let op = &state.doc.move_ops.values().nth(0).unwrap();
        assert!(op.has_snap_rotation(), "both B points make it rotate");
        let m = crate::extrude::move_op_transform(&state.doc, op).expect("transform");
        let landed = m.transform_point3(glam::Vec3::new(10.0, 0.0, 0.0));
        assert!(
            (landed - glam::Vec3::new(0.0, 10.0, 0.0)).length() < 1e-2,
            "start B lands on end B, got {landed:?}"
        );
        // Naming only the A pair leaves it a pure translation.
        let translate_only = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.move_bodies{ bodies = {0},
                from = { body = 0, vertex = {0, 0, 0} },
                to   = { body = 0, vertex = {0, 0, 0} } }
            "#,
        );
        assert!(!translate_only.doc.move_ops.values().nth(0).unwrap().has_snap_rotation());
    }

    /// A third `from`/`to` pair pins the spin about `end A → end B` that the B pair leaves free.
    #[test]
    fn lua_move_c_pair_pins_the_remaining_spin() {
        let source = |c_from: &str, c_to: &str| {
            format!(
                r#"
            bearcad.rect{{ width = 10, height = 10 }}
            bearcad.extrude{{ polygon = {{0, 1, 2, 3}}, distance = 10 }}
            -- A holds the origin and B holds (10, 0, 0), so the box is still free to spin
            -- about the X axis; C is what decides that turn.
            bearcad.move_bodies{{
                bodies = {{0}},
                from = {{
                    {{ body = 0, vertex = {{0, 0, 0}} }},
                    {{ body = 0, vertex = {{10, 0, 0}} }},
                    {c_from}
                }},
                to = {{
                    {{ body = 0, vertex = {{0, 0, 0}} }},
                    {{ body = 0, vertex = {{10, 0, 0}} }},
                    {c_to}
                }},
            }}
            "#
            )
        };
        // Without C the spin is undecided, so nothing turns.
        let free = run_lua(&source("", ""));
        assert!(!free.doc.move_ops.values().nth(0).unwrap().has_snap_roll());
        let m = crate::extrude::move_op_transform(&free.doc, &free.doc.move_ops.values().nth(0).unwrap()).unwrap();
        let corner = glam::Vec3::new(0.0, 0.0, 10.0);
        assert!((m.transform_point3(corner) - corner).length() < 1e-2, "no C, no spin");

        // With C, the top corner swings a quarter turn onto +10 Y.
        let state = run_lua(&source(
            "{ body = 0, vertex = {0, 0, 10} }",
            "{ body = 0, vertex = {0, 10, 0} }",
        ));
        let op = &state.doc.move_ops.values().nth(0).unwrap();
        assert!(op.has_snap_roll(), "both C points pin the spin");
        let m = crate::extrude::move_op_transform(&state.doc, op).expect("transform");
        let landed = m.transform_point3(corner);
        assert!(
            (landed - glam::Vec3::new(0.0, 10.0, 0.0)).length() < 1e-2,
            "start C lands on end C, got {landed:?}"
        );
    }

    /// #1458: `bearcad.ui.move_preview()` is the Move tool's intended pose. Nothing
    /// in-progress means no ghost, so it is nil — the same answer a script gets
    /// before the first hover.
    #[test]
    fn lua_move_preview_is_nil_without_a_move() {
        run_lua_expect_ok(
            r#"
            assert(type(bearcad.ui.move_preview) == "function")
            assert(bearcad.ui.move_preview() == nil, "no move, no ghost")
            "#,
        );
    }

    /// `bearcad.ui.begin_move` arms the tool with its picks instead of committing them, so a
    /// script can drive the live preview — the ghost and the pair marks — the way the
    /// documentation shots do.
    #[test]
    fn lua_begin_move_arms_the_tool_without_committing() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 10 }
            bearcad.ui.begin_move{
                bodies = {1},
                from = {
                    { body = 1, vertex = {40, 0, 0} },
                    { body = 1, vertex = {50, 0, 0} },
                    { body = 1, vertex = {40, 0, 10} },
                },
                to = {
                    { body = 0, vertex = {0, 0, 10} },
                    { body = 0, on_edge = {10, 0, 10} },
                    { body = 0, on_edge = {0, 10, 10} },
                },
            }
            "#,
        );
        assert_eq!(state.tool, crate::actions::Tool::Move, "the Move tool comes up armed");
        assert!(state.doc.move_ops.is_empty(), "nothing is committed");
        let cm = state.creating_move.as_ref().expect("a move in progress");
        assert_eq!(cm.targets, vec![bkey(1)]);
        assert_eq!(cm.translate_mode, crate::model::MoveTranslateMode::PointSnap);
        for (what, point) in [
            ("start A", cm.start_point_a),
            ("end A", cm.end_point_a),
            ("start B", cm.start_point_b),
            ("end B", cm.end_point_b),
            ("start C", cm.start_point_c),
            ("end C", cm.end_point_c),
        ] {
            assert!(point.is_some(), "{what} should be armed");
        }
    }

    /// #891/#894: `bearcad.joint` commits a joint whose revolute position turns the
    /// driven body about the mated axis, and the joint lands in the document.
    #[test]
    fn lua_joint_commits_a_revolute_that_poses_the_driven_body() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            -- Faces are named by their own middle and normal, which `body_faces` reports.
            local function face_at(body, nx, ny, nz)
              for _, f in ipairs(bearcad.body_faces(body)) do
                if math.abs(f.normal[1] - nx) < 0.01
                   and math.abs(f.normal[2] - ny) < 0.01
                   and math.abs(f.normal[3] - nz) < 0.01 then
                  return f
                end
              end
            end
            bearcad.joint{
                a = 0, b = 1, kind = "revolute",
                face = { moving = face_at(1, 0, 0, -1), fixed = face_at(0, 0, 0, 1) },
                position = 90,
                name = "Hinge",
            }
            "#,
        );
        assert_eq!(state.doc.joints.len(), 1);
        let joint = &state.doc.joints.values().nth(0).unwrap();
        assert_eq!(joint.members.len(), 2);
        assert_eq!(joint.name.as_deref(), Some("Hinge"));
        assert_eq!(joint.rest, "90", "rest pose captured from creation (#898)");
        let pose = crate::joints::body_joint_pose(&state.doc, bkey(1)).expect("driven body posed");
        // Face Snap lands B's underside middle **on** A's top middle (5, 5, 5) (#1079); the
        // 90° turn about that normal swings B's far corner (50, 0, 0) — 5 mm along +X and
        // 5 mm along -Y of the mate point — round to (10, 10, 5).
        let landed = pose.transform_point3(glam::Vec3::new(50.0, 0.0, 0.0));
        assert!(
            (landed - glam::Vec3::new(10.0, 10.0, 5.0)).length() < 1e-2,
            "swung corner lands at {landed:?}"
        );
        // The status names the joint and both parts.
        assert!(state.status.contains("Revolute"), "{}", state.status);
    }

    /// #1013: a hole and a shaft have centre lines you can pick, so "put this peg in that
    /// hole" is one face pair and one line-up row — no fudging with face centres.
    #[test]
    fn lua_joint_seats_a_peg_in_a_hole() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 40, height = 40 }
            bearcad.circle{ x = 20, y = 20, r = 5 }
            bearcad.extrude{
              boolean = { op = "difference", a = { polygon = {0,1,2,3} }, b = { circle = 0 } },
              distance = 6,
            }
            bearcad.circle{ x = 100, y = 0, r = 5 }
            bearcad.extrude{ circle = 1, distance = 20 }
            bearcad.exit_sketch()
            local function face_facing(body, n)
              for _, f in ipairs(bearcad.body_faces(body)) do
                if math.abs(f.normal[1]-n[1]) < 0.01 and math.abs(f.normal[2]-n[2]) < 0.01
                   and math.abs(f.normal[3]-n[3]) < 0.01 then return f end
              end
            end
            assert(#bearcad.body_cylinders(0) == 1, "the plate has one hole")
            assert(#bearcad.body_cylinders(1) == 1, "the peg has one round wall")
            bearcad.joint{
              a = 0, b = 1, kind = "cylindrical",
              face = { moving = face_facing(1, {0,0,-1}), fixed = face_facing(0, {0,0,1}) },
              -- The hole's own centre line is the axis the peg turns and slides about.
              frame_axis = bearcad.body_cylinders(0)[1].axis,
            }
            "#,
        );
        assert_eq!(state.doc.joints.len(), 1);
        let mesh = crate::extrude::body_solid_mesh(&state.doc, bkey(1)).expect("the peg meshes");
        let (min, max) = mesh.bounds().expect("bounds");
        // The peg stands on the plate's top face (z = 6), and Face Snap lands its underside's
        // middle on that face's middle — which, on a square plate with a central hole, is the
        // hole's own centre (20, 20). So the peg comes out concentric with it (#1079).
        assert!((min.z - 6.0).abs() < 0.05, "peg sits on the plate, got {min}");
        // Exact (#1080): the centre a mate lands on is the face's **area** centroid, which is
        // the same point whatever way the mesh happened to triangulate it. Averaging triangle
        // vertices instead put this a couple of tenths out.
        assert!(
            ((min.x + max.x) * 0.5 - 20.0).abs() < 0.01
                && ((min.y + max.y) * 0.5 - 20.0).abs() < 0.01,
            "peg is concentric with the hole, spans {min}..{max}"
        );
    }

    /// #894: `bearcad.ui.begin_joint` arms the tool with its picks instead of committing.
    #[test]
    fn lua_begin_joint_arms_the_tool_without_committing() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            bearcad.ui.begin_joint{
                a = 0, b = 1, kind = "slider",
                face = {
                  moving = bearcad.body_faces(1)[1],
                  fixed  = bearcad.body_faces(0)[1],
                },
            }
            "#,
        );
        assert_eq!(state.tool, crate::actions::Tool::Joint, "the Joint tool comes up armed");
        assert!(state.doc.joints.is_empty(), "nothing is committed");
        let cj = state.creating_joint.as_ref().expect("a joint in progress");
        assert_eq!(cj.members.len(), 2);
        assert!(cj.placement.start_point_a.is_some() && cj.placement.end_point_a.is_some());
        assert!(matches!(cj.kind, crate::model::JointKind::Slider));
    }

    /// #894: `bearcad.edit_joint` re-points a committed joint; a loop-closing edit is
    /// refused loudly.
    #[test]
    fn lua_edit_joint_repoints_and_refuses_loops() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            bearcad.joint{ a = 0, b = 1, kind = "rigid" }
            bearcad.edit_joint{ index = 0, a = 0, b = 1, kind = "slider", position = 3 }
            -- A second joint driving the already-driven body 1 is refused.
            local ok, err = pcall(function()
                bearcad.joint{ a = 0, b = 1, kind = "rigid" }
            end)
            assert(not ok, "a second joint on the same driven part must fail")
            assert(tostring(err):find("already driven"), tostring(err))
            "#,
        );
        assert_eq!(state.doc.joints.len(), 1);
        assert!(matches!(state.doc.joints.values().nth(0).unwrap().kind, crate::model::JointKind::Slider));
        assert_eq!(state.doc.joints.values().nth(0).unwrap().position, "3");
    }

    /// #898: a joint's rest pose — captured at creation, recapturable, and reverted to,
    /// singly or all at once.
    #[test]
    fn lua_joint_rest_set_and_revert() {
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            bearcad.joint{ a = 0, b = 1, kind = "slider", position = 5 }
            -- Drag the joint elsewhere, then revert: back to the rest captured at creation.
            bearcad.edit_joint{ index = 0, a = 0, b = 1, kind = "slider", position = 12 }
            bearcad.revert_joint(0)
            "#,
        );
        assert_eq!(state.doc.joints.values().nth(0).unwrap().position, "5", "reverted to the creation pose");
        let state = run_lua(
            r#"
            bearcad.rect{ width = 10, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }
            bearcad.rect{ x = 40, y = 0, width = 10, height = 10 }
            bearcad.extrude{ polygon = {4, 5, 6, 7}, distance = 5 }
            bearcad.joint{ a = 0, b = 1, kind = "slider", position = 5 }
            bearcad.edit_joint{ index = 0, a = 0, b = 1, kind = "slider", position = 12 }
            -- Recapture: 12 becomes the pose Revert-all returns to.
            bearcad.set_joint_rest(0)
            bearcad.edit_joint{ index = 0, a = 0, b = 1, kind = "slider", position = 3 }
            bearcad.revert_joints()
            "#,
        );
        assert_eq!(state.doc.joints.values().nth(0).unwrap().position, "12", "revert-all returns to the recaptured rest");
    }

    /// #936: shapes cut each other properly — the sphere's kernel solid is a real BREP
    /// sphere, so a boolean against one lands geometry instead of an empty body.
    #[test]
    fn lua_a_shape_cuts_another_shape() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 40, depth = 40, height = 40 }
            bearcad.sphere{ at = {20, 20, 0}, radius = 20 }
            bearcad.combine{ op = "cut", a = {0}, b = {1}, keep_b = true }
            "#,
        );
        let volume = |i: crate::model::BodyKey| {
            crate::extrude::body_solid_mesh(&state.doc, i)
                .map(|m| crate::extrude::mesh_signed_volume(&m).abs())
                .unwrap_or(0.0)
        };
        let cut = state
            .doc
            .bodies
            .iter()
            .find_map(|(k, b)| matches!(b.source, crate::model::BodySource::Boolean { .. }).then_some(k))
            .expect("the cut lands an output body");
        let carved = volume(cut);
        assert!(carved > 0.0, "the cut body has geometry");
        assert!(
            carved < 64000.0 * 0.98,
            "and a bite out of it: {carved} vs the cuboid's 64000"
        );
    }

    /// #1581: Keep leftovers on intersect/difference splits A and B into three live parts.
    #[test]
    fn lua_combine_keep_leftovers_splits_into_three_parts() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 10, depth = 10, height = 5 }
            bearcad.cuboid{ width = 10, depth = 10, height = 5, at = {5, 0, 0} }
            bearcad.combine{ op = "intersect", a = {0}, b = {1}, keep_b = true }
            local vols = {}
            for i = 0, 20 do
                local b = bearcad.get{ kind = "body", index = i }
                if b == nil then break end
                if not b.shadow then
                    local s = bearcad.body_stats(i)
                    assert(s ~= nil, "live leftover body must mesh")
                    table.insert(vols, s.volume)
                end
            end
            assert(#vols == 3, "intersect+keep should keep three parts, got " .. #vols)
            table.sort(vols)
            for i = 1, 3 do
                assert(math.abs(vols[i] - 250) < 15,
                       "each part should be ~250, got " .. tostring(vols[i]))
            end
            "#,
        );
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 10, depth = 10, height = 5 }
            bearcad.cuboid{ width = 10, depth = 10, height = 5, at = {5, 0, 0} }
            bearcad.combine{ op = "xor", a = {0}, b = {1}, keep_b = true }
            local n = 0
            for i = 0, 20 do
                local b = bearcad.get{ kind = "body", index = i }
                if b == nil then break end
                if not b.shadow then n = n + 1 end
            end
            assert(n == 3, "xor+keep should keep three parts, got " .. n)
            "#,
        );
    }

    /// #1355 Case A: cutting a cutter that floats fully inside the target must leave a
    /// cavity (20³ − 4³ ≈ 7936), not an unsliced copy of the target.
    #[test]
    fn lua_cut_of_a_fully_enclosed_solid_leaves_a_cavity() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 20, depth = 20, height = 20 }
            -- 4³ sitting at z=8: [-2,2]×[-2,2]×[8,12] inside the 20³ on the ground.
            bearcad.cuboid{ width = 4, depth = 4, height = 4, at = {0, 0, 8} }
            bearcad.combine{ op = "cut", a = {0}, b = {1} }
            local s = bearcad.body_stats(2)
            assert(s ~= nil, "enclosed cut must produce a real body")
            assert(math.abs(s.volume - 7936) < 5,
                   "cavity volume should be 20^3-4^3=7936, got " .. tostring(s.volume))
            assert(s.triangles > 0)
        "#,
        );
    }

    /// #1355 Case B: A−B is empty when the target sits wholly inside the cutter. The op
    /// must error (no phantom body) and leave the document exportable.
    #[test]
    fn lua_cut_of_a_body_wholly_inside_the_cutter_errors() {
        let path = std::env::temp_dir().join(format!(
            "bearcad_lua_empty_cut_{}.stl",
            std::process::id()
        ));
        let path_s = path.to_string_lossy().replace('\\', "\\\\");
        let _ = std::fs::remove_file(&path);
        run_lua_expect_ok(&format!(
            r#"
            bearcad.new()
            bearcad.cuboid{{ width = 4, depth = 4, height = 4 }}
            bearcad.cuboid{{ width = 50, depth = 50, height = 50 }}
            local n = bearcad.count("body")
            local ok, err = pcall(function()
                bearcad.combine{{ op = "cut", a = {{0}}, b = {{1}} }}
            end)
            assert(not ok, "empty cut must raise, got success")
            assert(tostring(err):lower():find("empty", 1, true),
                   "error should say the result is empty, got " .. tostring(err))
            assert(bearcad.count("body") == n, "must not leave a phantom body")
            assert(bearcad.body_stats(0) ~= nil)
            assert(bearcad.body_stats(n) == nil)
            bearcad.export_stl("{path_s}")
        "#
        ));
        assert!(
            path.is_file(),
            "export of the remaining real bodies must still work"
        );
        let _ = std::fs::remove_file(&path);
    }

