    /// #1576: gear-options open/edit/editing are scriptable so Tab between bounds can be driven.
    #[test]
    fn lua_parameter_options_edit_is_scriptable() {
        let state = run_lua(
            r#"
            bearcad.add_parameter("width", "10mm")
            assert(bearcad.parameter_options("width") == false)
            bearcad.parameter_options("width", true)
            assert(bearcad.parameter_options("width") == true)
            bearcad.parameter_edit("width", "min")
            local e = bearcad.parameter_editing()
            assert(e.name == "width")
            assert(e.field == "min")
            bearcad.parameter_edit("width", "max")
            assert(bearcad.parameter_editing().field == "max")
            bearcad.parameter_options("width", false)
            assert(bearcad.parameter_options("width") == false)
            assert(bearcad.parameter_editing() == nil)
            "#,
        );
        assert!(state.parameters_pane.options_open.is_empty());
        assert!(state.parameters_pane.options_editing.is_none());
    }

    /// #1176/#1180: parameter min/max/step and private are scriptable.
    /// `private true` hides the knob (secondary); default plain value is public.
    #[test]
    fn lua_parameter_bounds_and_private() {
        let state = run_lua(
            r#"
            bearcad.add_parameter("width", "10mm")
            bearcad.edit_parameter{ name = "width", min = "5mm", max = "50mm", step = "2.5mm", private = true }
            "#,
        );
        let p = state.doc.parameters.values().next().unwrap();
        assert_eq!(p.minimum.as_deref(), Some("5mm"));
        assert_eq!(p.maximum.as_deref(), Some("50mm"));
        assert_eq!(p.step.as_deref(), Some("2.5mm"));
        assert!(!p.primary, "private true ⇒ secondary");
        let state = run_lua(
            r#"
            bearcad.add_parameter("width", "10mm")
            bearcad.edit_parameter{ name = "width", min = "5mm" }
            bearcad.edit_parameter{ name = "width", min = false }  -- clear
            "#,
        );
        assert!(state.doc.parameters.values().next().unwrap().minimum.is_none());
    }

    /// #1559: a local min+max parameter exposes a slider; setting it snaps like a drag.
    #[test]
    fn lua_parameter_slider_reads_and_sets() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.add_parameter("width", "10mm")
            bearcad.edit_parameter{ name = "width", min = "0mm", max = "20mm", step = "5mm" }
            local s = bearcad.parameter_slider("width")
            assert(s ~= nil, "min+max should offer a slider")
            assert(math.abs(s.min - 0) < 1e-4, "min")
            assert(math.abs(s.max - 20) < 1e-4, "max")
            assert(math.abs(s.value - 10) < 1e-4, "value")
            assert(math.abs(s.step - 5) < 1e-4, "step")
            bearcad.parameter_slider("width", 12)
            assert(math.abs(bearcad.parameter_value("width") - 10) < 1e-3,
                   "12 snaps to 10")
            bearcad.parameter_slider("width", 99)
            assert(math.abs(bearcad.parameter_value("width") - 20) < 1e-3,
                   "99 clamps to max")
            assert(bearcad.parameter_slider("missing") == nil, "no such parameter")
            bearcad.add_parameter("plain", "3mm")
            assert(bearcad.parameter_slider("plain") == nil, "no min/max ⇒ no slider")
            "#,
        );
    }

    /// #107/#1867: `parameter_value` / `parameter_expression` read a parameter back.
    #[test]
    fn lua_parameter_get_returns_value_and_expression() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.add_parameter("A", "5mm")
            local v = bearcad.parameter_value("A")
            assert(math.abs(v - 5) < 1e-4, "A should evaluate to 5mm, got " .. tostring(v))
            assert(bearcad.parameter_expression("A") == "5mm")
            assert(bearcad.parameter_value("missing") == nil)
            assert(bearcad.parameter_expression("missing") == nil)
        "#,
        );
    }

    /// #1867: parameters are name-first functions; the verb-string dispatcher is gone.
    #[test]
    fn lua_parameter_name_first_api() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            assert(bearcad.parameter == nil, "bearcad.parameter dispatcher must be gone")

            local p = bearcad.add_parameter("w", "24")
            assert(p:kind() == "parameter")
            assert(p:name() == "w")
            assert(math.abs(bearcad.parameter_value("w") - 24) < 1e-4)
            assert(math.abs(bearcad.parameter_value(p) - 24) < 1e-4)
            assert(bearcad.parameter_expression(p) == "24")

            bearcad.set_parameter("w", "30")
            assert(math.abs(bearcad.parameter_value("w") - 30) < 1e-4)
            bearcad.set_parameter(p, "12")
            assert(math.abs(bearcad.parameter_value(p) - 12) < 1e-4)

            bearcad.edit_parameter{ name = p, rename = "width", min = "1", max = "50", step = "1" }
            assert(p:name() == "width")
            assert(bearcad.parameter_value("width") ~= nil)
            assert(bearcad.parameter_value("w") == nil)

            local ok = pcall(bearcad.set_parameter, 0, "9")
            assert(not ok, "a raw ordinal is not a name or handle")

            bearcad.delete_parameter("width")
            assert(not p:exists())
            assert(bearcad.parameter_value("width") == nil)

            local q = bearcad.add_parameter("keep", "5")
            bearcad.add_parameter("drop", "9")
            bearcad.delete_parameter("drop")
            bearcad.set_parameter(q, "8")
            assert(math.abs(bearcad.parameter_value("keep") - 8) < 1e-4)

            bearcad.line{ x = 0, y = 0, x1 = 40, y1 = 0 }
            local L = bearcad.parameter_from_line_length(0, "len")
            assert(L:kind() == "parameter")
            assert(L:name() == "len")
            assert(math.abs(bearcad.parameter_value("len") - 40) < 1e-3)
            "#,
        );
    }

    /// #108: `circle{ radius = 12 }` is an alias of `r`; omitting all size keys is a clear
    /// error naming the accepted keys.
    #[test]
    fn lua_circle_accepts_radius_alias_and_errors_without_a_size() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.circle{ radius = 12 }
            local c = bearcad.get{ kind = "circle", index = 0 }
            assert(math.abs(c.r - 12) < 1e-4)
            local ok, err = pcall(bearcad.circle, { x = 0, y = 0 })
            assert(not ok, "circle without a size should error")
            err = tostring(err)
            assert(err:find("radius") and err:find("diameter"),
                   "error should name the accepted keys: " .. err)
        "#,
        );
    }

    /// #1883: `cube`/`box` alias cuboid (`cube{ size = 10 }` is equal sides); `r` /
    /// `radius` / `diameter` work on every radial size; circle `get` includes `radius`;
    /// kind names are the create-verb shorts (`plane`, `shape`, `revolution`).
    #[test]
    fn lua_cube_radius_and_canonical_kinds() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.cube{ size = 10, name = "Block" }
            local s = bearcad.get{ kind = "shape", index = 0 }
            assert(s.kind == "cuboid")
            assert(math.abs(s.width - 10) < 1e-4 and math.abs(s.depth - 10) < 1e-4
                   and math.abs(s.height - 10) < 1e-4)

            bearcad.new()
            bearcad.box{ width = 4, depth = 5, height = 6 }
            local b = bearcad.get{ kind = "shape", index = 0 }
            assert(math.abs(b.width - 4) < 1e-4 and math.abs(b.depth - 5) < 1e-4
                   and math.abs(b.height - 6) < 1e-4)

            bearcad.new()
            bearcad.cylinder{ r = 5, height = 10 }
            local cyl = bearcad.get{ kind = "shape", index = 0 }
            assert(math.abs(cyl.radius - 5) < 1e-4)
            bearcad.sphere{ diameter = 8 }
            local sp = bearcad.get{ kind = "shape", index = 1 }
            assert(math.abs(sp.radius - 4) < 1e-4)

            bearcad.new()
            bearcad.circle{ r = 12 }
            local circ = bearcad.get{ kind = "circle", index = 0 }
            assert(math.abs(circ.r - 12) < 1e-4)
            assert(math.abs(circ.radius - 12) < 1e-4, "get must include radius, not only r")
            assert(math.abs(circ.diameter - 24) < 1e-4)

            local p = bearcad.plane{ offset = 5 }
            assert(p:kind() == "plane", "plane, got " .. p:kind())
            assert(bearcad.count("plane") >= 4)
            bearcad.begin_sketch{ kind = "plane", index = 0 }
            bearcad.circle{ x = 0, y = 0, r = 2 }

            bearcad.new()
            bearcad.circle{ x = 0, y = 0, r = 20 }
            bearcad.extrude{ circle = 0, distance = 5 }
            bearcad.fillet_edge{ extrusion = 0,
                edge = { kind = "top", face = 0, edge = 0 }, r = 2 }
            assert(bearcad.count("edge_treatment") == 1)

            bearcad.new()
            bearcad.rect{ width = 20, height = 20 }
            bearcad.fillet_vertex{
                point = { kind = "line", index = 0, endpoint = "end" },
                diameter = 6,
            }
            assert(bearcad.count("sketch_chamfer") == 1)
        "#,
        );
    }

    /// #1894: one name per concept. `set_unit_parameter` (not `unit_override`),
    /// repeat `spacing` (not `gap`), revolve helix `pitch` (not `offset`/`gap`).
    #[test]
    fn lua_one_name_per_script_key() {
        run_lua_expect_ok(
            r#"
            assert(type(bearcad.set_unit_parameter) == "function")
            assert(bearcad.unit_override == nil, "unit_override is gone")

            bearcad.new()
            bearcad.cuboid{ width = 10, depth = 10, height = 10 }
            local ok, err = pcall(function()
                bearcad.repeat_bodies{ bodies = {0}, axis = "x", count = 3, gap = 5 }
            end)
            assert(not ok, "repeat gap should error")
            err = tostring(err)
            assert(err:find("gap") and err:find("spacing"), err)
            bearcad.repeat_bodies{ bodies = {0}, axis = "x", count = 3, spacing = 5 }

            bearcad.new()
            bearcad.rect{ x = 10, y = 0, width = 5, height = 4 }
            bearcad.exit_sketch()
            local ok2, err2 = pcall(function()
                bearcad.revolve{ polygon = {0,1,2,3}, axis = "y", gap = 10 }
            end)
            assert(not ok2, "revolve gap should error")
            err2 = tostring(err2)
            assert(err2:find("gap") and err2:find("pitch"), err2)
            bearcad.revolve{ polygon = {0,1,2,3}, axis = "y", pitch = 10 }
            local rev = bearcad.get{ kind = "revolution", index = 0 }
            assert(math.abs(rev.pitch - 10) < 1e-4)
        "#,
        );
    }

    /// #1828: a script can find a Context-pane row by its label, the way it can find an
