    /// #1687: a view's cutting planes — placed on a plane or face, then slid, turned, and
    /// flipped; several combine to cut in several directions at once.
    #[test]
    fn lua_section_planes_are_placed_and_adjusted() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 40, height = 30 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 10 }
            bearcad.exit_sketch()
            bearcad.cross_section{ name = "Front half" }

            local a = bearcad.section_plane{ plane = 1 }        -- the XZ datum
            assert(a == 0, "the first plane is 0, got " .. tostring(a))
            local b = bearcad.section_plane{ plane = 2, offset = 5, flip = true }
            assert(b == 1)
            assert(bearcad.get{ kind = "cross_section", index = 0 }.cuts == 2)

            local cuts = bearcad.section_planes(0)
            assert(#cuts == 2, "both planes read back")
            assert(math.abs(cuts[2].offset - 5) < 1e-4, "offset: " .. cuts[2].offset)
            assert(cuts[2].flip, "flip carried")
            assert(math.abs(cuts[1].normal[2] + 1) < 1e-3 or math.abs(cuts[1].normal[2] - 1) < 1e-3,
                   "the XZ plane's normal runs along Y")

            bearcad.edit_section_plane{ cut = 0, offset = -2.5, roll = 90 }
            cuts = bearcad.section_planes(0)
            assert(math.abs(cuts[1].offset + 2.5) < 1e-4)
            assert(math.abs(cuts[1].roll - 90) < 1e-3, "roll reads back in degrees")

            bearcad.delete_section_plane{ cut = 0 }
            cuts = bearcad.section_planes(0)
            assert(#cuts == 1 and cuts[1].flip, "the other plane survives")

            local ok = pcall(bearcad.delete_section_plane, { cut = 9 })
            assert(not ok, "an unknown plane should error")
        "#,
        );
    }

    /// #1787: a script can open the live edit draft of a cutting plane — the path where the
    /// offset/tilt preview stands in for the plane being edited (#1783).
    #[test]
    fn lua_begin_edit_section_plane_opens_the_edit_draft() {
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cuboid{ width = 30, depth = 20, height = 20 }
            bearcad.cross_section{}
            bearcad.section_plane{ origin = {0, 0, 0}, normal = {0, 0, 1}, offset = 5 }
            bearcad.ui.begin_edit_section_plane{ cut = 0 }
            "#,
        );
        let view = state.doc.cross_sections.keys().next().expect("the view");
        let cs = state
            .creating_section
            .as_ref()
            .expect("begin_edit_section_plane opens the edit draft");
        assert_eq!(cs.edit_cut, Some((view, 0)), "editing plane 0 of the view");
        assert!(
            state.status.contains("Edit cutting plane"),
            "the status names the edit: {}",
            state.status
        );
        // An unknown plane errors instead of opening a draft.
        let state = run_lua(
            r#"
            bearcad.new()
            bearcad.cross_section{}
            bearcad.section_plane{ origin = {0, 0, 0}, normal = {0, 0, 1} }
            local ok = pcall(bearcad.ui.begin_edit_section_plane, { cut = 3 })
            assert(not ok, "an unknown plane should error")
            "#,
        );
        assert!(state.creating_section.is_none(), "no draft for a bad pick");
    }

    /// A cutting plane is its own element: it shows in the Views section, and a script
    /// can count, get, select, rename, and delete it like any other.
    #[test]
    fn lua_section_planes_are_elements_in_the_views_section() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.cross_section{ name = "Front half" }
            assert(bearcad.count("section_plane") == 0, "a new view has no cutting planes")

            bearcad.section_plane{ origin = {0, 0, 0}, normal = {0, 0, 1} }
            assert(bearcad.count("section_plane") == 1, "the plane is countable")
            local p = bearcad.get{ kind = "section_plane", index = 0 }
            assert(p ~= nil, "the plane is readable")
            assert(p.view == 0, "it belongs to the view")
            assert(p.cut == 0)

            local g = bearcad.ui.elements_graph()
            local kinds = {}
            local names = {}
            for _, row in ipairs(g.rows) do
                kinds[row.kind] = (kinds[row.kind] or 0) + 1
                names[row.kind] = row.name
            end
            assert(kinds.views, "the pane still groups under Views")
            assert(kinds.cross_section == 1, "the view is a row")
            assert(kinds.section_plane == 1,
                   "the cutting plane is its own row, got " .. tostring(kinds.section_plane))
            assert(names.section_plane == "Cutting plane",
                   "unnamed planes get a default name, got " .. tostring(names.section_plane))

            bearcad.select{ kind = "section_plane", index = 0 }
            local sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "section_plane",
                   "a cutting plane is selectable")
            bearcad.set_name({ kind = "section_plane", index = 0 }, "Front cut")
            assert(bearcad.get{ kind = "section_plane", index = 0 }.name == "Front cut")

            bearcad.delete_selection()
            assert(bearcad.count("section_plane") == 0, "and deletable")
            assert(bearcad.count("cross_section") == 1, "deleting a plane leaves its view")
        "#,
        );
    }

    /// #1686: scripts read and switch the workbench the app is in.
    #[test]
    fn lua_workbench_reads_and_switches() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            assert(bearcad.ui.workbench() == "model", "a fresh document is on the model")

            bearcad.rect{ width = 10, height = 10 }     -- opens a sketch implicitly
            assert(bearcad.ui.workbench() == "sketch", "drawing a rect is sketch work")

            bearcad.cross_section{ name = "Front" }
            assert(bearcad.ui.workbench() == "view", "a new view opens its workbench")

            bearcad.ui.workbench("model")
            assert(bearcad.ui.workbench() == "model", "and you can leave it")

            bearcad.ui.workbench("view")
            assert(bearcad.ui.workbench() == "view", "and come back to it")

            bearcad.drawing{}
            assert(bearcad.ui.workbench() == "drawing", "a new drawing opens its own")

            local ok = pcall(bearcad.ui.workbench, "spiral")
            assert(not ok, "an unknown workbench should error")
        "#,
        );
    }

    /// #1671: `bearcad.cross_section{ name? }` adds a cross-section view — a saved way of
    /// looking at the model — which reads back like any other element.
    #[test]
    fn lua_cross_section_creates_a_named_view() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            assert(bearcad.count("cross_section") == 0, "a new document has no views")
            local i = bearcad.cross_section{ name = "Front half" }
            assert(i:kind() == "cross_section", "cross_section returns a handle, got " .. tostring(i))
            assert(i:index() == 0, "the first view is 0, got " .. tostring(i:index()))
            assert(bearcad.count("cross_section") == 1)
            local v = bearcad.get{ kind = "cross_section", index = 0 }
            assert(v.name == "Front half", "name read back: " .. tostring(v.name))
            assert(v.cuts == 0, "a fresh view cuts with nothing yet")

            bearcad.cross_section{}
            assert(bearcad.count("cross_section") == 2)
            bearcad.select{ kind = "cross_section", index = 1 }
            local sel = bearcad.selection()
            assert(#sel == 1 and sel[1].kind == "cross_section", "a view is selectable")
            bearcad.set_name({ kind = "cross_section", index = 1 }, "Top half")
            assert(bearcad.get{ kind = "cross_section", index = 1 }.name == "Top half")
            -- still selected from above
            bearcad.delete_selection()
            assert(bearcad.count("cross_section") == 1, "and deletable")
        "#,
        );
    }

    /// #108: `bearcad.ui.elements_view(...)` drives the Elements pane's layout mode.
    #[test]
    fn lua_elements_view_sets_hierarchy_view_mode() {
        let state = run_lua(r#"bearcad.ui.elements_view("graph")"#);
        assert_eq!(
            state.hierarchy_view_mode,
            crate::hierarchy::HierarchyViewMode::Graph
        );
    }

    /// #1670: the Graph view is one node per line, and scripts can read that layout back —
    /// the row order, the lane each row's dot sits in, and the lines between rows.
    #[test]
    fn lua_elements_graph_reports_one_row_per_node() {
        run_lua_expect_ok(
            r#"
            bearcad.new()
            bearcad.rect{ width = 20, height = 10 }
            bearcad.extrude{ polygon = {0, 1, 2, 3}, distance = 5 }

            local g = bearcad.ui.elements_graph()
            assert(#g.rows > 0, "the graph has rows")
            assert(g.lanes >= 1, "at least one lane")

            local row_of = {}
            for i, row in ipairs(g.rows) do
                assert(type(row.name) == "string", "row " .. i .. " has a name")
                assert(type(row.lane) == "number", "row " .. i .. " has a lane")
                assert(row.lane < g.lanes, "lanes are within the reported count")
                row_of[row.kind] = row_of[row.kind] or i
            end
            assert(row_of.sketch and row_of.extrusion and row_of.body, "sketch/extrusion/body rows")
            assert(row_of.sketch < row_of.extrusion, "a sketch sits above the extrusion it feeds")
            assert(row_of.extrusion < row_of.body, "an extrusion sits above the body it made")

            local related = 0
            for _, e in ipairs(g.edges) do
                assert(g.rows[e.from] and g.rows[e.to], "edges name rows")
                assert(e.from < e.to, "lines run downward")
                if e.kind == "related" then
                    related = related + 1
                    assert(g.rows[e.to].kind == "constraint", "only constraints tie sideways")
                else
                    assert(e.kind == "parent" or e.kind == "dependency",
                           "the other lines are inputs, got " .. e.kind)
                    assert(g.rows[e.to].kind ~= "constraint", "a constraint is nobody's child")
                end
            end
            assert(related > 0, "the rectangle's constraints tie to the lines they hold")
        "#,
        );
    }

    /// #1764: scripts can ask the graph to include shadow bodies, and descendants pack
    /// left into unused columns instead of drifting right of a busy trunk.
    #[test]
    fn lua_elements_graph_packs_left_with_shadow_bodies() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/issue_1764.json");
        let path_s = path.to_string_lossy().replace('\\', "\\\\");
        run_lua_expect_ok(&format!(
            r#"
            bearcad.open("{path_s}")
            local g = bearcad.ui.elements_graph{{ shadow_bodies = true }}
            local lane = {{}}
            for _, row in ipairs(g.rows) do
                lane[row.name] = row.lane
            end
            assert(lane["Sketch 1"] == 0, "Sketch 1 packs to the far left, got " .. tostring(lane["Sketch 1"]))
            assert(lane["Slice 0"] == 0, "Slice 0 packs left, got " .. tostring(lane["Slice 0"]))
            assert(lane["Body 4"] == 1, "Body 4 sits in the second column, got " .. tostring(lane["Body 4"]))
            assert(lane["Body 5"] == 1, "Body 5 shares that column, got " .. tostring(lane["Body 5"]))
            assert(g.lanes <= 2, "unused left columns are not wasted, got " .. tostring(g.lanes))
            "#
        ));
    }

